local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["119:168497577"]="이제 더 좋아할지도 몰라 새 친구랑 여기 앉아있으면 좋겠어"
rows["119:1770283830"]="$p넌 프로 꽃집자처럼 이 꽃을 뽑아냈어"
rows["119:1772894382"]="기억해두세요. 제가 주문을 외우는데 집중하려면 그대의 도움이 꼭 필요해요. 목적을 달성할 때까지 몇 차례 도움을 청할 테니 준비하고 계세요."
rows["119:1795820643"]="만약 당신이 맨티드에 대해 너무 궁금하다면, 클라시스베스로 가는 길에 더 많은 것을 알려줄게.$B$B그렇지 않으면, 내 일에 맡겨라."
rows["119:1808228975"]="광산에 도움이 되는데 감사할 만큼은 없는데 광산업자들이 다시 일하도록 설득하는 문제야"
rows["119:1810631810"]="첫 번째 조각은 호드 폭풍의 분노라는 무기가 여기까지 오지 않았습니다."
rows["119:1810927472"]="이러한 방법이 형제님께 분명한 길이 아닌 것 같다는 사실을 압니다만, 성스러운 빛에 더 가까이 다가가게 해 줄 겁니다. 잘 싸우세요, 형제님."
rows["119:1813070694"]="...탈주민들은 테라모르를 찾고 있어 시민들이 하루 종일 자유롭게 자그롤할 수 있는 곳이야?"
rows["119:1830392905"]="이 대장님도 보답해 줄 수 있어"
rows["119:1833729839"]="호드는 명예와 전쟁에 관한 것입니다. 저는 이 약사가 하는 일에 대해 명예로운 것은 없다고 확신합니다."
rows["119:1847233552"]="타들라 오버룩, 배틀스카밸리, 스톤탈론 피크 또는 타들라 그로브로 돌아가면 히포그리프가 떨어질 거야!"
rows["119:1869649501"]="난 네 능력에 의문을 품지 않지만, 네가 내게 맡겨진 일을"
rows["119:1885723172"]="|TInterface\\Icons\\spell_fire_selfdestruct.blp:20|t%s 후반 및 캐스트 |cFFFF0000|Hspell:77982|h[Searing Flame]|h|r!\010"
rows["119:1888165750"]="스톰스타우트, 파다리아 섬에서 떠돌아다니는 스톰스타우트가"
rows["119:190411300"]="우린 큰 골짜기가 우리들을 기다리고 있지만, 그 잔 밑에 집중해서 볼 수 없어"
rows["119:1904570439"]="그 척후병이 설마 보르타크는 아니겠지요? 그가 무자비하다는 소문은 저 같은 사람도 들어 봤다고요. 그가 저를 붙잡으려고 하나요?"
rows["119:1917127341"]="이제 하이달 산에 맞춰서 시간 동굴로 이동할 수 있어"
rows["119:1952806155"]="잘 싸우는구나, 작은 이여. 지금은 내가 졌다. 장담하건대 우리는 다시 만나리라. 그때는 내가 좀 더 나은 모습을 보여주리라!"
rows["119:1967942191"]="럭터그 보너스가 없으면 산에 야크를 타고 갈 수 없어!"
rows["119:1972461884"]="도시의 주요 응급센터인 First to Your Aid은 대라란 북서부 마구스 무역 거래소에 위치하고 있습니다."
rows["119:197620747"]="케르사이 더스크싱어가 실종된 우리 형제와 자매들에게 저지르고 있는 사악한 짓거리를 끝낼 방법을 찾아야 합니다!"
rows["119:1982959025"]="우리 경비자들은 이 새로운 땅으로 왔을 때부터 많은 위험에 직면해 왔습니다."
rows["119:2004083277"]="헤드리스 하스마인의 마음은 치매로 지쳐져 있습니다."
rows["119:2011056774"]="이 거대한 성당은 몇 년 전에 이 땅에 살았던 밤 엘프들에 의해 지어졌습니다.$B$B어떤 비밀이 담겨있을까요?"
rows["119:2020660498"]="마법을 발견할 거 같은데, 이 때문에 문제가 생기지 않는 게 좋을 것 같아요."
rows["119:202921409"]="오크나 오그르의 맥주를 정말 마실 수 있을까?"
rows["119:2035374062"]="흠, 이제 다시 일하러 가야겠군. 역시 잠깐 쉬고 나니 좋구먼. 썬더 에일 맥주는 언제 마셔도 늘 맛있단 말이야!"
rows["119:2056262220"]="베인, 우린 네 지원이 필요해 오그리마 대재난 이후 강화될 수 있습니다."
rows["119:2072174712"]="우리 마법사들은 에크소다르에 하루를 보내고 여러 프로젝트를 진행하고 있습니다."
rows["119:2074720675"]="내 아버지와 아버지의 아버지는 이 동상을 위해 평생을 노력했습니다. 저는 그 동상이 완성될 수 있는 사람이라는 자랑스러운 일이었습니다."
rows["119:2089595272"]="도망갈 생각은 꿈에도 하지 마라, 이 뒤틀린 드레나이 쓰레기들아! 침입자들을 해치우지 않으면 지옥보다도 고통스러운 운명을 안겨주겠다!"
rows["119:2096608175"]="이 존재의 시험에 방해를 당할 용기가 있으신가요? 전투는 혼자 치러야 합니다."
rows["119:2131777023"]="미스트! 다시는 못 보게 될까봐 두려웠어! 그래, 난 괜찮으니까 걱정하지 마. 하지만 너는 좀 쉬어서 건강을 회복해야 해."
rows["119:2135240948"]="|TInterface\\Icons\\ability_mage_worldinflames.blp:20|t%s는 캐스팅을 시작한다 |cFFFF6600|Hspell:99171|h[Engulfing Flames]|h|r!"
rows["119:21443283"]="내가 마을로 돌아가서 구매자를 찾을 수 있는 시간을 찾으면 그 유적들이 많은 금을 가져오게 될 거야"
rows["119:225881317"]="만약 여러분이 정말로 우리 땅에 행한 모든 것을 해제하고 싶다면, 먼저 우리 학교에서 자신을 증명해야 합니다."
rows["119:256883114"]="알렉스스트라스자에게 아직 삶의 순환이 준비되지 않았어."
rows["119:260482097"]="호디르의 이 모형은 아랑그림 왕과 그 외의 모든 사람들이 번개의 전투에서 잃은 것을 기념하는 기념물로 세워져 있습니다."
rows["119:265820676"]="모고, 마티드, 그리고 얼라이언스 모두 이 고대 장소의 안전을 위협합니다. 우리는 그것을 어떤 대가를 치르더라도 보호해야 합니다."
rows["119:282099300"]=" ⁇ 커스 섬유소에서 로렌스 슈나이더와 이야기해봐요"
rows["119:286817623"]="필멸자여, 므우루의 심장을 들여다보게! 흠집 하나 없지 않은가. 천지창조의 그 순간처럼, 만물을 생성하는 빛에 정화된 것이라네."
rows["119:287472299"]="조르겐슨과 함께 눈에 띄지 않게 지나갈 수 있도록 방해를 만들어라|TInterface\\Icons\\ABILITY_ROGUE_BLOODYEYE.BLP:16|t\010"
rows["119:300152380"]="이게 마나 오일일줄은 상상도 못했소! 수요가 엄청날 것이오. 물론 그렉은 빼고 말이야!"
rows["119:333751774"]="몇 번의 싸움은 힘으로만 이길 수 있습니다. 결국은 현명한 능력, 반사, 무기에 대한 지식이 승리합니다."
rows["119:363485924"]="더 중요한 것은, 챔피언이 당신을 떨어뜨리지 않을 것입니다."
rows["119:370465244"]="번개는 번개 채널의 급격한 열성 확장으로 인해 공기 중에 충격파가 시작됩니다!"
rows["119:394766311"]="기적의 작품에 오신 것을 환영합니다!$B$B잠시만 가게를 둘러보세요. 어린이나 늙은 사람들을 위한 멋진 장난감들이 있습니다."
rows["119:407116375"]="아니, 하지만 당신은 저쪽의 지구맨더 도로스와 이야기 할 수 있습니다. 큰 드레네이, Twilight 캠프에서 남은 것을 보고."
rows["119:410792586"]="암흑 철자들은 이 태블릿들이 암호화된 것이라고 생각했지"
rows["119:427287624"]=" ⁇ ,  ⁇ , 젠장,  ⁇ , 잘했어, 내가 가로쉬에게 네 이름을 추천해줄 거야"
rows["119:428379824"]="이  ⁇ 은 밤 엘프들을 여기서 볼 수 있어! 내가 커지면, 전사들이 그랬듯이 전쟁 대장에게 싸우고 싶어요!"
rows["119:43263165"]="우리 주인의 위대한 부활에 함께 노력해야 합니다. 오직 그분만이 모든 사람들에게 영원한 평화를 가져다 줄 수 있습니다."
rows["119:450449916"]="화이트 파운을 찾기 위해서는 우리 민족의 고대 마술을 이용해야 합니다."
rows["119:467322858"]="그럼 델먼 슬레이트피스트와 얘기하고 싶으세요 스톰윈드 계속"
rows["119:492578288"]="여기가 우리가 있는 곳이 아니냐?$b$b같은 생각을 가진 사람들과 함께 탐험되지 않은 세계 각지를 여행하는 것?$b$b더 좋은 방법은 무엇일까요?"
rows["119:522296418"]="표면에는 약간의 활동만 있지만 태양은 올바른 곳에 있습니다."
rows["119:523209262"]="이러한 교의대로 행동하는 일은 이 세상을 우리 모두가 감사할 수 있는 곳으로 만드는 데 도움을 줍니다. 명예와 정의의 세상을 말이죠."
rows["119:532724512"]="이제, 겁이 나지 마 용감한 영웅들이 지금 싸우고 있어 내가 여기 있는 동안"
rows["119:543922157"]="이 유적들은 귀신들이 있다고 합니다. 하지만 저는 귀신들을 믿지 않습니다. 그리고 다시 말해서, 저는 잔다라리도 믿지 않았습니다."
rows["119:554709058"]="우리 아래의 거시들을 보세요. 황후는 너무 일찍 스와임을 명령합니다. 그녀의 혼란스러운 환상의 또 다른 징조입니다."
rows["119:583288021"]="깨끗한 야크가 있는 게 행운이 더 많고, 제 특별한 맥주로 먹이는게 더 큰 행운이"
rows["119:612566468"]="또 다른 화학자, 네 능력은 내 기술만큼 크지 않을 수 있어"
rows["119:628428198"]="안두인 왕자와 함께 없었더라면 우린 서로 반란을 일으키고 분노가 우릴 지배할 수 있었을 거야"
rows["119:638989312"]="끄아악! 바보 같으니라고! 무슨 짓을 한 거야?! 저 녀석 미쳤군! 해치를 닫아라! 돛대를 올려! 아아아악! 모두 자기 위치로!"
rows["119:648639732"]="대족장님께서 아라지우스의 목에 상금을 걸었다! 지금부터 아무짝에도 쓸모없는 그 쓰레기 같은 악마는 척살 대상 1호이다."
rows["119:674921512"]="발티온의 알스다르와 다른 전사 훈련자들은 발기소 근처에서 파스트라이더스 광장으로 내려다 볼 수 있습니다."
rows["119:700327099"]="네가 필요하다고 느끼니? 내가 명령하기 전에 네가 필요해"
rows["119:702693426"]="난 할 일이 많고, 휠러는 내 일을 안 해"
rows["119:714378794"]="네, 달아! 모든 걸음으로 심장이 빨라지고 있습니다. 부딪치는 소리도  ⁇ 고 울리는 소리도 거의 귀가 들리지 않습니다."
rows["119:721167206"]="내가 여기 없는 것처럼 말 마, 난 배고프고 이 끔찍한 냄새가 나는 옷을 벗어야만 해요!"
rows["119:722247630"]="우리 모두에게 힘들었지만 잘 풀려나가고 있어요$B$B그냥 팔을 펴고 해야 할 일을 해야만 해요"
rows["119:723946199"]="네, 우린 큰 걸음걸이를 해냈어, 해안 곳곳에 석유가 있습니다."
rows["119:732231386"]="|TInterface\\Icons\\spell_priest_divinestar_shadow2:20|t%s는 |cFFF00000|Hspell:137350|h[Shadowed Loa Spirit]|h|r!"
rows["119:750082478"]="어쨌든 토타르는 남서쪽 구석에 있는 동굴에서 태양으로부터 숨어있다고"
rows["119:767023335"]="오스틸 드 몬의 주 식실 안에 들어가보세요."
rows["119:801115654"]="지난 몇 주 동안 지진이 얼마나 많았는지 알 수 있겠지만"
rows["119:827208659"]="알갈론이 도착하기 전에 이 자리에 왔어요"
rows["119:847236541"]="메이슨의 미련한 곳에 다시 만나면 내가 준비한 것에 놀라게 될 거야"
rows["119:851293005"]="너희가 내게서 가르침을 받으러 왔으니 내가 너희에게 은혜를 구하노니 그것을 행하라 그리하면 보상을 받으리라"
rows["119:85428444"]="나무의 곡선에서, 해가 뜨는 빛의 색깔, 심지어는 전사의 웅장한 검의 완벽한 물리적 형태에서도."
rows["119:85647355"]="아이스펀그는 수많은 전투를 겪어왔어요$b$b그녀의 무장 부족이 당신을 속이지 않도록 해"
rows["119:872461356"]="무장영의 판은 전사 테라스에서 전사와 함께 훈련하고, 나머지 트레이더 계층을 내려다보며"
rows["119:893765992"]="우리 아름다운 도시에서 우편 상자가 풍부합니다. 로얄 거래소 은행에 있는 상자는 확실히 여러분의 필요에 적합합니다."
rows["119:900816080"]="주의 하십시오. 루나 에서 너무 오래 떨어져 있거나 여러 번 연속으로 폭발을 당하면 다시 시작해야 합니다."
rows["119:922048211"]="물론, 물론, 우리 마을에 광업 훈련자가 있어요."
rows["119:932824818"]="그리고 무엇보다도, 내가 어떻게든 당신과 함께 부딪히게 되는데, 바로 그 사람이 처음엔 내 직장을 잃게 해줬어요!"
rows["119:935415127"]="|TInterface\\Icons\\ability_mage_firestarter.blp:20|t 강렬한 바람은 |cFFFF0000|Hspell:99794|h[불의 전사]|h|r!"
rows["119:958452023"]="그럼, 네 귀여운 타우렌의 시체를 비워봐요. 하지만 난 너의 눈물이 그를 돌아오게 하지 않을 것이라고 확신한다."
rows["119:969443596"]="서부 프로스트울프 타워는 프로스트울프 마을과 프로스트울프 케이프 사이의 게이트를 보호합니다.$B$B호드에 의해 통제됩니다."
rows["119:975076073"]="넌 위험하지 않았어, 내 친구들이 널 잡았겠지"
rows["119:979101966"]="이곳 주민들은 정말 이상적인 생활습관을 가지고 있습니다. 그래서 저는 바닥을 내려놓고  ⁇ 을 들고 가봐야겠어요?"
rows["119:990572297"]="불타는 촛불이 보이시나요? 판다렌 유물에 대해 말해줄 수 있을 때까지! 이제 이야기 시작하세요!"
rows["11:1001198926"]="그들을 꺾어라!"
