rows["120:1113528640"]="우리 세 영웅은 코보에게 파괴의 아레나는 단지 원숭이 사업이 아니라는 것을 보여주었습니다."
rows["120:1123484184"]="안녕하세요. 저는 크로노스입니다. 절대 잊지 않는 사람입니다. 기억은 결함이 없고, 아주 작은 세부사항까지 정확하게 기억합니다.$B$B- 믿어요"
