rows["120:1179086228"]="엄청난 규모의 지진이 일어난 후, 당신이 가장 원하는 곳은 실내에서야 한다고 생각하겠죠?"
rows["120:11910623"]="우리 형제들, 피의 엘프들이 그들의 길을 바꿀 수 있다면 레지옹을 다시 우리에게 데려올 수 있었으면 좋겠다"
rows["120:119682191"]="감시의 언덕 근방을 여행하시는 분들을 위해 여행용품을 판매합니다! 한번 와보시라니까요!"
rows["120:1204043792"]="마지막으로 아주 커다란 전리품 자루라오! 사과를 8개나 채울 수 있을 정도로 크지! 8개란 말이오, 에드! 믿어지오?"
rows["120:1205536905"]="자, 감시의 언덕에 이 유명한 안토니오 페렐리가 왔습니다. 곧 떠나야 하니 어서들 와서 구경들 하세요."
rows["120:122777695"]="펠 코네스는 펠 마법을 통해 이름 붙여진 것입니다."
rows["120:1234324837"]="배신자다운 최후구나... 가자, 노예들을 해방하고 리치 왕의 방에 무엇이 있는지 직접 확인해야 한다."
rows["120:1238644249"]="여보, 그럼 어쩌자는 거요? 다른 방법이 없잖소. 그들이 알면 우리 둘 다 처형하고 말 거요."
rows["120:1304520308"]="내가 그 때까지 뭘 해야겠어? 난 남자들이 없어! 우린 호드들이 어디에 있는지, 얼마나 많은 놈들을 가지고 있는지도 몰라!"
rows["120:1308467159"]="제 남편, 우리 왕이 다시 우리와 함께 할 때가 왔어"
rows["120:1318163976"]="난 이 얘기에 대해 아무 말도 안 돼, 하지만 너한테 잘 된 왜성 덩어리 좋아진다고 말하는 얼굴이 있어"
rows["120:1345519636"]="그럼 역사에 대한 지식을 시험해 보겠습니다. 리프스나르는 워겐이 되기 전에 가족이 있었습니다. 그의 아내의 이름은 어땠을까요?"
rows["120:1372340878"]="이 마을을 준비하는 것은 단지 무기를 손에 넣는 것만이 아니라"
rows["120:1383814442"]="어서 여기 오래 걸리면 모든 것을 볼 수 있을거야 한 번 다리와 팔이 있는 화랑을 봤어"
rows["120:1409244397"]="이 농장은 우리 가족 중 한 세대 였지만 어떻게 포기할 수 있을까요?"
rows["120:1414941904"]="그대는 이 검을 고대 신의 피, 사로나이트로 벼려냈네. 리치 왕의 힘이 이 검을 부른다네."
rows["120:1421591140"]="난 이제 내가 어떻게 된 지 알 수 있어 의심과 분노로 인해 너무 무겁게 되어서 평생 두려움의 노예가 되고 싶었지"
rows["120:1443449481"]="노즈도르무의 자녀들아, 시간을 헤아릴 수 없고 우리도 많아요."
rows["120:1447923436"]="이리던, 화살이 없어 달의 여신여 어둠으로부터 우리를 보호해줘"
rows["120:1470242144"]="당신이 서 있는 모습에서 볼 수 있듯이 당신은 전사가 아닙니다.  $B$B왜 안 가서 안전한 일을 해봐요? 책 읽으세요."
rows["120:1471906507"]="너의 불타는 시체는 내 영역에 침범하는 어리석은 자들이 어떻게 되는지를 보여주는 계기가 될 것이다!"
rows["120:1492349950"]="내 계산에 따르면, 충분한 인원이 한꺼번에 징을 울리면 이 문을 막은 봉인이 깨져 안으로 들어갈 수 있을 거요."
rows["120:1527100318"]="어둠골의 주민들은 의회가 좀 더 적극적인 조치를 취하기를 바라고 있습니다. 우리를 괴롭히는 이 부정한 침략에 그들이 고통받도록 내버려 둘 순 없습니다."
rows["120:1527808525"]="노스렌드 오버로드 헤일스크림의 관심은 필요합니다 리치 왕 그리고 당신의 도움 없이 그의 하인들도"
rows["120:1531400649"]="저는 이 아이디어를 가지고 있습니다. 이번에는 해군 전투를 겪지 않도록 해 얼라이언스 그리고 호드.$B$B그냥 말만 하고 있어요"
rows["120:1542379503"]="브롤가르 참전용사들은 블라트를 기억할지도 모릅니다. 자기 자신을 재현하는  ⁇ 이요. 오늘날 우리는 그의 더 악하고 더 못생긴, 큰 여동생을 만나게 됩니다."
rows["120:1561247898"]="타들라 호버룩이나 배틀스카밸리로 돌아오지 않으면 다르나시아의 칼포 투사에서 제거될 것입니다."
