rows["120:1595565092"]="겨울 할아버지는 겨울맞이 축제 기간 동안 오그리마의 나무 아래 있는 모든 사람들에게 선물을 주신답니다. 올해에는 어떤 선물을 주실지 궁금하군요."
rows["120:1605234906"]="이 요새는 가로샤르보다 더 어렵게 잡을 수 있을 겁니다. 하지만, 일찍이 또는 늦게 그들은 깨질 것입니다. 호드은 항상 깨집니다."
rows["120:1616597305"]="전쟁에서 많은 친척들을 잃었기 때문에, 예, 도시는 예전처럼 활발하지 않을 수도 있습니다."
