rows["120:1635469925"]="우리가 마지막으로 보았을 땐, 네 녀석이 유리했다. 성스러운 땅에서 싸웠기 때문이지. 하지만 이번엔 상황이 뒤바뀌었다는 걸 곧 알게 될 것이다..."
rows["120:1642149670"]="이 포털들은 다라란으로 연결돼 있어 키린 토르가 호드 이 잔인한 행위를 저지르세요."
rows["120:1645224952"]="시간이 있다면, 그림클라와 그의 주인 볼코르는 당신의 도움이 필요할 것입니다."
rows["120:1671215748"]="내가 지금 보여준 것들은 볼타루스 밖에서 절대 말하지 않아야 돼"
rows["120:1691719270"]="안녕하세요, 저는 비디케이터 팔나아르입니다. 빛의 여행 paladin]"
rows["120:1693536548"]="피의 엘프들은 코루네 모구와 싸우기 위해 준비되지 않았어."
rows["120:1703155615"]="이 땅의 영들은 더 이상 이 어두운 마법과 악의적인 희생을 용납하지 않을 것입니다.$B$B비레브랑크가 가야 돼!"
