rows["120:1723292095"]="'더크월 페어'는 지금 멀고어, 남서쪽 썬더 블러프놓치지 마세요!"
rows["120:1731975728"]="테일러는 야만 짐승처럼 그 똥과 싸웠고$B$B하지만 결국 그는 극복되었습니다."
rows["120:1735296275"]="그들은... 동의했나요?! 환상적이네요! 대단히 감사합니다! 그들의 축복으로 우리는 전국의 가장 행복한 판다레인이 될 수 있습니다!"
rows["120:1741808554"]="고마워요, 영웅님, 괜찮다면, 저는 당신 옆에 서서 제 납치자들에게 복수를 요구하고 싶습니다!"
rows["120:1749894807"]="부탁할게 있어 내 친구에게 보상을 해주면 안 돼 아이언포지."
rows["120:1758876471"]="이 뒤틀린 드레나이 녀석들을 가루로 만들어 버려라, 일리다리! 이 버림받은 땅에 쓸만한 물건이 있다면 우리가 찾아낼 것이다!"
rows["120:1760384972"]="베토드는 위대한 전사였지만, 충분히 훌륭하지는 않았다고요."
rows["120:1775107728"]="|TInterface\\Icons\\spell_nature_healingwavelesser.blp:20|t 가랄론 |cFFFF0000|Hspell:123495|h[만드스]|h|r 그의 한 다리!"
rows["120:179691470"]="그리고 류랑은 대나무 숲으로 올라갔고, 그는 항상 모험에 가지고 다니는竹의 우산을 들고 갔다."
rows["120:1808366277"]="난 너랑 공평하게 싸워야 했는데 친구도 데려오기로 결정했어"
rows["120:1824513117"]="저들이 전투 규칙을 반드시 준수하도록 지켜보겠습니다. 관람석의 두 분을 보면 모두 힘을 얻을 것입니다."
rows["120:1830229136"]="마직 마네게리 는 다라란 북동쪽에 위치 하고 있으며, 반려동물 의 물품, 이국적 인 산, 그리고 양궁 이 모두 이 곳 에서 사용 가능 합니다."
rows["120:1890798505"]="잘 됐군. 내 군단에게 먹일 보잘것없는 벌레들이 제시간에 도착한 것 같구나. 어서 오너라, 나약한 생명체들아!"
rows["120:1894151006"]="보물을 가져오는데 먼 곳으로부터 온 보물들이 산을 넘어 온 보물들이 벽을 넘어온 보물들이기도 합니다."
rows["120:1910659977"]=" ⁇ 을 찍고, 애모를 보고 공격할 준비가 되면 신호를 내세워"
rows["120:1924627320"]="저나크가 그런 설명에 맞을 것 같아 왜 다라나르의 숙소로 가서 얘기하지 않는가?"
rows["120:192603687"]="어릴 때, 길윈, 우리는 트롤이나 무르록이나 여자들과 싸우는 척 하는 하루 종일 보냈지"
rows["120:1927737219"]="이 검의 모양이나 무늬는 용이 벼려낸 검임을 암시합니다. 마침내 해답을 얻은 셈이군요."
rows["120:1937687620"]="제 딸, 시간이 되면 알게 될 거야. 나와 함께해."
rows["120:1939188418"]="이도니스, 진정하세요. 경솔한 행동은 아무런 도움이 되지 않아요! 휴식을 좀 취하고 나서 마나 수정구를 사용해 보세요. 기분이 한결 좋아질 테니까."
rows["120:194294976"]="체인 삼촌과 저는 주간 그 자이드 숲을 돌아다니며 나무와 한 마리  ⁇  뱀만 봤어요"
rows["120:1968486039"]="그럴지도 모르지. 이 계획이 효과 있을지 의심스럽소. 최후의 공격을 펼칠 군대를 준비하는 게 나을 텐데."
rows["120:1971612952"]="이 군대는 이제 막 행진을 시작했고, C'Thun의 군대가 이 세계를 파괴할 것입니다."
rows["120:1978712081"]="좀비들은 괴물이든 아니든, 빛의 눈에는 혐오스럽고, 게다가, 이들에게는 이익이 없다.$B$B아직은 아니죠"
rows["120:198287203"]="악당의  ⁇ 스피스트가 디저트를 받았다는 게 너무 기쁘네요."
rows["120:2001242192"]="네가 떠나서 공격한 건데, 아드미랄은 살아남지 못했고 나머지는 동굴로 물러났고, 너도 똑같이 해야겠어."
rows["120:2001348468"]="내가 알았던 것처럼 효과가 있었지!$B$B하지만 그럼에도 불구하고, 정지증의 영향은 내 원래 계산을 뛰어넘어버렸습니다."
rows["120:2008534970"]="우린 전쟁의 절벽에 있습니다. 군대가 순서대로 되면 신호를 보내면 공격 명령을 내린다."
rows["120:2011805764"]="그들이 나를  ⁇ 버에 잠자리 내기 전에, 나는 무리의 백만 개의 목소리를 내며 내 이름을 외쳤다. 이제, 난 침묵을 듣는다."
rows["120:2037699278"]="기회는 다가오고 있습니다. 시간 없는 섬은 당신의 담요의 잠재력을 최대한 발휘할 열쇠를 가지고 있다고 믿습니다."
