rows["121:2053017956"]="내가 지난번 당신을 데려갔을 때, 7성자 신당에서 어떤 종류의  ⁇ 이 우리 병사들에게 감염된다고 들었습니다."
rows["121:2055008986"]="살육자가 다가오고 있다! 명심하라. 어떤 경우에도 절대 투기장을 떠나서는 안 된다. 투기장을 떠나면 너와 네 전우는 실격될 것이다."
rows["121:2062458008"]="너희 둘 다 실패한 놈들이야 하지만 상관없어 우리 편에  ⁇ 주님이 있다면 보병이나 용이 필요 없어"
rows["121:2071146937"]="배달 서비스에서 무슨 일이 일어나고 있어요? 우편이 언제까지나 도착하지 못하면 어떻게 작동해야 할까요?"
rows["121:2094201086"]="만약 이것이 아르헨티나 오브의 무기로 기대할 수 있는 품질이라면, 그들이 떨어지는 것은 단지 시간 문제일 뿐입니다."
rows["121:2132706755"]="문 앞에 있는 건물을 무너뜨릴 수 있으면 안으로 들어갈 수 있을 겁니다"
rows["121:249971153"]="이곳의 전투는 전 세계에서 벌어지고 있는 스컬지의 침공의 극히 일부일 뿐이다, 바보 같은 놈! 진정한 힘이 어떤 건지 가르쳐주마!"
rows["121:265466791"]="우리 아버지가 만든 청춘수욕장들을 찾았을지도 몰라요"
rows["121:270173334"]="하지만 항상 기억하세요 우리 운동은 순수해지지 않을 수 있습니다. 여러분 중 몇몇 배신자들이 여전히 숨을 쉬고 있다면요.\010"
rows["121:273910455"]="근대화는 핵심입니다. 손잡이와 레버로 당신은 정상적인 활을 끌어내는 오그르의 힘으로 이 아기를 발사할 수 있습니다."
rows["121:301144845"]="|TInterface\\Icons\\INV_Misc_Food_Vendor_PinkTurnip.blp:64:64:100:0|t$b$b ⁇ 니 여자들이  ⁇ 에 대해 뭘 하고 싶습니까?"
rows["121:303969444"]="당신 심정, 땅과 민족에 대한 사랑으로 이곳을 오게 된 것은 당신의 무기와 무기도 아니었다."
rows["121:30992826"]="희망 따위는 버려라! 오래전 시작한 계획을 마무리하고자 불타는 군단이 돌아왔다. 이번엔 절대 피할 수 없다!"
rows["121:310563739"]="고르, 네가 어린아이처럼 느껴지지 않을 때 나와 함께 나가서 강제범죄를 시작해봐"
rows["121:312211362"]="로타르의 아들들은 끝없는 전쟁을 벌이고 있습니다."
rows["121:31601498"]="들어봐!$b$b내가 아는 모든 걸 말해줄게, 하지만 먼저 날 이 야만과 그들의 살인 곰으로부터 구해야 해$b$b거래?"
rows["121:317739892"]="경기 시작합니다! 척 보기에도 날렵한 고블린 자동차가 우승할 것이 분명합니다! 경주가 시작되기 전에 어서 어서 돈을 거십시오!"
rows["121:323270890"]=" ⁇ 을 줄일 준비가 되셨나요? 이것은 조금 찌르고 불타게 될 수도 있습니다. 하지만 고통과 진동은 빨리 지나갈 것입니다."
rows["121:343287806"]="숙련된 광부들이 전염병으로 인해 지네아스를 탈출하고 이리로 왔습니다."
rows["121:343297469"]="|TInterface\\Icons\\ability_whirlwind.blp:20|t Foe 수확자 5000는 활성화되기 시작합니다 |cFFFF0000|Hspell:88481|h[Overdrive]|h|r!"
rows["121:348910878"]="미란다, 당신은 높은 명성을 가진 모험가들에게 제공하는 상품의 인지도를 말해 줄 수 있을까요?"
rows["121:361110211"]="이런다고 달라질 것 같으냐! 주인님께서 널 가만두지 않을 것이다! 피의 강에서 허우적대라! 세상은 불타버릴 것이다! 으아아!"
rows["121:36353868"]="이 추운 땅은 시원해 보이지만, 이 곳은 많은 비밀이 있습니다."
rows["121:37286263"]="갑옷과 무기 공예인 크라두 그림블레이드와 슐라 슬라그푸리 (Zula Slagfury) 는 하위 도시의 큰 도금에서 일하고 있습니다."
rows["121:379128270"]="또 다른 생존주의자, 네 능력은 내 기술만큼 크지 않을 수 있어"
rows["121:392777479"]="내 배는 이 해변에 착륙하기 위해 박을 당했고, 난 배의 모든 돈들을 지불하도록 하겠습니다."
rows["121:394550858"]="아서스! 네놈과 스컬지의 최후를 보겠다고 맹세했다! 희망의 빛 예배당에서 시작했던 일을 이제 끝내겠다!"
rows["121:395594363"]="내가 자네가면 조심해지, 하이드니르."
rows["121:402375730"]="이런 곳에서 시간을 보내는 것은 좋은 일입니다. 우리는 항상 우리가 지키기 위해 열심히 노력하는 것을 기억해야 합니다."
rows["121:402810371"]="우리는  ⁇ 다라리아 트롤들이 먼 섬에서 왔어요. 왜냐하면 우리는 지금 우리 세계가 직면한 위협을 무시할 수 없기 때문입니다."
rows["121:402983559"]="아윽... 이 고통... 내가 어린애였을 때 학교에서 받은 매질이 이렇게 아팠지..."
rows["121:411543382"]="중화제를 호수에 섞자 수정에 오염된 물이 깨끗해지는 것 같습니다."
rows["121:412873078"]="일부 밀착한 사람들은 여전히 오래전부터 해체된 동맹에 집착할 수 있습니다."
rows["121:415621292"]="우리 도시에 새로운 사람을 신뢰하는 것은 어려운 일이죠."
rows["121:418307351"]="제 두개골은 다리 때린 것 같지만 그렇지 않으면 괜찮아요"
rows["121:427254485"]="많은 사람들이 지상의 반지를 Cenarion Circle와 혼동합니다. ...나는 우리가 \"지상 광장\"이라고 이름을 바꾸어야 한다고 말했다."
rows["121:438673259"]="미란다, 존경받는 명성을 가진 모험가들에게 제공하는 상품의 엠자그니 비용에 대해 말해줄 수 있나요?"
rows["121:448300379"]="우리는 오랫동안 평화 외에는 아무것도 알지 못했고, 우리 해안에 전쟁이 오면 어떤 사람이 어떻게 대처할지 모르겠어요."
rows["121:44937414"]="도전은 받아들여졌어요, 필사자들이 알 아키르, 에리먼트 항공의 주님과 마주하고 있다는 것을 알고 계세요."
rows["121:459063075"]="네, 친구 톤거스한테 말해봐요. 만약 그가 여기 자신의 계산을 처리하지 않는다면, 나는 오래된 스틸헤드와 함께 출연할 거야!"
rows["121:469005597"]="자, 다 고쳤습니다! 속도가 좀 더 빨라지겠지만 너무 많이 충돌하면 차체가 견뎌내질 못할 겁니다."
rows["121:484576069"]="썬더 포지는 근처에 있는 지역을 충전하기 시작했습니다. |cFFFF2222|Hspell:139397|h[Overcharge]|h|r로 직접 달려가십시오!"
rows["121:486431207"]="먼 곳을 볼 수 있는 공기 중에 너무 많은 연기가 있습니다.\010해변에서 아무것도 알아차리지 못해, 그리고 사격은 쓸모없어"
rows["121:491827688"]="사이안은 공감대자라고 의심하지 않았는데, 우리는 이 일에 준비가 되지 않았기 때문이에요."
rows["121:495409309"]="이 씨앗으로 뿌리를 내리고 시간이 지나면, 그리고 주의를 기울이면, 우리는 이 화화롭고 적대적인 영역에서 보호받을 수 있어야 합니다."
rows["121:512194561"]="전기선으로 큰 거리를 지나서 메시지를 보내는데..."
rows["121:52171347"]="외교를 통해 최선을 다했고, 이제 우리는 우리의 행위로만 진주에게 증명할 수 있습니다."
rows["121:533520476"]="지하철과 로딩 도크를 잡으면 도시의 중심에 빠른 공격을 할 것입니다. "
rows["121:536016754"]="해안의 화려한 해안 마을에 오신 것을 환영합니다. 폭발물 열광자들이 만든 도시입니다."
rows["121:546395541"]="하지만 이제 산의 잡을 수 없는 상태이고 해를 입지 못해 안전해"
rows["121:554300370"]="내가 살아 숨쉬는 동안 진짜 트롤이야, 당신은 이야기에서 묘사된 것처럼 보입니다."
rows["121:56629596"]="우리한테는 아니지, 하지만 좋은 친구..."
rows["121:58244833"]="하루에 백 번은 우물까지 가서 물을 길어오는 것 같아. 웃어른을 전혀 공경하지 않는단 말이야."
rows["121:592176524"]="5번부터 세게 되자, 볼진은 이 배에 눌러서 누가 가장 위대한 맥주 마스터인지 결정할 수 있을거야."
rows["121:603655332"]="자, 이번 주에 과연 이 안토니오가 뭘 가져왔는지 와서 보세요. 안 보면 후회할 겁니다. 안토니오가 뭘 가져왔을까요?"
rows["121:616638273"]="너희 역사가 시작되기 전에 우리 제국은 막강했고, 이 세계를 자매 왕국인 아 ⁇ 키라지와 아조엘 네루브와 공유했지."
rows["121:62538414"]="샤만과 드루이드의 방식은 매우 다릅니다."
rows["121:649031647"]="그대가 찾는 정보는... 공짜로 줄 순 없지. 우리가 공통의 적을 노리고 있다는 사실을 먼저 증명해 보이게나."
rows["121:675204078"]="미알은 에크소다르의 수강장이야, 트레이더 레벨의 하위층에서 찾을 수 있어 빛."
rows["121:708456089"]="나가의 수단과 의도를 밝혀줄 수 있을 겁니다"
rows["121:716497495"]="내가 그를 볼 때 샤도 마스터  ⁇ 에게 내 마음을 줄거야."
rows["121:726901399"]="이제 모가들이 타이탄들과 뿌리를 공유한다는 것을 알지만, 아직도 많은 신비들이 남아 있습니다. 왜 그들은 여기 있었는지?"
rows["121:73384682"]="12개의 초점 중심을 만들면 마법의 힘이 보다 충만하게 되어 안정성을 충분히 확보할 수 있을 거예요."
rows["121:744911335"]="여기 있는 마법사들이만 스톰윈드왜 경비원 한 명을 불러 안 들어와 스톰윈드?"
rows["121:7488608"]="누가? 타우렌 족장들이! 무엇을? 실황 공연을! 어디에서? 세상의 끝 선술집에서! 언제? 매시간 정각에! 놓치면? 후회합니다!"
rows["121:771245971"]="여기 북동쪽에 있는 슬러드지 필드에서 문제가 있습니다."
rows["121:795283679"]="왜 고집을 피우는 게냐? 어차피 다 헛된 일... 아직 늦지 않았어! 살 수 있을 때 도망쳐라!"
rows["121:825308743"]="스파크는 몇 년 동안 알고 있었지"
rows["121:829027585"]="바다 건너의 이 엘프들에 대해 어떻게 생각해야 할지 모르겠지만 이 대륙의 타우렌과 엘프는 항상 싸우고 있습니다."
rows["121:846153285"]="네, 일어나라! 이 구석에서 탈출하고 호드를 죽여라"
rows["121:854437324"]="내가 당신에게 거래를 할 수 있었으면 좋겠어요, 파트너 - 정말 그럴게요 - 하지만 먼저 빌그워터 카르텔과 친근하게 지내야 합니다."
rows["121:86113235"]="아이언포지에 대한 무기를 들고 다크 아이언의 이유가 뭐죠?"
rows["121:879094060"]="내가 임금님이었다면 너 같은 말을 데리고 다녔을 거야. 난 절대 널 잃어버리지 않을 테고, 너도 날 절대 잃어버리지 않겠지."
rows["121:883091977"]="첫째, 내가 구출될 필요 없어 둘째, 난 결코 당신 같은 혐오스러운 사람이 나를 구출하지 않을거야!"
rows["121:889227986"]="더 이상 말하지 마, 레오리크 우리 모두는 뼈에 차가운 것을 느끼고 있지만 매일 영웅들이 온 세상과 그 밖의 곳에서 도착합니다."
rows["121:89568442"]=" ⁇ 은 거리 라이트의 음란한 전술에 의존합니다. 함정과 배려요. 슬프게도 말하지만, 그들은 우리를 모든 곳에서 우릴 능가하는 것 같습니다."
rows["121:929166167"]="당신의 이름으로 저들에게 죽음을 선사하겠습니다! 오라, 스컬지의 적이여! 내 너희에게 리치 왕의 강대함을 보여주겠다!"
rows["121:94281498"]="이  ⁇ 츠는 현명한 투자자라는 것을 증명합니다.$b$b지하에 들어가서 충분히 통찰력이 있었기에 다행이군"
rows["121:962839753"]="우린 해냈어, 또 다른 항해를 살아남았어. 하지만 그건 느긋하게 할 이유가 아니야!"
rows["121:96386277"]="넌 진짜 재능과 술조각에 대한 열정이 있어"
rows["121:974405209"]="대제님과 얘기했나요? 그녀는 당신의 관점에서 순례의 이야기를 듣고 싶어합니다."
rows["121:982150498"]="여, 친구들 다시 보니 반갑구먼. 친구들 덕택에 국경 여행이 안전해. 고맙네."
rows["121:984578497"]="스노우드리프 마스터는 어둠 속으로 사라지고 자신만의 두 배의 환상을 만들어내며"
rows["121:986843813"]="몸은 여성 오크 전사의 몸입니다.$B$B분명 전투에서 죽었지 아마 그 지역의  ⁇ 돌에 맞았을 거야"
rows["121:988979637"]="좋은 친구들은 항상 농부 비밀을 공유합니다. 이제 말해봐요, 어떻게 채소를 이렇게 만들 수 있을까요?"
rows["121:989850834"]="녀석도 날 잡으러 온 거요! 나 같으면 좀 더 조심하겠소, 여행자 양반. 녀석이 어느 나무 뒤에 숨어 있을지 모르니까 말이오!"
rows["121:991563465"]="그들은 아래에서 우리의 배를 공격했고, 언제든지 포위대에 진출할 것입니다!\010우린 그들을 막기 위한 숫자가 없어요"
rows["122:1004804900"]="그래. 그 헬스크림 님. 대단한 분이지. 하지만 내 생각엔 자신을 증명하는 데 너무 열중해 계셔. 사울팽 님이 여기 계시니 다행스럽지."
rows["122:1027534953"]="그분께서 네가 나타날 것이라 말씀하셨다. 하지만 난 네 손에 죽지는 않을 것이야. 난 네가 우리 동족들에게 어떤 짓을 해왔는지 안다."
rows["122:1032028174"]="그녀는 새로운 친구를 사귀기 위해 왔고, 그리고 불을 붙여서!"
rows["122:1046051826"]="그쪽은 어깨를 깎아 내렸어, 그루머는 옳았어요."
rows["122:1061683069"]="제발 그 일만은 저지르지 않았다고 말해주세요! 그렇지 않다면 전 당신을 해칠 수밖에 없습니다."
rows["122:1067570791"]=" ⁇ 랑은 평생 세계를 탐험했고, 여기 방황하는 섬에 많은 아이들을 키웠다."
rows["122:1074294629"]="전날 배에 유물을 태우고 있는 걸 봤어요$b$b한 곳에서 본 금이 많았어요!"
rows["122:1078428321"]="미안해, 와이스프스나 캡틴 이외의 다른 사람들과 얘기할 시간이 거의 없어서"
rows["122:1090564606"]="불은 감추고 챔피언들 내 힘의 마지막을 가져가 내가 실패한 곳에서 성공하고"
rows["122:1100698272"]="형, 우린 부서졌어. 그녀가 끝낼 수 있게 해줘"
rows["122:1110943471"]="|cff0000ff급 9:|r \010  빅 바다 부름: $8032w-$8031w\010  니블레: $8034w-$8033w\010  박사 FIST: $8036w-$8035w\010  아후'루: $8038w-$8037w"
rows["122:1154003569"]="너희는 어둠 속에서 비틀거릴 뿐이다. 이곳엔 빛도, 자비도 없다. 얼음왕관은 너희보다 뛰어난 영웅들의 영혼도 삼켜왔다."
rows["122:1164694073"]="워치하이프는 변화를 가져오며 호드 이성쪽의 바락에 스와트를 찾아라"
rows["122:1182096809"]="내 목소리가 사라졌어? 제 종들은 어떻게 나를 들을 수 있을까? 그들은 여전히 그들의 황후를 사랑할 것인가?"
rows["122:1209323518"]="때때로 당신 은 자신 에게 \"그 것 이 가치 있습니까?\"라고 물어야 합니다. 그 해답은 분명 히 이러 합니다. \"통증 은 비용 이 아니라 보상 이다\"."
rows["122:121138351"]="다크월 페어가 열릴 때, 엘윈 숲- 우리 텐트를 남쪽으로 꽂을 거야 골드샤이어!"
rows["122:1223042786"]="만약 당신이 디파이러의 상승을 방문하고 싶다면, 물어봐라."
rows["122:1241123761"]="네 창조자들이 너를 실패시켰어 너의 결함있는 인종은 육체의 저주에 굴복했다"
rows["122:1251298844"]="서부 프로스트울프 타워는 프로스트울프 마을과 프로스트울프 케이프 사이의 게이트를 보호합니다.$B$B얼라이언스에 의해 통제됩니다."
rows["122:1256157935"]="이 모든 가려움증이 사라지고 내 빛나는 코트가 다시 돌아오기를 기다릴 수 없어"
rows["122:1273304022"]="큐 를 기다리는 후원자 를 클릭 하십시오. 그 들 과 성공적으로 교류 한 후, 당신 에게 악수 를 건드리는 것 을 보실 수 있습니다."
rows["122:1323764722"]="모든쿠, 당신의 동맹들은 우리를 구하고 황폐한 Zuluhed를 파괴했습니다. 그들은 영원히 Netherwing의 친구가 될 것입니다."
rows["122:1342737072"]="요쿰, 아른그림의 아들이여. 이곳에서 내가 행한 일들에 대해서 항상 후회했었다. 비탄에 잠긴 채 나는 나와 가장 가까운 자들에게 막대한 피해를 불러왔지."
rows["122:1354765367"]="그 악행으로 바람과 폭풍에 대한 힘을 얻었다"
rows["122:1385107711"]="안녕하세요, 내 살롱에 오신 것을 환영합니다.$B$B좋아 보이지만, 변할 기분이라면 의자 한장에 앉으세요."
rows["122:1392047851"]="스톰윈드와 얼라이언스는 성공할 수 없지만 우리의 선택은 제한되어 있습니다."
rows["122:1392309675"]="팀으로 나간다면 알려줘$B$B몇 개를 보관하고 있어, 더 필요하면 다시 와"
rows["122:1392356270"]="이대로 물러날 내가 아니다! 반드시 내가 설계한 미래를 실현하리라! 이제 진정한 힘을 느껴 보아라!"
rows["122:1398629194"]="고대의 해적 도자 를 조심스럽게 던지면서, 도자 는 떨어지고 10 로 이어지는 것 으로, 골격 해적 은 전투 에 도움 을 받기 위해 와 있습니다!"
rows["122:141476229"]="오, 내 모습을 여기 보라고 생각했지? 원숭이 왕은 듀얼링을 할당하지 않는다. 이제, 당신은 영웅입니까? 아니면 당신은 위키켓인가요?"
rows["122:1442873976"]="판다렌 전설은 레이  ⁇  (Lei Shen) 를 \"더 Thunder King\"이라고 한다. 그는 12,000 년 전에 Mogu 제국의 잔인한 창시자였다."
rows["122:1449592410"]="내 좋은 친구, 오늘 어때?$B$B이봐, 난 이걸 누구에게도 말하지 않지만, 너한테 야크가 필요하면,"
rows["122:1450670741"]="서부 프로스트울프 타워는 프로스트울프 마을과 프로스트울프 케이프 사이의 게이트를 보호합니다.$B$B이 둘 다 통제됩니다."
rows["122:1481703393"]="길네아 시티 전투가 진행 중이야, 전선으로 이동하거나, 우리의 사람들이 다음 공격에 재군합할 때까지 기다려야 한다."
rows["122:1497337052"]="보안 경보를 발령합니다. 출처 불명의 역사 자료 분석은 하위 등급 대기열로 이전됩니다. 방어 작업을 시작합니다."
rows["122:1498503643"]="한쪽은 다른 쪽보다 더 높이 날아다닌데, 혼자 물 위로 뛰어다니고, 너무 길어지고 있어."
rows["122:1514310052"]="이 큰 비석은 안전하고 빛나는 곳으로 만들어서 우리를 돌볼 수 있습니다.$B$B더 빛나는 돌을 가지고 있지?"
rows["122:1531006850"]="이 부분에는 특별한 철이 있습니다. $p- 철이 없어요 아제로스 우리는 왜소들이 가짜를 만들 수 없습니다."
rows["122:1548237386"]="그롬골에서 언더시티로 가는 비행은 아름답지만, 무사히 운행되는데, 그 이유는 직장에서 잠들기 위한 것이 아닙니다."
rows["122:156344288"]="난 내 방패를 찾을 수 없어 마을 곳곳을 찾아봤어"
rows["122:157126666"]="휠러 모바일에 거의 타버렸어!"
rows["122:1572504091"]="스키테는 묶이지 않는 것을 해제하자 영혼이 짐승을 지배하게 하여야 돼"
rows["122:1574980446"]="왜 그냥 차이점을 얘기하지 않는가? 좋은 긴 대화로 해결할 수 없는 문제도 난 한번도 겪지 않았어!"
rows["122:1576900185"]="그렇다면, 알겠습니다. 마음대로 하십시오. 우리가 다른 순례자들을 내쫓을 때 그들이 받을 고통은 당신 책임입니다. 그 점 명심하십시오."
rows["122:1598808180"]="내가 네 말대로 거래해 내 사람들을 돌고래에 데려가줘서 널 보호해 줄 거야"
rows["122:161052567"]="너 없이 큰 냄새가 나고 있는  ⁇ 문,  ⁇ 문, 네 빚이 다 됐어"
rows["122:1617243952"]="정말 최고의  ⁇ 匠이 되어서야! 축하합니다."
rows["122:1620758318"]="|cff0000ff급 9:|r \010  빅 바다 부름: $8072w-$8071w\010  니블레: $8074w-$8073w\010  박사 FIST: $8076w-$8075w\010  아후'루: $8078w-$8077w"
rows["122:1648437804"]="모든 줄, 각 줄은 이미지를 정의하는데 도움이 됩니다. 그것은 생각과 문장에서 분리되어 보는 사람의 관심을 사로잡습니다."
rows["122:1662457476"]="눈부신 시야야, 로나. 이 총을 조종해!"
rows["122:1672968896"]="일단 얼라이언스와 그들의 동맹군들을 물리치면 이 땅이 호드의 끈기라는 증거가 될 것입니다."
rows["122:1687712919"]="그래, 그게 더 좋은 것 같아서요. 저는 그들로부터 본 것을 좋아하고 그들의 세상은 제 도움이 필요할 것 같습니다."
rows["122:1692459814"]="사실, 누군가가 날 죽이려고 했지만, 그게 지금 내가 가장 걱정하는 게 아니라 세상 자체가 내 도움을 요구하고 있습니다."
rows["122:1700369012"]="네 세계 샤만은 아래의 바사틀밭에 서 있지만 조심해 그는 이 끝없는 돌 홀과 하나가 되었다"
rows["122:17028190"]="그 사람들은 호드 배, 총군 기구, 새들을 날려보내, 갑판을 정리해"
rows["122:170984467"]="아뇨, 아가씨, 점심 먹으러 갈래?"
rows["122:174610254"]="요리사가 없었지만 남풍에 맛있는 냄새가 있어"
rows["122:1750845237"]="방랑한 이야기에는 시간이 거의 없습니다. 우리 사람들은 위기에 처해 있고, 모든 죄가 우리의 회복에 역할을 합니다."
rows["122:1752202435"]="성스러운 빛은 느낌으로 나타납니다. 처음에는 미약해서 쉽게 지나칠 수도 있지만 마침내는 진실을 보여주고 옳은 일을 하도록 인도하죠."
rows["122:1782227523"]="고대 문헌은 맨티드가 항상 여기 있었음을 알려줍니다. 그들은 모고보다 훨씬 오래되었습니다. 그들은 어디에서 왔습니까?"
rows["122:1783178049"]="누가 내가 맥주 한 잔 남았다고 했는지 모르겠지만 조용히 해봐"
rows["122:1783773009"]="'린다, 이바르 블러드펀그랑 어디서 만나게 되죠?"
rows["122:1784040698"]="폐허와 잔해가 풍경을 휩쓸고 있고... 저는 라벤하일드의 도둑들과 암살자들을 그 잔해의 일부라고 생각합니다."
rows["122:1795114365"]="우후!$b$b다시 한번 해야 할 일이 있어요!$b$b좀 더 연구하러 가는데, 준비되면 찾아볼게"
rows["122:1797911102"]="어둠 속에서 헤매는구나. 여기엔 빛이 없다. 자비도 없다! 얼음왕관에서는 너보다 더 나은 영웅들의 영혼도 사라져갔다."
rows["122:1810464855"]="아마카르, 워러드 고로투스가 어디로 보내줄까?"
rows["122:1816163534"]="페렐레 씨, 언데드의 징후를 목격한 적이 있습니까? 뭐든 정보를 제공해 주시면 아서스 왕자님께서 기뻐하실 겁니다."
rows["122:1820648989"]="내 피가 충분한 대가를 지불하지 않았어?"
rows["122:1842276306"]="검색 중... 아제로스는 초기 발전 단계에서 기생성 숙주 잠식 공생체에 감염되어 질환을 앓았습니다."
rows["122:1843581791"]="웃기지 마. 내가 널 살려주면 어디로 갈 셈인데? 방금 너희 문명을 싹 없애버렸다는 거 잊었나?"
rows["122:1869096634"]="좋다. 얼어붙은 땅의 전사들이여, 일어나라! 너희에게 싸울 것을 명하노라. 날 위해 죽고, 날 위해 죽여라! 한 놈도 살려두지 마라!"
rows["122:1876663125"]="저는 당신이 호수의 한가운데에서 폭발하는 분노의 거대한 파도에 대해 뭔가를 할 계획이라고 믿습니다!"
rows["122:1882449812"]="신도레이만이 쿠엘델라를 추앙한 게 아닙니다. 실버문 자손 모두의 마음속에 자리 잡고 있지요."
rows["122:1883112842"]="|TInterface\\Icons\\spell_frost_piercing chill:20|t당신은 |cFFF00000|Hspell:139866|h[Torrent of Ice]|h|r의 표적이 되고 있습니다!"
rows["122:1891820563"]="여기 있는 도자, 전쟁 구역에서 일하고 있어, 그의 무기가 쓰이는 곳 근처에 있어."
rows["122:1894944969"]="여자들이여, 저 공작은 계속 살아갈 거야."
rows["122:1912310489"]="섬 곳곳에 방패 발전기가 장베스의 심장을 보호하고 있어 무기 저장소에 접근하지 못해"
rows["122:1924451130"]="아, 넬쥴이라... 입에 함부로 올려서는 안 되는 이름이지만 내가 그 대답을 기대하고 물은 것이지.$B$B넬쥴이 정답일세."
rows["122:1937563373"]="모가들은 무엇을 지키거나 파괴하러 보내졌을까요?"
rows["122:1953358335"]="마침내 끝났도다! 동지들의 죽음을 애도하라! 이루지 못한 꿈을 그리며 슬피 울어라! 하크 민 코레이!"
rows["122:1957864432"]="어떻게 찾았는지 묻지 말고 그 큰 파란 불에 던져서 너무 늦기 전에 양위의 영혼을 파괴해"
rows["122:196308790"]="난 널 포기하지 않아 아직 저주 치료법이 없어 하지만 치료 방법이 있어"
rows["122:1984433784"]="|TInterface\\Icons\\ability_creature_poison_04:20|t%s은 그의 칼을 |cFFFF0000|Hspell:143224|h[인스턴트 독자]|h|r로 덮는다!"
rows["122:1998651241"]="엘리베이터가 시간 내에 작동할지 몰랐기 때문에 나와 동생을 불러들었어요"
rows["122:2013316382"]="스톤하스 묘지는 전투 현장에서 스톤하스 포스트 동쪽에 위치하고 있습니다.$B$B얼라이언스는 현재 이 기구를 통제하고 있다."
rows["122:2023121093"]="네 파란 피로 즐거워 마시게 되는데, 드레네이"
rows["122:2030250875"]=" ⁇ 피크는 한 번 싸웠고 겨우 탈출했어"
rows["122:2058179748"]="우리는 적들을 그들의 힘을 빼앗기 위한 방법을 찾아야 합니다."
rows["122:2066774624"]="물러서! 이번엔 내 주문을 받아라... 신념의 파괴자! 고통의 창조자! 다시 돌아오는 날엔 오늘 네가 저지른 만행을 똑같이 되돌려받으리라!"
rows["122:210171959"]="저장소를 찾고 있어? 에스코다르의 안전에 가고 싶어서 은행가들이 기꺼이 도와줄 거야."
rows["122:2104625946"]="<너의 놀라움으로, 랩터 새끼는 당신과 소통할 수 있습니다.>$B$B- 네 고기를 요리하는 게 사실인가요?"
rows["122:2111719262"]="물러서! 이번엔 내 주문을 받아라... 신념의 파괴자! 고통의 창조자! 다시 돌아오는 날엔 오늘 네가 저지른 만행을 똑같이 되돌려받으리라!"
rows["122:2113399927"]="|cFFFF0000|Hspell:105723|h[Elementium Bolt]|h|r 당신을 죽였습니다. 타격 지점에서 벗어나 볼트의 손상을 줄이기 위해 이동하십시오."
rows["122:2114178009"]="날개 없는 비둘기들아, 내 영역으로 들어와, 이 테라스에서 내려오면서 죽음의 외침을 듣게 될 거야!"
rows["122:2146353549"]="일단 안으로 들어가면 잔다라리 배를 파괴하고 혼란 속에서 우리는 정원을 뚫고"
rows["122:219177611"]="나트레즈마의 고향에서 그런 시나리오를 봤을 때, 난 읽을 수 없어"
rows["122:222685104"]="이제 고객들은 당신이 만든 누드루 수프를 기꺼이 먹게 될 것이고, 그들이 다하면 행복하게 떠날 것입니다."
rows["122:252586241"]="이 곳에는 자연스럽지 않은 어둠이 있습니다. 영원한 밤 중간에 빛."
rows["122:255333401"]="시간이 지나면 우리 사람들은 당신이 보이는 적보다는 동맹국으로 당신을 보게 될지도 모릅니다."
rows["122:260860109"]="우리는 부적합한 물품이 있지만 많은 것이 아닙니다. 우리는 전투장에 지상의 공격을 보낼 수 있기 전에 훨씬 더 많은 것이 필요할 것입니다."
rows["122:265591990"]="태블릿과 함께 보내진 브란의 크리스탈을 사용하여 자신을 보호하고 탈출할 수 있었지만 공격자 중 한 명이 나를 따라왔다!"
rows["122:268770857"]="다크월 페어가 열릴 때, 멀고어우리는 우리 텐트를 남서쪽으로 썬더 블러프!"
rows["122:282488874"]="아뇨, 안리 장님께 많은 오닉스 알을 가져왔어요"
rows["122:289594886"]="나는 이제 평온하게 떠나지만, 너희 모두에게 영원한 감사를 남긴다. 내 어리석음과 탐욕이 만든 저주에서 날 해방해줘서 고맙다."
rows["122:290561172"]="모든 보상금은 검증 후 고위 집행자 롤에게 지불되어야 합니다.$B$B진지한 마음이 있는 사람들은 내면을 조사합니다.$B$B협상자 없소!"
rows["122:307247885"]="성령께서 당신 앞에 놓으신 것을 부인하지 말라 오직 희생을 바치는 모든 자들이 그분 앞에서 구원받으리로다"
rows["122:360604040"]="아무 일도 일어나지 않아서 병의 가두는 망가졌지만, 전혀 달라진 것 같지 않아"
rows["122:361801575"]="왜 그런지 모르겠어요 포세이큰 하로우의 끝에서 진짜가 아닌 매 밤 빗자루를 태워버리는데,"
rows["122:366836718"]="별일 아닐세! 이 아카마와 나의 맹신도들이 감시하는 동안 포로가 달아날 일은 없을 거라고 주인님께 전하게."
rows["122:431024029"]="도움으로 다시 감사해요, 낯선 사람. 이미 시라의 손에게 만들 수 있는 링에 대한 아이디어를 생각해보았습니다."
rows["122:431694176"]="고대의 해적 도자 를 조심스럽게 던지면서, 도자 는 떨어지고 10 로 이어지는 것 으로, 골격 해적 은 전투 에 그녀를 돕기 위해 와 있습니다!"
rows["122:432057332"]="한 고객이 식사를 마친 후에는, 그들이 사용하는 좌석이 청소되어야 합니다."
rows["122:44299450"]="라저 힐에 엔지니어링 트레이너가 있는데, 그는 무크드라크라고 불리며, 보통 금고 근처에 서 있는 사람이 발견될 수 있습니다."
rows["122:447122635"]="많은 가죽 노동자들이 훈련에 참여하지 않지만, 준비가 되면 가르쳐 줄 수 있을 것 같습니다."
rows["122:449739447"]="내 왕, 난 약속해 키린토르는 가로쉬를 공격할 거야"
rows["122:453682626"]="우리는 당신을 알고 있습니다, Cairne Bloodhoof, 당신의 사람들은 당신의 행위에 대해 우리에게 이야기했습니다."
rows["122:46828628"]="크록, 네놈이 한때는 내 전우였지만, 지금은 그저 배신자일 뿐이다. 오너라. 두 번째 죽음을 맞이해라!"
rows["122:489778212"]="두 가지로 갈라져 하나의 둥글다.$B$B쌍둥이가 발견되면 수르트라즈가 되살아난 자 될 것입니다."
rows["122:490367530"]="에드워드, 타일러. 잘했다. 훈련 성과가 꽤 좋군. 얼마 후에 자네들의 기질을 다시 한번 시험해 볼 테니 준비하고 있도록."
rows["122:494166174"]="악이 있어야 선도 존재할 수 있다면, 이 유물이 존재함으로써 정반대의 성질을 가진 물건도 존재할 수 있지 않겠소?"
rows["122:537388382"]="우리 주인은 세상을 갈라놓을 것이고, 당신이 아는 모든 것이 끝납니다."
rows["122:540463451"]="먼저 내 소중한 사론이트를 많이 내주고, 그 다음 더 큰 힘을 가진 루니블레이드를 만들기를 요구한다."
rows["122:555487463"]="돼지 농장을 운영하는 것은 생각보다 더 많은 일이지만 대부분 \"돼지를 위한 먹이를 찾아내기\"로 요리를 할 수 있습니다."
rows["122:597699488"]="타이란데 와 말푸리온 은 우리 를 환영 하였는데, 거의 오랫동안 잃어버린 가족 처럼 들었어요."
rows["122:641133506"]="나중에 돌아올 수 있겠어? 지금 내 구름 뱀을 훈련하는 데 바쁘다. 다른 사람들을 이길려면 더 열심히 일해야 한다."
rows["122:651259981"]=" ⁇ 디와 젤아야는 델밸리의 중심 건물 북쪽에 있는 한 굴에서 일하고 있습니다.$B$B데이는 네가 필요한 모든 것을 도와줄 수 있어"
rows["122:652789958"]="분노나 의심과 같은 부정적인 감정은 파다리아에서 이상한 힘을 갖게 되지만,"
rows["122:668012704"]="다시 한번 도움을 주셔서 감사합니다. 저는 잠시동안 여기 머물게 되고, 부상자들을 돌볼 수 있도록 도와드리겠습니다.$B$B그럼 북쪽으로 갈게"
rows["122:681158836"]="영원의 눈 안에 있는 집중 아이리스가 용 영혼 안에 있는 마법 매트릭스를 합성할 수 있게 해 줄 수도 있습니다."
rows["122:701726777"]="술 마스터는 그  ⁇ 을 만들지만, 종종 술이나 약에 대한 더 좋은 점들을 놓치고 있습니다."
rows["122:716166108"]="날 미워하는 거요, 내 사랑? 그 고통스러운 불행의 속박에서 당신의 영혼을 풀어주기 위해서 다른 이의 손을 빌려 당신을 해칠 수밖에 없었던 나를..."
rows["122:73694541"]="아버지, 크레인 성전이 전쟁지역으로 변할 수 없어요."
rows["122:753845624"]="시체를 조사하면 이 사람은 '블러드 라이트 아운스타'가 될 것으로 결론지었습니다."
rows["122:761568942"]="미란다, 다른 명성을 가진 모험가들에게 제공하는 상품의 엠자그니 비용에 대해 말해줄 수 있나요?"
rows["122:768624483"]="아마 그는 애완 동물인 괴물과 놀고 더 많은 시간을 훈련한다면 우리는 이 일을 해결할 충분한 힘을 가질 것입니다!"
rows["122:778168148"]="|TInterface\\Icons\\ability_shaman_cleansespirit.blp:16|t그라울 투하 |cFF00FFFF|Hspell:103550|h[정화 영]|h|r"
rows["122:790350226"]="이 는 목적 지점 이다. 모든 10 체크포인트 를 지나가자, 목표 지점 아래로 비행 하여 당신 의 장소 로 잠금 하라."
rows["122:7923220"]="여러분께 필요한 것은 제 소소한 바램을 훨씬 뛰어넘는 스케마입니다."
rows["122:819003348"]="내 거꾸로 돌아다니는 건 다 끝났어, 그 길은 여기까지 이 건물은 우리가 발견한 것과 같은 잎이 있는 식물들로 덮여있어요"
rows["122:828671118"]="저주받을 개구리 같으니! 그래, 난 예전에 남쪽바다 해적단의 일원이었어. 그게 뭐 어쨌다는 건가, 친구? 당장 절단을 내 주겠어!"
rows["122:830681051"]="루칸 코델은  ⁇ 다에 있는 운하에 작은 가게를 가지고 있어"
rows["122:833807621"]="그러니까 성스러운 빛이 자랑하던 정의가 마침내 왔다 이건가? 폴드링, 서리한을 내려놓고 자비라도 애걸하라는 건가?"
rows["122:846093156"]="우리가 수집하는 곡물은 맥주 공장에 필요한 양이 많아야 하지만, 당신의 필요에 맞는 곡물도 알고 있을지도 모릅니다."
rows["122:848045276"]="스톤하스 묘지는 전투 현장에서 스톤하스 포스트 동쪽에 위치하고 있습니다.$B$B현재 어느 쪽도 통제하지 않습니다."
rows["122:874587359"]="백 호랑이의 전설을 듣고 자랐어요. 그는 판다레네 민족의 영웅입니다."
rows["122:90020993"]="켄-켄... 나는 그가 붉은 크레인의 성전 근처 어딘가에 머물렀다는 소문을 들었다고 생각합니다.$b$b내가 데려갈까요?"
rows["122:92716337"]="용들은 우리에게 Twilight's Hammer의 문들을 포위할 기회를 줬어"
rows["122:927837651"]="필멸의 용사들은 이런 무기로 오랫동안 악에 대적해 왔소. 그러니, 이 전투에서 저들이 그 검을 사용하지 못하게 할 이유가 없소."
rows["122:935885621"]="용들은 우리에게 Twilight's Hammer의 문들을 빼앗을 기회를 줬어"
rows["122:95229711"]="영들의 방은 우리 샤마가 고향이라고 부르는 곳이다."
rows["122:954948131"]="우린 수십 마리의 나가를 죽였지만, 그들은 계속 오고 있어요."
rows["122:97209738"]="넌 허약하고, 심심 넘치는 사람이야 눈도 빠진 것 같지만 그렇다고 경쟁을 하지 않아야"
rows["123:1016891943"]="이 거리를 계속 지나가게 되죠. 언'고로로 가는 길은 여기서 서쪽으로 갈 겁니다."
rows["123:1017724188"]="전 세계 모든 대륙에서 에이전트를 가지고 있지만, 그 누구도 오그리마!"
rows["123:1027554580"]="어둠을 저주하기보다는 촛불을 부추는 것을 좋아한다고 말한 사람이 누구든...$b$b아마 저만큼 촛불을 불린 적도 없을 겁니다"
rows["123:1029414632"]="빨리, 내놈!$b$b내가 죄수들에게 무슨 짓을 하는지 알 수 있어, 난 죽기엔 너무 젊어!$b$b뭔가 해야 돼!"
rows["123:1038135749"]="소년들과 함께 여행한 건 얼마 되지 않았지만, 둘 중 어느 누구도 없는 삶을 상상할 수 없습니다."
rows["123:1054491565"]="열어야 돼 빨리 가봐야 돼, 다크 아이언의 냄새가 나고 있어"
rows["123:1061494010"]="그들은 조성처럼 권세를 추구하나 너희는 그들이 우리에게 반항하지 아니하리라 생각하니 내가 너희를 어리석게 키웠느뇨"
rows["123:1071044739"]="에메랄드 드림은 나에겐 별로 안좋아"
rows["123:107692112"]="절대 안 돼!$b$b내 재산을 위험에 빠뜨리고 있어 솔직히 공공 위기가 어떤 사람에게 어떤 도움이 될까요?"
rows["123:1077972470"]="빛 당신의 길을 안내하고 당신의 여행에 도움이 될 수 있습니다. 당신이 어떤 도움도 필요하면 탐색, 나는 바로 여기에있을 것입니다."
rows["123:1093593263"]="야아아! 이 초짜야, 무슨 짓을 한 거냐?! 저놈이 미쳐버렸잖아! 갑판을 봉쇄해! 돛대를 올려! 아아아! 이제 각자 살길 찾아라!"
rows["123:1100076560"]="이 결정 기반의 구조물은 에너지로 가득 차 있습니다. 이상한 글리프들이 당신 앞에 투영되어 순차적으로 스크롤됩니다."
rows["123:1100182384"]="물 속에서 떠다니는 게 지쳤어, 좀 쉬워요?"
rows["123:1115165177"]="내 생각에는 네가 잃을 것이라는 의심의 여지가 없습니다. 속도와 지성은"
rows["123:1121085427"]="곳곳에서 온 모험가들이 안토니오의 고객이랍니다. 자, 안토니오가 이번 주에 여러분을 위해 준비한 작은 보물이 무엇인지 어서 와서 구경들 하세요."
rows["123:1178528340"]="우리는 예쁜 사회의 그림자 속에서 활동할 수도 있지만, 전쟁의 전선에서 우리의 권력은 마침내 제대로 존중됩니다."
rows["123:1190136735"]="이 유물은 바로 전쟁원장이 찾길 바랬던 것인데,"
rows["123:1202430080"]="맹세하네... 퀸트가 내게 또 다른 낚시 먹이를 심으려 한다면, 난 내 썩지 않은 칼로 그 나무를 잘라내게 될거야."
rows["123:1203574731"]="내 가구 안에 있는 것을 가져오세요. 그것은 제 계획의 두 번째 단계였죠."
rows["123:1215270436"]="말하게 해주셔서 감사합니다 아달 많은 동맹들이 무루를 대하는 걸 싫어한다는 것을 압니다"
rows["123:1265719605"]="오늘 여기 오기 위해 제이드 숲에서 먼 길을 걸었고, 이번 대회에서 내 능력을 키울 수 있기를 바랍니다."
rows["123:1270796517"]="|TInterface\\Icons\\ability_warlock_chaosbolt.blp:20|t%s는 거대한 |cFFFF0000|Hspell:138559|h[Chaos Bolt]|h|r를 캐스팅하기 시작합니다!"
rows["123:1291998055"]="|TInterface\\Icons\\achievement_boss_ragnaros.blp:20|t당신은 캐스팅을 앞두고 있습니다 |cFFFF0000|Hspell:101109|h[Ragnaros의 분노]|h|r!"
rows["123:1303860865"]="중부분야에 있는 얼라이언스군을 공격할 명령을 받았어요"
rows["123:1314657556"]="결국, 바리안이 아니라 그의 새끼가 내 앞에 서게 되니까"
rows["123:1323599798"]="이해가 되길 시작해 난 네 크레이커나 아빠랑 아무 상관이 없어\010"
rows["123:1323708111"]="담당자가 당신에게 말할 때는 매 줄을 당신 이름으로 시작합니다. 이름이 보이지 않는다면 당신에게 하는 말이 아닙니다."
rows["123:1329069550"]="여기 밸리에는 전투장이 없습니다.$B$B전쟁터나 전쟁 현장들을 위해 순차적으로 고향으로 돌아가야 합니다."
rows["123:1337239752"]="길네아스, 실바나스 통제를 잃는 것 같군"
rows["123:1356804284"]="워치프, 이 새로운 포세이큰 우리 민족은 죽게 될 것입니다. 로데론 무너질 것입니다."
rows["123:1397357653"]="그는 결코 싸우지 않는 상대를 본 적이 없다. 아, 작은 수정: 그는 결코 상대를 본 적이 없습니다. 그는 맹인 영웅입니다!"
rows["123:139932420"]="마모트가 널 뚫고 있는 거 봤을 때 화나고 먼저 그들을 밀어내면 안 돼"
rows["123:1461992135"]="이 자료에 따르면 우리는 두려워할 것이 없어 적어도 가까운 미래에 아무것도 없습니다."
rows["123:1477044779"]="시간이 얼마 없다! 운반할 수 있는 건 아무거나 챙겨서 곧장 폭풍 첨탑으로 순간이동하도록! 서둘러!"
rows["123:1483541106"]="오늘은 좋은 날이군요, 친구여. 고룡쉼터 사원을 떠나 용의 안식처를 자유롭게 날아다니는 것은 참으로 오랜만입니다."
rows["123:1496755091"]=" ⁇ 이라고 주장하는 소여성이 실버문 안에 캠프를 세웠고"
rows["123:1518190352"]="우리는 명예와 명예와 아르헨티나 십자군 전쟁의 형제들과 함께 스컬지를 싸우기 위한 권리를 위해 경쟁하기 위해 왔습니다."
rows["123:152016774"]="자발톱을 깎아 내린 아브루스는 가슴에 파묻혀서 심장 박동을 제거하고 달석이 떨어지는 곳에 놓습니다."
rows["123:1531682239"]="이 고통받은 영혼들을 처리하도록 나를 도와라! 함께 서리한의 지배를 늦추고 안에서부터 리치 왕을 약하게 하자!"
rows["123:1532815244"]="난 이 나무들을 돌보는 데 일생을 바쳤소. 가지를 치고 비료를 주고... 이제 죽음까지 나와 함께하니 정말 잘 어울리지 않소?"
rows["123:1536181655"]="반대의 경우, 그노메레건의 최고의 선수들 중 몇몇이 있습니다."
rows["123:154958304"]="오늘 끝나는 순환이 끝나고, 레전트 로드님과 프라우드머 부인께서 서로서로 돌아와"
rows["123:1559834482"]="카르게시족은 이런 욕을 받지 않을 겁니다."
rows["123:1575852710"]="지금, 저는 우리의 워치퍼를 보고, 똑같은 인종차별을 보게 됩니다. 그는 자신의 일제에서 우리의 삶을 버리는 것을 기꺼이 합니다."
rows["123:1579915682"]="정말, 이 곳의 공포는 우리가 전염병에서 겪었던 공포보다 더 크습니다.$b$b스컬지는 이제 이전보다 더 강력합니다."
rows["123:1587105089"]="왼쪽의 크리스탈은 결함이 있다고 생각합니다. 우리는 그들의 건설을 서둘러서는 안 됩니다. 이런 식으로 사고가 발생합니다."
rows["123:160473713"]="멍청한 녀석! 넌 우리에게 위협이 되는 유일한 존재에게 우릴 안내해 줬을 뿐이다! 에티미디안을 노스렌드에 데려갈 수는 없어!"
rows["123:1656790031"]="큰 곰이 아직 여기 있어?"
rows["123:1657983558"]="섬을 분할하는 물들을 보세요. 하지만 경고하세요. 악수사자는 강의 물 속에서 집을 짓습니다."
rows["123:1662603774"]="내 카라반 안에 있는 물건들을 환영해줬으면 좋겠어요."
rows["123:1671835049"]="신사님, 다른 군인들이 우리 공격에 대비하고 있다는 소식이 전해졌습니다."
rows["123:168277312"]="내가 제안할 수 있는 유일한 조언은 당신이 원하는 길을 가세요!$B$B아무것도 기억 안 나!"
rows["123:1706866946"]="친구들에게 라인 가족  ⁇ 거리를 찾아서 비밀 요금 수프를 사라고"
rows["123:1707944181"]="이 곤충들은 그들의 위치를 알지 못해 가라'질."
rows["123:1714487996"]="내가 널 위해 가방에 뭔가를 넣었어, 여기 있어, 내가 찾게 해"
rows["123:1718961280"]="머리가 너무 아프고... 기둥은 내 눈보다 더 강한 힘을 포함하고 있을 거야"
rows["123:1727668629"]="신조들의 명령이 나오는 곳이죠. 그들의 지도자는 곧 나타날 것입니다.$B$B이 기회를 놓치지 마세요."
rows["123:1728404678"]="|TInterface\\Icons\\spell_shadow_twilight.blp:20|t 울트라시온은 캐스팅을 시작한다 |cFF9900CC|Hspell:106371|h[Twilight의 시간]|h|r!"
rows["123:1744945594"]="우리는 성전을 점령하는데 성공했습니다. 우리는 계속 경호를 전환하고 다른 전술적 위치에서 경호자로 사용할 수 있습니다."
rows["123:179933008"]="|Tinterface\\icons\\spell_fire_twilightrainoffire.blp:0|t%s는 스카이파이어에서 |cFF9900CC|Hspell:110153|h[브로드사이드]|h|r를 발사한다!"
rows["123:1808833630"]="살아생전에는 나의 검 아키우스가 아주 쓸모 있었지. 하지만 비참했던 삶에서 자유로워진 지금은 아무런 필요가 없네."
rows["123:1809164622"]="이 청춘들은 인사도 하지 않고 공격만 했다!"
rows["123:1866583813"]="그러면 난 영원의 눈을 찾아갈 길을 열어줄게 아제로스 당신의 행동에 달려 있습니다."
rows["123:1867774702"]="우리는 여전히 움직임을 거쳐가고 있지만, 겨울 베일 축제는 이제 빈 느낌입니다. 오그리마 그들은 진정한 축제를 가지고 있습니다."
rows["123:1869997121"]="켈'투자드가 전설적인 아티시, 수호자의 대부들을 찾는다.$B$B예, 메디브가 한 때 지낸 지팡이"
rows["123:1871785850"]="하지만 생성되는 힘이 소실될 수도 있고 몇 주 동안 두통을 일으킬 만한 힘의 유입을 유발할 수도 있어요."
rows["123:1890059808"]="<레일은 당신을 향해 올라가지 않는다.>$b$b<이런 상태에서 판단하면 머리가 움직일 수 있는 에너지가 있다고 확신할 수 없습니다>"
rows["123:1894992944"]="빛 당신의 길을 안내하고 당신의 여행에 도움이 될 수 있습니다. 당신이 어떤 도움도 필요하면, 나는 바로 여기에있을 것입니다."
rows["123:1905335787"]="하지만, 수년이 흐른 지금, 올빼미야수는 수호자의 역할을 잊고 점점 광포한 야생의 본능으로 돌아가고 있다. 자신도 혼란스러워 하는 것이지..."
rows["123:1944026640"]="들어와서 앉으세요, 발에서 일어나세요.$b$b이제, 내가 뭘 도와줄 수 있어?"
rows["123:1955921189"]="현재 우리는 Zul'Aman의 테스트를 중점화하고 있습니다 10 유령지방의 포지션에 대한 공격이 가능한데 68 들어가게"
rows["123:1971574331"]="내가 여기 있을때, 내 물건을 둘러보고 싶니? 판다리아에서 새로운 물건이 있어."
rows["123:1971609123"]="일지를 보셨다면, 제가 어떤 작업에 매달려 왔는지 아실 텐데요. 우리는 서로 칼을 겨누고 있지만, 둘 다 티탄의 창조물입니다!"
rows["123:1986685368"]="성스러운 빛의 가르침을 따르다 보면 그 목소리와 힘에 점점 민감해지는 자신을 느낄 수 있을 겁니다."
rows["123:2001325596"]="|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:90949|h[Devoring Flames]|h|r!"
rows["123:2004683070"]="난 먼저 내 사람들을 보호해야 돼 우리 적들이 사막에 오르시스를 묻어놨어"
rows["123:2007186109"]="잘 싸웠네! 다음 상대는 은빛십자군의 일원이라네. 그들을 상대로 자신의 무용을 증명해 보게."
rows["123:2011571086"]="충격이나 부상, 둘 다 없는 첫 번째 사람이죠.$B$B도움이 되길 바랍니다."
rows["123:2024843764"]="당신은 당신이 생각하는 것보다 더 강하고, 더 강합니다. 이 생각을 당신 곁에 가지고 앞으로의 어둠으로 가져가세요."
rows["123:2061097436"]="지혜의 시험을 거쳤고, 자이드 뱀의 길을 배웠으니, 저처럼 이 교훈을 배워라"
rows["123:2061323124"]="큰 곰 정신, 네 말을 들어왔어, 그리고 이해해 왔어."
rows["123:2070846823"]="수색꾼, 자네 사료... 아니, 사람들은 브리쿨에 대항하는 소중한 자원이 될 거야. 내가 자원이라고 했나? 내 말은... '동맹'이란 소릴세."
rows["123:2075729196"]="여러분, 놀랍죠? 도시로 들어가는 이는 모두 이 땅의 위대한 영웅들이 위에서 지켜보고 있는 이 아래를 지나가야만 해요."
rows["123:2099264822"]="오크 군대에 충분한 일이 있고, 대부분 내가 할 수 있는 일이지만,"
rows["123:2099695749"]="당신은 그들의 지구 룬을 파괴했지, 다른 세 명이 있을거고, 그리고 그들은 모두 뒤쪽의 불문과 연결되어 있다고 확신합니다."
rows["123:2102842413"]="장거리에서 졸트릭과 싸울 수 없다면 점프 드레이크 능력을 사용하세요!\010|TInterface\\Icons\\ability_vehicle_launchplayer.blp:64|t"
rows["123:2105120816"]="전 하루 종일 여기 그 메시지를 기다리지 않을거야."
rows["123:210703453"]="물론 새에 더 많은 고기를 먹으면 좋겠지만, 네 사람들과 내 사람들은 그렇게 다르지 않다는 걸 알 수 있습니다."
rows["123:21587633"]="달 축제는 칼도레에 더욱 중요해졌습니다. 드루이드들의 위대한 축제는 확실히 전성기를 누리고 있습니다."
rows["123:230531644"]="틴키가 떠났다는 건 내 잘못이 아니야 이 물건은 그녀의 아기야"
rows["123:238014365"]="보시다시피, 이 야만인들한테 잡히는 바람에 가진 게 별로 없습니다. 하지만, 뭐라도 드리고 싶군요. 와서 쓸만한 게 있는지 살펴보시죠."
rows["123:239226191"]="|TInterface\\Icons\\spell_fire_twilightflamebreath.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:86840|h[Devoring Flames]|h|r!"
rows["123:243038092"]="정복 섬은 우리가 침입할 수 없는 귀중한 자원들로 가득 차 있습니다 얼라이언스 - 전투에 참여하겠어?"
rows["123:271819688"]="워치프가 이 해안을 안전하게 지키라고 요구하고 있습니다. 얼라이언스이 움직일 때, 물은 그들의 피로 빨강해질 것입니다!"
rows["123:27325239"]="당신이 한 일은 자연의 법칙에 어긋나고, 혐오스러운 것은 내가 설명할 유일한 단어다."
rows["123:281281738"]="동쪽 산벽이 있습니다. 저는 지금 남쪽으로 갈 것입니다. 계속 노력하세요. 우리는 아직 그 두께를 벗어나지 못했습니다!"
rows["123:282205582"]="판다렌은 이 순간에 집중하고 있어"
rows["123:284817"]="길게 여행했지만 마침내 밸리를 찾았어요."
rows["123:287655398"]="데 마을로 돌아가야 할 때, 우리 집, 데 다크스피어의 집을 다시 짓는 시간."
rows["123:294146892"]="우린 당신이 처한 정신 통제 된 야만인들이 아닙니다. 호드!"
rows["123:294400925"]="이것은 손자들에게 말할 수 있는 훌륭한 이야기로 만들어질 것입니다. 내가 충분히 살면,"
rows["123:302270028"]="말 낭비 그만해, 벌레. 드래곤마우의 도움을 원한다면 무릎 꿇고 금을 바쳐야 했다"
rows["123:304417188"]="그리고 너나 그 바보 같은 일리단 녀석이 나를 막을 방법은 없다! 너와 일리단 모두 태어났을 때부터 나를 섬기게 된 것이다. 자기도 모르게 말이지."
rows["123:369206311"]="외로운데 내 나이보다 더 많은 아이들이 있었으면 좋겠어 가끔은 샤트라스 시티의 고아원에서"
rows["123:389902106"]="지금까지 인내했지, 하지만 그들이 빨리 로켓 스링을 작동시키지 못하면, 난 누군가를  ⁇ 을거야!"
rows["123:391963049"]="불꽃을 부추는 내 여자애야! 좋아. 이제, 우리 중 누가 더크스피어에 작은 방문을 할만큼 용감해?"
rows["123:398058016"]="헤비 메탈 발사기에 기름을 뿌리면 피라론의 승무원들은"
rows["123:419256538"]="차종에서 그놈의 차를 폭발시키려고 하는거 들었어요"
rows["123:434344117"]="내가 그 사람을 내 손 아래로 내게 하고 벌을 받게 되리니 그가 이 땅의 법을 어겼으니 그것을 이행하는 것이 나의 맹세된 의무이다"
rows["123:447434757"]="동쪽의 언덕에 사는 한 약사가 있습니다. 스톰윈드 우리 화학자와 함께 하는 것, 아주 편리한 조화를 맞지 않나요?"
rows["123:448317384"]="그들이 가장 환영받는 것처럼 느껴지도록 해줘요"
rows["123:465405746"]="내 친구, 내가 옛날에 많은 재미있는 이름을 봤어. 물고기는 그렇게 이상하지 않아."
rows["123:470609135"]="케이다니스 씨, 당신이 지키고 있는 이 비전 성소들은 상당히... 흥미롭소이다. 유용한 정보 감사드리오."
rows["123:477341939"]="교육은 거의 완료됐고 마지막 임무는 당신과 당신의 노력의 최고점까지 걸리는 것입니다."
rows["123:513115503"]="지나의 아버지는 매우 부유합니다. 돈이 필요하면 항상 그와 이야기 할 수 있습니다.$b$b왜 저 여자들이 가난한  ⁇ 베지에게 고장을 안겨야 할까요?"
rows["123:520276119"]="밤낮은 내가 하는 일은 여기 앉아서 탄약을 만들고, 활을  ⁇ 다.$B$B나도 너한테서 뭔가를 해줘야겠어?"
rows["123:54945733"]="어류 전투에 특화된 수도사를 알고 있었는데, 꽤 제한적이지만 어류 튀김을 만들 수 있었습니다."
rows["123:566244573"]="바람과 나무는 보이지 않는 문제들을 속삭이고 땅은 건강해 보이지만, 여기서 보이는 것보다 더 많은 일이 일어나고 있습니다."
rows["123:566712779"]="이미론은 고뇌했다. 왕좌에 오래도록 앉아 왜 우리가 이런 곤경에 처했는지 깊이 고민했다. 해답은... 이유는... 단 하나뿐이다..."
rows["123:581634913"]="맙소사! 여길 좀 보십시오! 살라다르가 뭘 계획하고 있는지 상상이 되는군요. 어서 계속 갑시다."
rows["123:619869402"]="네 바람의 계곡에 있는 네싱바리 사파리에서 스킨 트레이너가 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["123:627170923"]="안녕하세요, 제가 찾고 있던 사람이 바로 당신입니다. 앉아서 들어보세요. 왜냐하면 우리 둘 다 부자가 될 계획이 있기 때문입니다."
rows["123:646375888"]="타락한 오크들에게 잡아먹히는 것과 노예상인인 라젤크라즈 밑에서 일하는 것 중 어느 게 더 불행하기 짝이 없는 인생인지 모르겠지만... 어쨌든 고맙습니다!"
rows["123:650008610"]="나랑 훈련할 준비가 된 사람을 거절할 순 없어"
rows["123:667264425"]="조심해, 아직 아무도 당신을 집에 초대하지 않을 거라고 생각하진 마세요. 하지만 적어도 그들은 당신을 총에 맞지 않을 겁니다."
rows["123:679942567"]="그가 그레이메인 성벽의 피난처로 왔을 때 자신의 사명은 피난온 사람들을 구하는 것이라 생각하고는 사랑하는 여인을 언덕마루로 보냈습니다."
rows["123:693621153"]="자니질, 자네의 문제로 들리길 원해요. 제클리크 대사님과 베노시스 대사님의 시체를 찾았어요."
rows["123:727600459"]="난 여기 어둠 속에 숨어 있을 거야, 문제가 생기면 목표에 빛을 비춰서 내가 돌봐줄게"
rows["123:73247415"]="내가 뭘 하고 있는 것 같아? 내가 직접 꾸려서 살 수 있도록$B$B내가 당신을 알아?"
rows["123:784338299"]="테라모르 이후 제 첫 본능은 오그리마를 십분화하는 것 - 도시의 모든 남자와 여자와 아이를 죽이는 것입니다."
rows["123:788550951"]="프로스트울프 묘지는 도로 옆에서 프로스트울프 마을에서 북쪽으로 멀지 않습니다.$B$B호드는 현재 이 기구를 통제하고 있다."
rows["123:805340328"]="스톰윈드의 사제들이 있는 광장에서의 빛의 대성당은 그곳에서 로레나 대사제를 만날 수 있습니다."
rows["123:827211300"]="|TInterface\\Icons\\inv_misc_head_dragon_bronze.blp:20|t 노즈도르무는 |cFFFFFF00|Hspell:105984|h[타임루프]|h|r로 가득 차 있습니다!"
rows["123:871579113"]="난 관장이고, 네가 그걸 알고 있어."
rows["123:877910139"]="이 계단도 전혀 희망적이지 않아서, 다시 정원에 가서 다른 방이 있는지 보자"
rows["123:883269405"]="다지크는 너처럼 더 털 없는 것들을 보고 있어"
rows["123:885013203"]="시간이 되면, 이 대리인을 이용해 오그리마 가로쉬 펠스크림의 머리에 충돌했습니다."
rows["123:893210555"]="걷고 있는 죽은 사람도 스스로 고쳐야 해 메리 에드라스는 여기 일을 처리해"
rows["123:938313391"]="(영웅적인 어려움에서 모든 전례적 만남이 패배하지 않으면 이 만남을 시작할 수 없습니다.)"
rows["123:945581598"]="비록 내가 명령했으나, 선택은... 마지막 발걸음을 내딛는 것은 그대의 뜻이다. 20초 안에 결정하거라."
rows["123:952848175"]="<파니 미스'는 불편하게  ⁇ 니다. 아니면 근처 전투에 대해 긴장하거나,"
rows["123:992757592"]="이봐 피즈, 내가 운하를 따라 내려가다가 날 벌목기로 무장하고 습격하려던 고블린들을 박살 내 버린 얘기를 안 해 줬던가?"
rows["123:994034399"]="누가 돌아왔는지 봐요,  ⁇ 은 입이 있는 반짝이는 새입니다."
rows["124:1018950201"]="얼굴 없는 장군인 Zon'ozz과 Yor'sahj는 적의 군대를 지휘하고 있습니다."
rows["124:102452831"]="내가... 난 리치 왕를 봤어. 잠깐만였지만, 그는 여기 있었지... 그리고 너무 추워졌어요."
rows["124:103573739"]="그래서 기사들은 천 명의 사나운 호드 오크 아저씨들이 계곡으로 쳐들어오는데도 자리를 사수하고 공격에 맞서 싸웠어."
rows["124:10885960"]="카르타크는 큰 혀의 맛을 좋아하지만, 카르타크가 배고프면 프렌지하트 맛은 상관없어"
rows["124:1091446349"]="우리는 메일스트롬의 중심에 있습니다. 디폴름과 아제로스 사이의 격리입니다."
rows["124:1118466552"]="모아키 항구는 두 개의 큰 해조류로 축복받습니다. 파도의 발자국과 녹색 섬."
rows["124:1118751011"]="많은 아르헨티나 문호들이 내 앞에 쓰러진 이자들 중 하나라고 할 수 있습니다."
rows["124:1127396650"]="그러나 너희 죄는 여기서 끝나는 것이다. 아무도 내 금지된 요새에 들어갈 수 없다. 나는 너의 뼈로 벽돌로 이 다리를 다시 짓겠다."
rows["124:1151103545"]="노인은 위대하고 그의 분노는 무서운 것이었습니다. 그는 희망을 소멸시키고 절망을 낳았습니다. 그는 용기를 숨쉬고 두려움을 숨쉬었습니다."
rows["124:1160334048"]="남쪽 길에서  ⁇ 빌 타스키비젯을 찾아보죠\010관심 있는 직업에 도움이 될 수 있어요!"
rows["124:1160821647"]="자유연합 추적장치를 다시 따라나갈 수가 없습니다. 가는 길에 살덩이괴물이 너무 많아요. 구조대를 보내 주십시오... 추적장치를 따라오면 됩니다... 이상!"
rows["124:1191958356"]="내 도움이 필요한 작은 동물이 있나요?$B$B<밀룬의 눈은 그 생각을  ⁇ 다.>$B$B지금 토끼를 포옹해야 해!"
rows["124:1206874028"]="다시 오신 걸 환영합니다, 영웅. 다시 한번 수호자를 보호하러 돌아왔어요."
rows["124:1207006536"]="수도사로서, 당신의 반사 는 가장 큰 자원이 되고 종종 생각 하고 빠르게 움직일 수 있는 능력 은 생명을 구할 수 있습니다."
rows["124:1240685826"]="너와 네 한심한 족속이 내 아들들과 나를 몰아낼 가능성은, 키린 토의 거지 같은 잔당들보다 나을 게 없다."
rows["124:1243936653"]="오, 잠시만요. 여행자분. 그늘숲으로 여행하실 모양인데 도움이 될 튼튼한 방어구가 있습니다요. 자, 지금 안토니오 페렐리가 호숫골에서 장사를 합니다요. 어서들 오세요."
rows["124:1274359182"]="캡틴과 그의 군대는 당신이 그를 위해 탐구했던 기지를 가져갈 수 있도록 추진했습니다."
rows["124:1278171637"]="한편, 오그리마의 도시에서, Warchief Garrosh Hellscream는 반다리아 대륙 전역에 갓린 파기팀을 보냈습니다."
rows["124:1285961555"]="내 이름은 익숙해 보이시나요?$B$B중요한 사람 이름을 따서 지어진 것 같아요"
rows["124:1289739127"]="스바보가 한 걸 보세요.$B$B넌 그런 옷에 자격이 없어, 하지만 스자보는 돈이 필요해"
rows["124:1310920945"]="내 친구, 베일 중심에 있는 빅 블로섬 광산 근처에서 만나게 되세요."
rows["124:1318071070"]="아나테라와 라테리온은 가장 격렬했던 전투 속에서 서로 등을 맞대고 싸웠지. 그 두 연인은 함께 살아남으리라 굳게 다짐했소."
rows["124:1335210575"]="첫 번째 구절은 모든 걸 사랑하는 팬리에 관한 것이지만,$B$B\"눈\"에 무슨 리듬이 들어?"
rows["124:1337850913"]="다음 영은 수, 물의 영입니다. 준비되면 동쪽의 노래 수영장에서 아이사와 만나십시오."
rows["124:1339015180"]="이제 이해가 됐어요. 이더리움과 빈자리 생물은 우리 생존에 위협이 됩니다."
rows["124:1379126658"]="귀여운 외모를 점점 잃는 것은 참 유감스러운 일이죠. 불모의 땅에는 \"옥상에서 떨어진 메주보다 아름다운 것도 없다.\"라는 격언이라도 있나봐요."
rows["124:1394032886"]="우두머리의 유물들을 잘못 가지고 있는 것 같네요."
rows["124:1440587393"]="한 번의 증기 수영장에 잠입하면 나이가 10년 더 젊어 보이게 되는데"
rows["124:1442622224"]="감사합니다 $p나중에 날 발견하면 우리가 모험에서 숨긴 물건 중 하나를 줄게"
rows["124:1446725268"]=" ⁇ 거리는 골리앗의 시간입니다. 15피트 정도의 털이 치솟는 분노,  ⁇ 라이 정상의 눈살을 자아내려는 공포, JOL'GRUM!"
rows["124:1468149511"]="신왕 라스타칸, 잔다라리족의 통치자라고 합니다. 그의 강력한 왕국을 왕좌에서 정금으로 조각한 것입니다."
rows["124:1469410437"]="걱정 마, 아무도 그 물건에 더 이상 손을 대지 않을 것 같아."
rows["124:147613901"]="대사님과 그의 군대는 당신이 그를 위해 탐구했던 기지를 가져갈 수 있도록 추진했습니다."
rows["124:1477533152"]="|TInterface\\Icons\\spell_shaman_earthquake.blp:20|tKuai the Brute는 그의 |cFFFF0000|Hspell:119922|h[쇼크웨이브]|h|r 능력을 사용합니다!"
rows["124:1491255281"]="스톰파이크 묘지는  ⁇  발다르 동쪽의 다리를 가로지르는 산으로 깎여져 있습니다.$B$B얼라이언스는 현재 이 기구를 통제하고 있다."
rows["124:1515085183"]="이 광석은 강력하고 악의에 찬 힘으로만 생성할 수 있습니다. 더 자세한 정보를 얻고자 정보 저장고에 접속을 시도합니다..."
rows["124:1520296024"]="누가  ⁇  옆에 폭탄과 상약을 남길까요?"
rows["124:1527732201"]="고통스럽지만 아름답습니다! 거트호크가 원하는 것을 제공합니다. 아제로스 최고의 순교 전시."
rows["124:1528269825"]="|TInterface\\Icons\\ability_deathwing_cataclysm.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:106523|h[카타클리즈미]|h|r! 그를 막아라!"
rows["124:1538429501"]="등에 들고 있는 검은 애쉬브링거라고 불립니다."
rows["124:1538941423"]="탐험가들의 리그 회원으로서 일했던 동안, 저는 아제로스에 다 갔지만, 블러드미스트처럼 아무것도 본 적이 없습니다. "
rows["124:1547599199"]="여기서 수리브어를 모으고 오염을 준비합니다."
rows["124:156035028"]="아빠는 항상 낯선 사람과 얘기하지 말라고 했지"
rows["124:1576492114"]="내 눈에서 이 망할 물건을 꺼내라"
rows["124:1586434960"]="당신은 내 Warchief이 아닙니다. 당신은 나의 존경심을 얻지 못했고, 나는 그것을 볼 수 없습니다 호드 전쟁에 대한 너의 어리석은 갈망으로 파괴되었습니다."
rows["124:163445576"]="탄약이나 다른 물품을 찾고 있나요?"
rows["124:1642369714"]="우린 함께 있어야 해요. 날 믿어야 합니다. 내가 옳은 일을 할 것임을 알아야 합니다. 우리가 하나로 행동한다면, 우리는 실패할 수 없습니다."
rows["124:1645471146"]="우리 충성심은 반복적으로 시험되고 증명되지 않았나요?"
rows["124:1645706266"]=" ⁇  시장이 걱정해서 Shado-Pan에게 전화해 왔어"
rows["124:1654786228"]="저렇게 생각했는데, 보통은 불타는 땅과 무감각한 학살이 없어서"
rows["124:1666907364"]="우리 캠프에서 다시 모이고, 친구이자 영웅으로 마지막이자 가장 위험한 탐구를 논의해 봅시다."
rows["124:1672998846"]="아카네의 주인 앞에 서 있는 당신은 저를 도전하는 것은 현명하지 않을 것입니다."
rows["124:1673117342"]="트롤은 널 구하러 온 게 아니야, 다크스피어."
rows["124:1680133969"]="그 보답으로 그는 소위 '저주'를 풀어줬어요. 우리를 '고쳐'서 기계 상태로 되돌린다면서 말이에요."
rows["124:1686618024"]="그대의 제안을 심사숙고해 보겠소, 선구자. 그리고 그대 편 사절에게 고문 역할을 맡기도록 하지."
rows["124:1698165558"]="널 구하러 온거 아냐, 트롤 칼림도어- 우린 적을 방해하는 동안 포항에 힘을 합쳐라!"
rows["124:1732317851"]="아직 훈련할 권리가 없어서 먼저 툰드랑 만나면 테이블에 와"
rows["124:1747283863"]="|TInterface\\Icons\\spell_fire_ragnaros_splittingblow.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:98951|h[스플릿링 블로]|h|r!"
rows["124:1758847772"]="|TInterface\\Icons\\inv_misc_head_dragon_01.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:113653|h[대 용의 호흡]|h|r!"
rows["124:1776278184"]="재건을 위한 중소 물품은 있지만, 프로스트울프 킨이 완전히 수리되기 전에 더 많은 것들이 필요합니다."
rows["124:1806786792"]="공사의 외치는 목소리는 황제의 적들의 마음속에 두려움과 의심을 심어주며, 그들을 그의 길을 따라 도망치게 만들었다."
rows["124:1827402475"]="하지만, 제가 여러분의 눈을 속이고 있다면?! 저 아래 뭐가 있는지 직접 확인하십시오! 이제... 연극을 시작하겠습니다!"
rows["124:1836680255"]="|TInterface\\Icons\\spell_shaman_totemrecall.blp:20|t 어둠의 샤먼 드롭 |cFFFF0000|Hspell:144291|h[ ⁇ 철 토템]|h|r!"
rows["124:1848234881"]="제플린은 전보다 더 나쁜 상황이야"
rows["124:186972080"]="|TInterface\\Icons\\spell_shadow_corpseexplode.blp:20|t %s 너무 많이 먹었고, |cFFFF0000|Hspell:126126|h[Upchuck]|h|r로 시작됩니다!"
rows["124:1884205072"]="걱정하지 마라, 케켁. 너 큰다. 광란심장 일족 위해 강해진다. 너, 고향으로 광란심장 일족 데려간다. 거기엔 새끼 날름이들 없다."
rows["124:1919628433"]="다시 만나서 반갑습니다. 어제만 돌고래를 살린 것 같습니다."
rows["124:1921112740"]="이 공은 바로 해변을 향해 지목된 것 같습니다. 새 덩어리 덩어리와 피우즈가 이미 설정되어 있습니다.$B$B얼마나 편리하냐!"
rows["124:1926460913"]="여기 있는 그런 사람 중 한 명도 몰라 오그리마 북쪽으로 가서 그들의 거침없이 한 사람에게 말해주세요."
rows["124:1932809917"]="호드를 물리친 후, 인간들은 이곳으로 돌아와서 우리의 생존을 기념해 과거의 위대한 도시를 재건하기 시작했어요."
rows["124:1936889914"]="|TInterface\\Icons\\sha_spell_warlock_demonsoul.blp:20|t %s는 캐스팅을 시작한다 |cFFF00000|Hspell:144400|h[Swelling Pride]|h|r!"
