rows["124:531295515"]="수고했네. 여기서부터는 혼자 가더라도 안전할 거야. 잿빛 골짜기의 마에스트라 주둔지로 가서 델그렌과 대화하는 걸 잊지 마시게."
rows["124:568017884"]="마로리아크, 이제야 실험실이라고 부르는 격리에서 나오게 된 건 얼마나 친절한지"
