rows["124:888167302"]="길네아스 외에는 오래전부터 아무것도 몰랐어요. 우리가 곧 다시 고향이라고 부를 수 있는 장소를 찾을 수 없을까봐 걱정했어요."
rows["124:889645125"]="그들은 공포와 속임수를 사용합니다. 전 세계가 그들의 어둠의 세력 앞에 무릎을 꿇자 형제와 다투는 일도 종종 생기고 있습니다."
rows["124:922042988"]="아, 여기 구경 왔던 게 기억나. 그럼, 그렇고말고. 새로운 친구한테 배운 걸 잊지 마, 작은 루. 네 미래는 멋져."
rows["124:948019767"]="명예, 용기, 연민, 그리고 정의! 텔잔, 너도 한때는 은빛 여명회의 사제로서 이런 가치를 위해 싸웠지."
rows["124:953440954"]="제 상품을 마음껏 탐색해 보세요. 마법에서 가장 우수한 것부터 최신 패션까지, 여기 모든 것을 찾을 수 있습니다."
rows["124:998339495"]="손님을 남겨 놓고 가기는 미안하지만 건수가 있어서... 이따 돌아올 거라고. 안녕!"
rows["125:1037296904"]="쿨루타스, 협동조합의 종들이 근처에 있어"
