rows["125:1054712714"]="여행자와 모험가 여러분! 어서 마을 광장으로 와서 이 안토니오가 파는 값 싼 물건들을 사세요! 얼마 없습니다요!"
rows["125:1058714533"]="|TInterface\\Icons\\spell_shadow_shadowfury:20|t다크 샤먼 코란탈은 |r|cFF9E09DE|Hspell:119971|h[Shadow Storm]|h|r!"
rows["125:1074544499"]="마을 사람들을 지켜야 돼, 전입구를 가져가면 나머지 사람들은 흩어져서"
rows["125:1087813465"]="그만, 너 둘은 날 미쳤어!"
rows["125:109750058"]="톨 바라드에서의 패배는 복수될 것입니다. 이 위대한 도시에 죽음을 가져다 줄 수 있도록 노력하겠습니다."
rows["125:1118617400"]=" ⁇ 커스 텍스틸즈는 스톰윈드 최고의  ⁇ 匠 중 한 명인 조지오 볼레로를 고용합니다. 마지스퀘어에서 가게를 찾아보세요."
rows["125:112605987"]="느껴져요. 아르코누스가 가까이 있군요. 북서쪽 길로 가십시오. 위로 가서 모퉁이를 돌면 아르코누스가 있을 겁니다. 전투 준비를 하십시오!"
rows["125:1136460151"]="<너의 놀라움으로, 랩터 새끼는 당신과 소통할 수 있습니다.>$B$B안녕하세요, 난 최근에 달걀에서 나왔어요."
rows["125:1158911705"]="남쪽에서 래우티키라는 트롤이 낚시를 하고 있는 걸 봤어요."
rows["125:1174343026"]="내 형제들, 침입자들을 죽이는 영광은 내게 있을 것이다. 그들의 약한 몸은 내 바람의 얼음으로부터 굳게 얼어붙게 될 것입니다."
rows["125:1222111386"]="마음속의 증오의 힘이 하나로 뭉치자 모든 것이 명확해졌다. 샤트라스와 함께 나루를 파괴해야 해."
rows["125:122531227"]="파발 리테! 마침내 찾아냈군. 이젠 오우거들과 어울리고 있나? 두려워 말라고. 탈영병이나 배반자에게도 자비의 손길을 베풀 순 있으니까."
rows["125:1240252716"]="당신 은 주 의 선물 을 받아들이기 위해 준비 되어 있습니까? 그분 의 사랑 의 분노 에 의해 축복 받거나 다른 사람 들 처럼 그것 으로 인해 멸시 될 것 입니까?"
rows["125:1253158305"]="이 문으로 열쇠가 필요하겠지?"
rows["125:1274302984"]="우리가 해야 할 일은 크라즈워크스 공항을 배치하고 일상적인 조사 임무가 시작되는 것뿐이었습니다.$B$B난 바보들로 둘러싸여 있어!"
rows["125:1277247940"]="우습구나. 내가 널 살려준들 네가 어디로 가겠느냐? 우리가 방금 너희 씨를 말렸는데 말이다. 기억하겠지?"
rows["125:1320176557"]="아빠! 나랑 놀아줘요! 재미난 이야기도 해줘! 예쁜 꽃도 꺾으러 가고! 아이스크림도 사줘요! 인형도 찾았는데... 내가 아빠한테 말해줬나?"
rows["125:133589428"]="조용히 조심스럽게 말해주세요. 잘못된 말이 여러분의 목을 잘라낼 수 있습니다."
rows["125:1348567969"]="평화유지군이 이 도시의 도둑들을 통제할 수 있는 힘을 가졌다면, 이런 일이 일어나지 않았을 겁니다!"
rows["125:1363124779"]="토르 모단 직송! 100퍼센트 순수 금속으로 만든 번개 동력 무쇠 골렘! 피녹빛파괴자를 소개합니다!"
rows["125:1364596928"]="샤만 자크 ⁇ 은 프렌지하트처럼 조용하지만 여전히 강해 카르타크가 우리보다 더 많은 사람들을 공격하지 않는 유일한 이유일지도 모른다."
rows["125:1375439398"]="물론 간호사가 되는 건 괜찮아, 그리고 모든 일을 해낸 후 사람들을 고쳐주는 것도 좋죠."
rows["125:138244099"]="가장 위대한 전사들이 잠에 빠지게 되고,"
rows["125:1391768468"]="저 저주받은 크리스탈, 우린 그렇게 쉽게 포기하지 않을거야. 우리 후손들에게 그 태블릿이 있을 거야."
rows["125:1396570797"]="타워 포인트 (Tower Point) 는 남쪽에서 전투장과 호드 영토 사이의 경로를 지킨다.$B$B호드에 의해 통제됩니다."
rows["125:142704921"]="환영합니다, 당황하지 마세요$b$b이건 내 자랑스러움과 기쁨입니다. 블래스텐하이머 5000 울트라 캐논!"
rows["125:1443196143"]="이제 여기를 떠도는 영혼들을 부르겠습니다. 백성을 구할 수만 있다면, 나는 아무것도 마다하지 않을 겁니다."
rows["125:1472477680"]="기기,  ⁇ 어,  ⁇ 어,  ⁇ 어,  ⁇ 어,  ⁇ 어, 도키, 또는 기지모를 찾고 있다면, 당신은 올바른 장소에 왔습니다!"
rows["125:1472862424"]="하지만 우리의 명령은 - 지옥의 비치는 여기 그의 발걸음을 잡을 것입니다. 우리는 얼라이언스 이 새로운 세계에 대한 주장을 허용하지 않을 것이다!"
rows["125:1505432380"]="우리는 새로운 적들에게 메시지를 보내기 위해 얼굴을 비추고 화염을 붓습니다. 우리를 괴물로 두려워하고 욕하는 사람들에게 선언입니다."
rows["125:15091188"]="너는 지금 스컬지의 신성한 땅 위에 서 있다. 성기사여, 여기서는 빛도 너를 보호하지 못한다. 그 무엇도 널 보호하지 못해..."
rows["125:1533050627"]="위대한 호랑이, 안개가 너머의 낯선 사람들은 믿을 수 없습니다."
rows["125:155615609"]="아, 제 학생 - 당신은 맨티드를 공부하고 싶으십니까? 경고: 판다렌 국경에는 전생들의 무덤이 가득합니다."
rows["125:1559201514"]="꽃이 이 황무지에서? 남쪽의 세진 마을에 있는 미시키가 그 꽃을 찾을 수 있는 방법을 가르쳐 줄 수 있다면"
rows["125:1563744786"]="이야기처럼, 야롱은  ⁇ 라이 평야를 여행하던 중 갑자기 두 개의 이상한 생물들이 그를 기망했다!"
rows["125:1585496136"]="애스리쿠스가 분노에 가득 차 당신을 가리키며 고막이 찢어질 듯한 고함을 칩니다. 그 후 아무 소리도 들리지 않습니다."
rows["125:1615730019"]="가끔은 여기 서서 호수 너머의 숲을 보고 있고 그 땅은 예전처럼 녹색이고 생명으로 가득합니다."
rows["125:1622105170"]="내가 뭘 가지고 일해야 하는지 봐$B$B<사보 서거>$B$B그래, 그래, 사보가 널 도와줄 수 있다고 생각했어"
rows["125:1628371431"]="적대적인 존재 감지. 위협 수준 평가 체제 가동. 주 목표물과 교전. 위협 수준 재평가까지 30초."
rows["125:1628729364"]="오그리마에 우리의 에이전트들은 어떻게? (도시는 돌과 모래로 뒤덮여 있습니다, 우리는 그것을 볼! 눈은 그 심장에 본다.) 나에게 눈을 가져와."
rows["125:1693959395"]="오래전 북풍이 이 봉우리들을 지배했을 때 강력한 타타카 상장의 형제는 그 땅을 자기에게 갈망했습니다."
rows["125:1695911209"]="공격자의 무기를 가져서 반격했지만 너무 많았어요"
rows["125:171051336"]="마사, 이 곡물에 문제가 있어요. 공자의 군인들이 이걸 찾고 있었어요."
rows["125:1715530823"]="어떤 적들은 그들의 무기에서 힘을 얻습니다."
rows["125:1720929563"]="이 교훈은  ⁇ 랑의 교훈입니다. 모든 사람들이 탐험가를 웃으며, 그가 돌아오기 전까지 웃습니다."
rows["125:1730251551"]="그럼, 여기서 무슨 일이 벌어지고 있을까요? $T 민간인: 민간인? 그건 귀여워진 게 아니냐?"
rows["125:173084518"]="여기서 뭐하고 있어? 이 죽은 가족의 먼지를 더 더 더 더 더 더 더 더 더 더 더 더 오염시키고 싶니? 이 곳을 떠나라."
rows["125:1740517450"]="아, 잘됐어... 얘기가 뭐지 모르겠지만 들어가고 있어"
rows["125:174315395"]="생존자들에게 살리기 로켓을 던져서 해적들에게 폭탄을 던지"
rows["125:1747505041"]="여기 경골을 자르고, 저기 동맥을 자르고 어떤 칼도 완벽한 살인 기계로 만드는 방법을 보여줄 수 있어요"
rows["125:1753894145"]="카르타크와는 거리가 좋지만, 우리가 그의 배가 가득한 한 그는 프렌지하트의 친구일 뿐이고, 큰 배도 있어요."
rows["125:1765197859"]="|cFFFF2222[Thundering Anvil]|r가 과부하되었다! |cFFFF2222|Hspell:138834|h|h|r에너지를 활성화하십시오."
rows["125:1781791383"]="내가 제대로 들었을 때, 당신은 이미 실바나르에 좋은 일을 하고 있습니다.$B$B계속해줘서 우리 집이 여기 있을지도 몰라"
rows["125:1804834136"]="네, 그래요. 성기사와 사제들은 모두 대성당 안에서 기술을 익히고 위대한 진리를 연구하는 거랍니다."
rows["125:1840340828"]="어렸을 때, 한 번은  ⁇ 에 대한 전쟁을 끝내겠다는 꿈을 꾸었는데..."
rows["125:1844117377"]="|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:107018|h[ 공격 측면]|h|r!"
rows["125:1862817447"]="쐐기돌을 합칠 수 있도록 도와준 당신에게 어떻게 감사해야 할지 모르겠군요. 장담하건대 이 쐐기돌로 인해 대단한 일이 벌어질 겁니다."
rows["125:1863157211"]="조르겐센은 정말 예쁘고, 그는 패라딘이니까 주변에서 말하는 것에 조심해"
rows["125:1876516088"]="콜드투트 광산은 호드 지역에서, 프로스트울프 묘역 북쪽의 산맥에 위치하고 있습니다.$B$B호드에 의해 통제됩니다."
rows["125:1881373808"]="우리들은 항구를 보호해야 합니다 얼라이언스공격이 노스렌드 시작하기 전에 멈출 것입니다!"
rows["125:189073121"]="|TInterface\\Icons\\inv_elemental_mote_fire01.blp:16|t당신은 |cFFFF0000|Hspell:100460|h[Blazing Heat]|h|r에 폭발할 것입니다!"
rows["125:190077092"]="|TInterface\\Icons\\ability_thunderking_lightningwhip.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:136850|h[Lightning Whip]|h|r!"
rows["125:190396079"]="|TInterface\\Icons\\spell_shadow_shadesofdarkness.blp:20|t%s는 캐스팅을 시작한다 |cFFF00000|Hspell:142842|h[쉬어 Y'Shaarj]|h|r!"
rows["125:1920790055"]="우리는 그들의 진정한 의도를 모르는 이성적인 사람들을 공개적으로 다루고 있습니다."
rows["125:1965338704"]="챔피언, 당신은 호드에 영광을 가져왔고 당신의 흔들리지 않는 의지로 우리의 위치를 확보했습니다. 이제 진정한 작업이 시작됩니다."
rows["125:1973065172"]="아, 그래. 그 쓰레기에 대한 얘기는 모두 들었지. 무게를 줄이려고 외장에서 보호재를 제거해 버리다니... 하! 말도 안 되지!"
rows["125:1986932888"]="제가 가르쳐준 기술을 여러분 모두에게 보여드리고 싶습니다."
rows["125:2021445280"]="에온 전, 타이탄들이 와서 우리 마스터들을 몰아넣었지. 하지만 이것은 그들의 세계가 아니었고 결코 없었어! 심판이 마침내 온다!"
rows["125:20254166"]="네가 날 죽음으로부터 구하지 않았다면 내가 널 죽였을 거야"
rows["125:2098962867"]="이번 건 별로 어렵지 않았던 것 같군. 두 번째 시험은 어떻게 해내는지 한번 볼까? 리스타, 리치 왕의 앞잡이들을 데려오게."
rows["125:2140205418"]="이리던 왕을 위해, 저는 이 멋진 몸매를 희생해 줄 것입니다."
rows["125:2140817267"]="|TInterface\\Icons\\sha_ability_rogue_sturdyrecuperate.blp:20|t %s는 캐스팅을 시작한다 |cFFF00000|Hspell:144563|h[감옥]|h|r!"
rows["125:2147241444"]="우린 운명의 주자크의 의지의 확장자일 뿐이야 힘과 경계로 있어 불타는 군단!"
rows["125:217570444"]="좋은 시장의 비밀은 분포가야"
rows["125:229278078"]="우리의 헌신적인 모습을 보고자 총사령관께서 직접 오셨다. 그렇게 축 늘어진 모습을 또 보인다면 내 손으로 널 없애버리겠어."
rows["125:233816414"]="한 번 뷰리 애플을 먹었는데, 맛있었어요.$B$B<유고는 먼 거리에 시선을  ⁇ 고, 마치 생각을 잃었다는 것 같다.>"
rows["125:238361723"]="산을 지나가는 걸 더 이상 용납할 수 있는 사람은 많지 않아요. 요즘은,"
rows["125:241150037"]="내 사람들은 대부분 네퍼셋 국경에 침투하면서 죽었습니다.$B$B제 의무는 그 희생이 어떤 의미로 작용하도록 하는 것입니다."
rows["125:320026029"]="시머는 샤트라트의 주요 스킨러이자 무역의 위대한 마스터로 하부시의 열린 시장에서 발견 될 수 있습니다."
rows["125:335956385"]="하루미에서 온 것인데, 그 단어에 무슨 뜻인지 알겠니?"
rows["125:346166061"]="어쩔 수 없이 내 뒤에서 내려가라"
rows["125:351133586"]="이봐, 당신이 신중하게 할 수 있다면, 이 마을에 나와 같은 사람들이 모르는 곳이 많아요."
rows["125:356406244"]="점심시간이 끝났어, 다시 일하자. 하루가 이렇게 잘 지났다면,"
rows["125:359166212"]="피나엄은 우리 소속 기드 레지스트리터이고, 그의 사무실은 에크소다르에 설치되어 있습니다."
rows["125:366490846"]="내 사람들이 당신을 신뢰하는 것은 내 결정이 아닙니다. 시장이 다른 결정을 내릴 때까지, 나는 당신을 친구로 간주합니다."
rows["125:380245282"]="코르야의 유적들은 중요한 일이 일어났던 곳이었어"
rows["125:386870727"]="어떤 공격 계획인가? 아우버딘은 재앙의 첫 번째 발작에서 파괴되었습니다."
rows["125:392705076"]="똑똑한 놈이 여기 숨어있어서, 흔적을 보호해줬지만, 내 퀴린견은 이 곳에서도 혀를 감지할 수 있어"
rows["125:405744240"]="난 문제를 일으키려고 하지 않지만, 만약 상황이 변하지 않는다면, 당신은 반란을 일으켜야 할 겁니다."
rows["125:412115411"]="잔다라리아 트롤들은 멀리 여행했고 이 곳을 찾아내기 위해 많은 고통을 겪었지만 아무것도 하지 않으면..."
rows["125:439434865"]="우는 몇 가지 숙제를 부탁할 거야 복잡하지 않은 일이 아니라 수도원의 유지와 관련된 일들일 뿐이야"
rows["125:465666406"]="몇 개만 더 더 있으면 우리 창고가 마차로 가득차게 될 거야"
rows["125:468508796"]="인간들은 찢어진 천막 봉투에서 벗어날 수 없지만, 요리하는 법을 아는 사람이 있다."
rows["125:473962554"]="카롤라이 아니스를 발견해서 북서쪽에서 집을 폭발시키려고 해"
rows["125:489826607"]="레물로스, 내 오랜 벗이여... 다시 만나 반갑네. 자네에게 어떻게든 그 전갈이 전해질 거라 생각했네."
rows["125:491137997"]="|TInterface\\Icons\\spell_nature_earthquake.blp:20|t유브리스 장군은 투수를 시작 |cFFFF0000|Hspell:74634|h[지방 포위]|h|r!"
rows["125:505085118"]="적을 이길 수 있는 능력을 증명해줬어"
rows["125:507830067"]="최근 일어난 사건들 가운데 우리를 약하다고 생각하는 것은 어리석은 일이었습니다."
rows["125:515318140"]="|TInterface\\Icons\\spell_druid_ursolsvortex.blp:20|t미닝 더  ⁇ 은 |cFFFF0000|Hspell:120099|h[자기장]|h|r를 생성한다!"
rows["125:51646269"]="|TInterface\\Icons\\inv_misc_bone_orcskull_01.blp:32|t$b$b구루바시 두개골을 골반에서 가져다가 트롤로로 떨어뜨려라!"
rows["125:518627331"]="거의 완벽한 샷은 조금 떨어졌지만 그럼러가 뭘 잘못할지 알 수 있어"
rows["125:521434073"]="이 재판에 참여하는 우리보다 무분별한 학생들 중 몇 명이"
rows["125:530557895"]="노인도락의 남동쪽 끝에 있는 리나리스가 가죽을 만드는 훌륭한 스탠드를 설치해"
rows["125:561178074"]="자연의 모든 힘이 나의 의지를 따른다. 미천한 존재여, 어떤 형상으로 네 고통을 끝내주길 바라는가?"
rows["125:581475212"]="천년 전에 kaja'mite가 우리를 똑똑하게 만들었지, 하지만 트롤들에게 아무런 영향을 미치지 않는 것 같지 않나요?"
rows["125:610964425"]="|TInterface\\Icons\\spell_fire_twilightpyroblast.blp:20|t%s는 캐스팅을 시작한다 |cFF00EEFF|Hspell:86408|h[Dazzling Destruction]|h|r!"
rows["125:635276581"]="- 여왕님! 호드이곳 서쪽에 있는 신전에서 숨어있었는데 밤 elf 경호가 포위하고 잠금했습니다"
rows["125:647098727"]="이 끈을 타고 안내해 줄게요. 만약 당신이 나로부터 너무 멀리 떨어져 있다면, 그것은 깨지고"
rows["125:656551064"]="두 개의 피그미가 상자에 있어 이제 조심스럽게 깎아야만"
rows["125:660383468"]="우리의 젊은 초신자들을 사냥의 방법에 대해 시험하는 것이 제 역할입니다.$B$B그리고 그것은 변하지 않았습니다. 오늘날,  ⁇ 보어는 우리의 먹이가 됩니다."
rows["125:662211209"]="롤 클럽의 첫 번째 규칙은 롤 클럽에 대해 말하지 않는 것입니다.$B$B두 번째 규칙은, 처음엔 롤클럽을 타면"
rows["125:667132475"]="카드리스 꿈꾼을 찾아라 그 여신과 샤마는 지혜의 계곡에 있는 트롤 요새의 입구실에서"
rows["125:684730225"]="임페리안에게 휴전할 의사가 있다고 알려라. 하지만 먼저 물보라가 내 땅에서 물장난을 그만둬야 할 것이야!"
rows["125:694140139"]="이제 폭풍우 요새에 남아 있는 블러드 엘프 녀석들을 몰아낼 때가 되었다. 무기를 들고 아달의 전장의 노랫소리로 기세를 올려라!"
rows["125:69795586"]="내가 속일 수 없었어요, 델로도르의 드레네이들은"
rows["125:703035256"]="이제 시작하자, 소방주께서 우리의 존재를 알게 되고"
rows["125:705675077"]="감사합니다, 대영주님. 도전자 여러분, 소환 의식을 시작하겠어요. 이 의식이 끝나면 무시무시한 파멸의 수호병이 나타날 거예요!"
rows["125:708210135"]="모가들은 우리를 파괴하려고 한다 모가들은 우리의 적이다$b$b도와줄래?"
rows["125:714599753"]="<그녀는 더 가까이 다가옵니다.>$B$B우리 둘 사이에, 이 밤 중 하나를  ⁇ 어내려고 생각 중이야"
rows["125:732779779"]="미안하지만 지금 내가 아는 것보다 더 많은 것을 다 알고 있어"
rows["125:735792015"]="하지만, 그 아이들이 정말로 천진난만할 뿐이라고 확신할 수 있습니까? 커서 우리에게 무기를 들이댈지 누가 알겠습니까!"
rows["125:742166898"]="우리 형제 자매들을 다시 데려오지 않을 것이지만, 우리가 야롱보다 낫다는 것을 아는 것은 밤에 더 잘 수 있도록 도와줍니다."
rows["125:752356490"]="이 호드♪ 내가 네 몸에 스프링 ♪ 호드우리의 적들은 약하고 분열되어 있지만 당신은 지옥의 잔소리와 협상해?"
rows["125:779591288"]="여기 책이 있습니다. 무슨 일이 벌어지는 건지 선리버에서 눈치채기 전에 반드시 이 책을 얼음왕관에 있는 칼라디스 브라이트스피어에게 가져다주십시오."
rows["125:827500123"]="우리는 당신의 요청을 듣고 동의합니다. 그것은 고귀한 의도입니다. 우리는 당신의 물을 정화 할 것입니다."
rows["125:841934898"]="내 힘이 네 힘으로 되어라 네가 해로운 공격에 대해"
rows["125:871158156"]="그 병에 대해 미안하지만, 오래된 점액을 보관하는 것이 더 낫습니다."
rows["125:878930373"]="새 전염병은 오래된 전염병의 맛을 모두 가지고 있지만, 오래된 전염병의 칼로리나 탄수화물이 없습니다!"
rows["125:881281801"]="챔피언스 홀은 구도시 남동쪽 끝에 위치하고 있습니다.$B$B명예와 정복의 분기장들은 거기 있습니다."
rows["125:903705852"]="그레시, 그레시, 왜 그런지 묻지 마요. 그레시, 그는 그레시의 아들이니까 그레시라는 타이틀을 줬고,"
rows["125:945712623"]="헤드리스 하더의 미생마는 집착한 거야 하로우의 끝 동안 이 마을에 대한 공격은 빈번하고 끔찍한 거야"
rows["125:963722359"]="부탁이다. 도망쳐라! 내가 자제력을 완전히 잃기 전에! 내 가슴 속에 검은 불길이 끓고 있다! 내뿜어야만 해!"
rows["126:1025289417"]="난 네 조상들에 대해 듣고 싶었어, 낯선 사람. 향수를 불어넣고 네가 어디서 왔는지 생각해 보자."
rows["126:1027476953"]="여행자, 전 세계로부터 온 보물이 있습니다.$B$B행운을 시험해보고 싶으면 몇 개의 시간없는 동전을 열쇠로"
rows["126:1047194785"]="꿈의 술은 깊은 명상 상태에 놓을 것이고 당신의 마음의 눈이 가장 큰 질문에 대한 답을 찾을 것입니다."
rows["126:1051129280"]="이 발전기는 미미론의 눈에 동력을 공급합니다. 힘이 모이게 내버려 두면 안 돼요. 순식간에 흙을 바수고 돌을 녹인다고요!"
rows["126:1063366886"]="네 죽음은 조금 늦춰졌을 뿐, 피할 수 없도다! 죽음의 군대가 얼음왕관의 심장부에서 일어나 행진할 때 공포의 요새가 동쪽에서 솟아오르리라!"
rows["126:106735241"]="내가 가르쳐 줄 수 있는 것들을 네가 모르는 것 같아$B$B진짜로, 뇌가 녹아들면 괜찮아 다른 곳으로 가서 놀아"
rows["126:1105031450"]="난 번개 섬에 많은 위험한 적들과 생물들이 있다고 들었습니다. 매일 위협이 변하는 것 같습니다."
