rows["126:1202236298"]="호드은 제 백성들에게 많은 도움을 주었고, 블랙 테플을 이리던의 지배로부터 해방시켰습니다. $B$B저는 상호 신뢰를 보여드리겠습니다."
rows["126:1204665150"]="한 가지에 대해 셰들이 옳습니다.$B$B우리의 가장 큰 적은 종종 우리 자신입니다.$B$B난 그렇게 큰 적이 아니었으면 좋겠어"
rows["126:1206793938"]="그건 인생의 순환이야 빛 트롤을 만들어 냅니다. 트롤은 공룡을 만들고, 공룡은 인간을 잡아먹고, 아제로스."
rows["126:1208335680"]="미렌과 저는 암흑문 양쪽에서 가장 좋은 사냥꾼입니다."
rows["126:1222838491"]="모고들은 우리의 적입니다. 그들은 우리를 이 세상에서 제거하려고 합니다. 왜 우리가 창조 신화를 믿어야 할까요?"
