rows["126:1270427406"]="실패했어... 내 임무에 실패했고... 우리 주민을 지키지 못했어... 늑대인간들은 미쳐 날뛰고 있고 여신께서 주신 낫은 잃어버리고..."
rows["126:1275161018"]="너희 전쟁은 무례한 파괴를 가져왔고, 심지어는 대왕도 너희 비행기나 폭탄보다 덜 위협적이다."
rows["126:1286655297"]="크고 반짝이는 마법 책으로 마법을 위한 글리프가 만들어집니다."
rows["126:1292888862"]="한 개가 트레이드맨 테라스에서 열렸어요. 남동쪽으로 가는 길을 따라 해안에서 찾으면 쉽게 찾을 수 있을 겁니다."
