rows["126:1303906806"]="마침내 그 마녀 아비데스의 부츠 아래에서 벗어나서, 내 자신의 이익을 추구할 수 있게 되었습니다."
rows["126:1309173915"]="우리의 육체가 먼지와 부스러기만 남을 때까지 모든 힘을 다해 싸울 것이다. 끝까지 싸울 것이야."
rows["126:133725682"]="그렇다면 역사에 대한 여러분의 지식을 시험해 보겠습니다. 아제로스를 통해 연결된 세계의 원래 이름은 무엇입니까?"
rows["126:1337664220"]="이 과수원은 썩어가는 내 모습처럼 메말라 생명을 잃었소. 한때 이 나무들에는 싱싱한 과일이 열렸지만 지금은 온통 썩은 것뿐이오."
