rows["126:1382836166"]="용이여, 나의 백성들에게 이런 참혹함을 보고 겪게 한 후에도 내가 또다시 짐을 떠맡을 것이라고 기대했는가? 물론 그대는 미쳤으니까 그럴 수도 있겠지."
