rows["126:1561134935"]="저들은 무자비하게 우리를 학살했지만, 진짜 목적은 성소 안 이곳에 보관된 알에 있는 듯하더구나."
rows["126:1561273486"]="당신의 음모가 당신의 계획을 알려줬으니, 전장에서 만나게 될거야."
