rows["126:1659643920"]="당신은 화염입니다. 당신은 불꽃입니다. 당신은 전 세계에 퍼질 것입니다. 당신은 아제로스의 잠재력을 깨울 것입니다!"
rows["126:1669606076"]="너희 형제들은 내 아이들을 해치려고 하고, 자기들을 윈드라이드라고 부르는 사람들은 땅을 파괴하고,"
rows["126:1674554180"]="거르탄 부족은 옳습니다. 오직 경건한 하르타크족만이 그들의 명령을 따르기 위해 더 작은 인종을 불러올 수 있습니다."
rows["126:1702676177"]="무슨 짓인가, 이실리엔? 한 때 명예를 위해, 백성을 위해 싸우던 자네가... 자네가 내 아들을 해치다니..."
