rows["126:1753905844"]="무쇠룬 피조물 모델명 U-9207는 당신의 말투가 마음에 들지 않습니다. 양탄자 소멸 작업을 시작합니다, 레브론스키."
rows["126:1776222898"]="프로스트울프 묘지는 도로 옆에서 프로스트울프 마을에서 북쪽으로 멀지 않습니다.$B$B얼라이언스는 현재 이 기구를 통제하고 있다."
rows["126:1780651971"]="영웅, 어둠의 소환자의 하인을 물리쳐야 해 그의 보호 마법을 약화시켜"
rows["126:1784614807"]="아니, 그 힘! 죽음의 날개의 마지막 재앙의 소환은 아제로스에 모든 생명을 파괴할 것입니다. 빨리, 우리는 그를 중단해야합니다!"
rows["126:1799456232"]="바보만 내 전복을 조롱할 거야$B$B이 잘 착용된 철의 옷은 고대 교육 장소에서 왔습니다!"
rows["126:1804570458"]="내 친구 카르닉, 살아서 자네를 직접 보고 싶지만 지금은 라그나로스에 대해 얘기해야겠네. 그의 영향력이 확장되고 있어."
rows["126:1811321668"]="내 대모, 내 백성의 지도자, 내 세상으로부터 온... 그는 두로탄의 아들, 네 손자"
rows["126:1827928503"]="내 백성들이 여러분을 환영했으면 좋겠습니다. 이 힘든 시간들 때문에 많은 사람들이 그들의 은혜에 경쟁을 할 수 있습니다."
rows["126:1846878982"]="이 토테마는 달걀을 손상시키고 있습니다. 더 큰 위협이 도래하고 있습니다."
rows["126:1853459620"]="으하하! 트롤플로우의 포가 놈들을 공격했을 때 그 표정이란, 참 가관이더군! 벌목기의 톱은 내 발끝에도 닿지 않았다네!"
rows["126:1853768547"]="파란색  ⁇ 은 큰 힘을 가지고 있습니다. 그들은 실라프 인우아를 통제하고 세계 다양한 민족으로부터 그것을 빼앗기 위해 일합니다."
rows["126:1879032630"]="남은 노예들을 모아 전투를 준비시켜 주겠고, 스콜러드 티라노스에게 맞서기 전에 널 잡을 거야"
rows["126:1888059256"]="줄무늬가 달린 멜론은 올해의 이 시기 꽤 정수적입니다."
rows["126:1890475135"]="광란심장 일족이 새로운 보금자리를 찾아 이곳으로 온 것도 그리 오래전은 아니다... 날름이 보금자리가 꽤 좋은 곳이어서 우린 그곳도 차지하려 한다. 어쨌든 좋은 놈들은 아니니까."
