rows["126:2024533039"]="희망의 붉은 크레인은 역사 초반부터 파다리아 시민들에게 영감을 주었습니다."
rows["126:2026474572"]="아지미, 자주 여기로 걸어와서 신선한 과일을 팔고, 물을 팔고 있어요. 배고프거나 목마른가요?"
rows["126:2027128638"]="|TInterface\\Icons\\INV_FIREARM_2H_RIFLE_CATACLYSM_B_01.BLP:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:93520|h[Pistol Barrage]|h|r!"
rows["126:2027231013"]="그롬그롬은 본 적 없어?$B$B한동안 아무도 못 봤어 아마 어쩔 수 없이 죽었어"
rows["126:2059512927"]="전방 방사선 펌프를 끄고, 부대들이 남은 기계화된 의복을 점령하고 메인 엔트리에 이동한다."
rows["126:2077884675"]="우린 아무것도 느끼지 못해 영혼은 여기, 리모바에서 남아있어요"
rows["126:2111581167"]="다르나서스 전쟁터 테라스에서 거주하는 밤 elf 무기 마스터 인 Ilyenia Moonfire는 활을 사용하는 방법을 보여줄 수 있습니다."
rows["126:2117936312"]="그곳은 숲의 심장입니다. 잿빛 골짜기 다시 한번, 우린 영원히 네 빚에 얽혀있어요"
rows["126:240562177"]="당신은 그의 통제에서 자유롭습니다. 그리고 당신이 더 작은 존재들에 의해 판단될 때, 적어도 스컬지 - 안돼!"
rows["126:248869799"]="견고한 상자는 나무 밀리 중간에 있으며, 그 뒤에는 잔해와 붉은십자군의 매우 열렬한 추종자들이 있다."
rows["126:303183264"]="여기 지상 병력의 사령관은 자리스리안이라는 잔인한 자인데, 그보다 더 강력한 힘이 움직이기에 두렵기만 하다."
