rows["126:313816187"]="더 이상 오지 않을 거야 포세이큰 고대 그레이만족의 전쟁 깃발에 의해, 저는 여러분들을 조상들의 땅에서 쫓아냅니다!"
rows["126:340945578"]="더 많은 사람들이 오고 있어요, 자신을 방어하세요. 마법 반대부에서 떨어지지 마세요! 그들은 보호 없이 당신을 찢어 버릴 것입니다!"
rows["126:367935315"]="내가 무슨 일이 일어나고 있는지 이해하려면, 변화를 가져오려면, 나의 헌신은 절대적이어야 합니다."
rows["126:375784190"]="그는 모든 것을 정의하고 정의로운 것으로 나타내고 또 다른 지루한 헛소리들을 표현합니다."
rows["126:39142345"]="저는 여행 전에 비전을 보았지만, 영원한 젊음의 꿈에 눈이 멀었습니다."
rows["126:40295489"]="이 자료를 이용하면 몇 달 뒤쳐질 거야"
rows["126:411790643"]="시간 없는 섬의 존재는 선형적 사고의 한계를 넘어 많은 것이 가능하다는 증거입니다."
rows["126:41221864"]="남풍의 힘으로 우리는 이 도시를 되찾고 우리 영토를 침범하는 사람들로부터 밀폐할 것입니다!"
rows["126:415735798"]="쥐, 쥐, 온통 쥐야. 어디를 봐도 쥐뿐이야. 조그만 구슬 같은 눈으로 항상 날 쳐다보지. 두고 봐. 전부 보여주겠어!"
rows["126:418333594"]="요리사들은 항상 신선한 채소를 찾고 있습니다. 농장에서 재배하는 모든 것을 요리용으로 사용할 수도 있고 다른 요리사들에게도 팔 수 있습니다."
rows["126:426392416"]="다시 한번 감사드립니다, 테렌디스 님. 도움이 더 필요하면 다시 오겠습니다. 그때까지 모험가들을 더 잿빛 골짜기로 보내 주시기 바랍니다."
rows["126:437347843"]="|TInterface\\Icons\\achievement_zone_cataclysm.blp:20|t%s는 거대한 |cFFFF0000|Hspell:138564|h|h|r를 채널하기 시작합니다!"
rows["126:443712107"]="내가 도와줄게, 하지만 먼저 네 백성에 대해 좀 더 알고 싶네."
rows["126:445657906"]="오랜 시간을 연구했지만... 아무런 성과도 없군요! 그들이 옳았나 봐요. 우리가 더불어 사는 방법을 배워야 하나 봅니다."
rows["126:460914014"]="영웅이라고 생각하는 필사자들은 깨진 홀에 들어왔어요."
rows["126:465312459"]="그들은 날개적이고, 이런 영들이 있고, 쉽게 주의를 기울이고 있지만... 그들의 비밀을 잘 듣는 사람들과 공유할 것입니다."
rows["126:470437754"]="하지만 지식은 힘이고 새로운 것을 공부할 기회를 거절하진 않을거야"
rows["126:487901325"]="용광로로 토석인을 한 무리 만들어내서 경비를 세우겠습니다. 하지만 가장 힘든 일이 남았어요. 로켄을 찾아서 저지하세요!"
rows["126:518103586"]="마지막이 될 것 같네요. 당신이 왔을 때 다행이에요. 내가 얼마나 더 숨길 수 있을지 몰랐어요."
rows["126:519889822"]="이 동굴은 위험한 것 같네요. 너희 셋이 분단하고, 한 명은 총을 들고, 나머지는 동굴로 분단합니다."
rows["126:528554910"]="내가 호젠, 위키츠를 배우려고 한다. 제이-썬 디 포가 내 모든 썰매를 먹었어. 그 때문에 난 그를  ⁇ 에 걸리겠다."
rows["126:568035333"]="아버지의 생령이 느껴져요. 분명 이 방향이에요... 이쪽으로 오세요, $n 님."
rows["126:580660472"]="오해하지 마세요...  ⁇ 도 스톰레이지 다시 받았다는 것에 감사하지만, 이건 정말 의심스러운 일이에요."
rows["126:585113070"]="실망스럽구나, 아카마! 내 몸소 저 벌레만도 못한 반역자를 심문하려 했거늘! 네 놈의 충성심부터 확인해 봐야겠다."
rows["126:612836776"]="이게 마지막이라 생각하지 마라. 우트가드 군대가 네놈들을 짓밟고 나면 네 시체에 침을 뱉으러 와 줄 테니!"
rows["126:652207244"]="당신 도움이 필요할만한 부실한 세상이 있어요."
rows["126:663133723"]="왜 전쟁 무기를 들고 왔습니까? 전쟁과 피 흘리는 것을 포함해서 이곳에 오는 데 어떤 목적이 있을 수 있을까요?"
rows["126:671443419"]="이 무기를 어떻게 쓸지 모르겠지만... 내가 여기 서서 위협적인 모습을 보더라도,"
rows["126:681722350"]="네나와 하오한 머드클라에게 증명해줘서"
rows["126:697394379"]="다크문 게임 토큰이 필요해$b$b이 게임 토큰을 파어에서 구매하세요$b$b네 지도에 하나 표시해 줄게"
rows["126:701944356"]="희망은 잔인한 농담입니다. 혹독하고 무관심한 세상으로 만들어졌습니다. 희망이 없습니다. 바네사만 있습니다. 바네사 반클리프"
rows["126:709775655"]="이 백악기 건 샤의 일인가? 이제 내가 보기에 우리 문명으로 전염되는 질병이 무엇인지. 감염된 사람들은 깨끗하게 해야 합니다!"
rows["126:726550880"]="변화의 바람이 불고 있고, 우린 그것을 무시할 수 없소. 나는 협정을 맺고자 과거의 수치와 타락을 떨치고 여기까지 왔소."
rows["126:738452933"]="좋아, 신병들 $p, 우리는 야롱올에서  ⁇ -라이 정상을 되찾고 다시 안전하게 만들 것입니다. 호드!"
