rows["126:768870265"]="너무 나쁘지 않겠소... 당신의 노력은 어쩔 수 없이 잠시 늦어질 것이다. 이제 내게 오십시오. 당신은 자신을 가치있는 희생을 증명합니다."
rows["126:781299224"]="노자리, 난 과거를 조작하여 자신의 위치를 향상시키려는 탐욕스러운 마법사에 대해 말하고 있는 것이 아니랍니다."
rows["126:786909122"]="아빠는 항상 이웃에게 도움이 필요하다고 했지"
rows["126:831084658"]="아카네 리포저를 찾고 있다면 마지 지구 바깥에 있는 매직 매장 안에 높은 기성 마지스가 있습니다."
rows["126:855884808"]="이방인, 자네와는 상관없는 싸움이다. 진홍십자군 정예병의 공격으로부터 몸을 지켜라. 나는 종교재판장과 일전을 치르겠다."
rows["126:880723044"]="알라틴엘을 찾고 있어 두 달의 성당 안에 찾을 수 있어$B$B네 지도에 그녀의 위치를 표시할게요"
rows["126:881935177"]="계속 그런 식으로 하면 상자에 처넣고 '불량품'이라고 써 붙여서 집으로 보내버리겠다!"
rows["126:900958159"]="스태그헬름은 흐느끼며 목숨을 구걸하리라. 그 아들놈이 그랬던 것처럼! 천 년의 한을 풀리라! 오늘에서야!"
rows["126:906279568"]=" ⁇ 이 내 손에 있을 때 그 힘을 풀어줄게"
rows["126:929836304"]=" ⁇ 은 태블릿을 구해줘 빨리 아이언포지로 가져와"
rows["126:940621473"]="나의 군대로는 퀴라지의 방어선을 뚫을 수가 없네. 용이여, 그대의 영검한 보호막을 칠 수 있을 만큼 가까이 갈 수가 없네."
rows["126:956791846"]=" ⁇ 돌탑이 크리스탈포지에 전력을 쏟아부었고, 더 많은 비밀을 밝혀냈어요!"
rows["126:967168662"]="브루머 마스터 블랑시는 폭풍의 한가운데에서 부머 브루를 만들려고 하지만 몇 명의 무서운 적들이 그녀의 길을 걸어가고 있습니다."
rows["126:967868052"]="얼라이언스 왜 타우라조를 공격하고 있어? 아이들을 데려가! 도망쳐!"
rows["126:985422872"]="최고의 것은 페렌올데의 얼굴이어야 했는데 우리 군대가 그의 앞 문으로 향했을 때"
