rows["127:1064422217"]="|TInterface\\Icons\\spell_nature_removecurse.blp:20|t다크 파라사이트는 |cFFFF0000|Hspell:133598|h[다크 페스트]|h|r로 변한다!"
rows["127:1067938673"]="당신은 환영받는 시야입니다, 말론의 아들아."
rows["127:1077529877"]="하지만 내가 아는 건 사랑으로 심도와 몸이 약해졌다는 거야"
rows["127:1082924851"]="여기서 내가 제일 똑똑하고, 강하고, 문화적인 골록이라고. 하지만, 감독은 전부 수세이가 하지... 이게 말이 된다고 생각해?"
rows["127:1107910558"]="콜드투트 광산은 호드 지역에서, 프로스트울프 묘역 북쪽의 산맥에 위치하고 있습니다.$B$B코볼드이 통제하고 있어요"
rows["127:111033178"]="넌 성공했어? 난 케인로리가 더 이상 속도를 늦추지 않았다는 걸 알아"
rows["127:1121077110"]="여기 보시면, 엽산층에서 수집한 오시디안 점포한 진흙이 있습니다."
rows["127:1136357479"]="\"Shalty\". 그게 내 이름이야. 네 이름은 \"Petsh'을 붙잡지 않아\"라고 해야 해."
rows["127:1140678499"]="여신이시여, 자매들이 계속 당해 그 수가 점점 줄어들고 있어 곧 저의 힘만으로는 악령숲의 악마들을 막아내지 못하게 될 것입니다."
rows["127:1170461027"]="레네 숙소장은 도시 중심에 있는 큰 건물로 이사했습니다."
rows["127:1219864057"]="수천 년 동안 나는 어둠 속에서 기다렸어, 침묵에서 고통받는 사람들의 외침에 의해만 뚫려졌어, 내 꿈은 깨어있는 악몽입니다."
rows["127:1242264711"]="이제야 진실을 알게 되다니, 가엾기 그지없구나. 나는 신의 힘을 휘두른다! 너는 필멸의 존재일 뿐이지. 날 쓰러뜨리겠다고? 꿈도 꾸지 마라!"
rows["127:1247949569"]="나그란드의 킬소로 포테시드의 발목은 당신의 뛰어난 기술에 속하는 악당에게도 상당한 도전을 줄 것입니다."
rows["127:1260104403"]="잘 들어봐요, 일이 힘들면 살릴 수도 있어요"
rows["127:1279182258"]="|TInterface\\Icons\\ability_druid_tigersroar.blp:20|t %s 은폐하고 준비하는 |cFFFF0000|Hspell:131271|h[스프링 오브 쉐도우즈]|h|r!"
rows["127:128207330"]="고대의 유물, 전쟁에 사용된 무기, 갑옷, 아니면 귀중품! 자, 이번 주에 안토니오가 어떤 물건을 가져왔는지 어서 와서 보세요."
rows["127:1287799008"]="남쪽의 괴물들에 대해 무슨 아는지 궁금했는데"
rows["127:1289390795"]="신나는 박자에 맞춰 마음껏 흔들고 싶으십니까? 지금 세상의 끝 선술집으로 오십시오! 타우렌 족장들이 정시마다 멋진 무대를 선보입니다."
rows["127:1294675957"]="만약 당신이 정말로 반려동물을 위해 죽은 자들을 신뢰한다면, 무역 구역의 상단 반지의 숙소에서 안야 마우레이와 이야기할 수 있습니다."
rows["127:1303027213"]="구름 반지를 날아다니는 것이 속도를 높이는 가장 좋은 방법인데"
rows["127:1316162632"]="마침내, 코루네의 마법꾼들은 그들의 악기를 주장하고 숨겼습니다. 그 이후로 벨은 역사에 사라졌습니다."
rows["127:1344290062"]="영웅들아, 빨리, 죽음의 날개의 재앙이 시작되고 세상을 끝낼 수 있는 순간이 될 거야"
rows["127:135685341"]="내 인생을 기억하는 거야 내가 가진 걸 가져서 나를 가만히 두"
rows["127:1360842152"]="아니... 이게 뭐지? 수갑 한 쌍인데 평범한 것은 아니군. 마법에 걸려있어. 이 짐은 물건이 아니라... 사람이었군!"
rows["127:1367127668"]="로로케임, 위대한 석사 화학자 그리고 스케티스 추방자, 하위 도시의 북서부 부분에서 다른 아라코아들 사이에서 살고 있습니다."
rows["127:139726560"]="루퍼트 보크라는 이름이 있는데, 그는 동남쪽의 겔로우스 엔드 타버너의 한 방에 있는 것으로 전해졌어요."
rows["127:1429935974"]="손상을 조사해봐요 얼라이언스 이 땅이 그들의 주장이라고 생각했나?"
rows["127:1437226413"]="|TInterface\\Icons\\ability_deathknight_remorselesswinters:20|t%s는 |cFFF00000|Hspell:142320|h[글래시얼 얼음 토템]|h|r를 소환한다!"
rows["127:1446442195"]="콜티라, 이상한 소리지만, 계속 유령을 볼 수 있어요."
rows["127:1450139499"]="다음 전투는 은빛십자군에서 가장 센 기사들을 상대해야 하네... 그들을 이겨야만 자신의 가치를 인정받을 걸세."
rows["127:1451132236"]="오, 우린 블랙록 마운틴 출신이야\010우리는 당신의 맥주에서 마실 온 것입니다!\010검은 철색 왜성들은 거짓말을 하지 않습니다\010그래서 그게 사실인 줄 알 수 있어요!"
rows["127:1462754866"]="난 항상 그런 소리를 들을 때, 언젠가 누군가를 잘라낼 수 있기를 바랬지만"
rows["127:1469905459"]="로데론의 모든 군인들은 즉시 스트라톨메 입구로 보고, 아르타스 왕자로부터 추가 명령을 기다려야 한다."
rows["127:1491020611"]="네, 네, 네, 네, 네$B$B몇 명의 신뢰를 얻었겠지만, 그 이상의 증거가 필요할 겁니다."
rows["127:1497347859"]="바로 알라보드에 발사할 수 있도록 라보를 붙여서 그녀의 작은 베개도 함께 싣고 가요"
rows["127:1520618334"]="판다렌 장로들은 진주들을 수도원에 허용하는 것이 현명했습니다.$b$b그 들 은 그 가구 에게도 같은 특권 을 부여 하는 것 은 현명 하지 않았다."
rows["127:1540571412"]="한때 유명한 오홀론 파스트라이더와 함께 사냥을 했습니다. 그는 토테임과 스키비에 불과한 사냥을 할 수 있는 타우렌이었습니다."
rows["127:1543727560"]="내가 여기 오기 위해 거꾸로 말을 걸려서 왔는데, 너무 위험해"
rows["127:1554901208"]="겨울 베일 축제는 추운 계절에 큰 따뜻함을 주는 곳이며, 그 중심은 오그리마입니다."
rows["127:1560477630"]="어떻게든 내 경호원들을 탈출해 왔어 귀신처럼 들어왔어"
rows["127:1579049811"]="이리던의 지휘 아래의 악마들은 레지옹을 침투하는 엔트로피적, 초록색 부패로부터 자유로워졌어요."
rows["127:1612969968"]="요일그럼은 아직 이 3개의 살인 기기와 전투를 할 준비가 되지 않았다고 해도 과언이 아니다"
rows["127:1675030636"]="타나리 사막은 이 오른쪽의 뼈처럼 거대한 뼈들로 가득 차 있어"
rows["127:1685488815"]=" ⁇ 스 로드와 얘기할 줄 알았는데, 지금 그가 존재하는지 아닌지 의심하고 있어요."
rows["127:1698773057"]="|TInterface\\Icons\\INV_MISC_FOOD_VENDOR_STRIPEDMELON.BLP:64:64:100:0|t$b$b<파니 여주님, 수박에 어떻게 하시겠습니까?>"
rows["127:1721734855"]="내 뼈가 약하고, 내 눈이 어둠만 보고, 내 몸은 고통만을 느끼고 있지만, 이 모든 것이 나만의 뜻이기 때문에 좋은 것입니다."
rows["127:1732130158"]=" ⁇ 도파나와 당신이 발견한 이 짐승의 도움으로,"
rows["127:1733736439"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 로켄이 포획하고 라저스케일로 변신한 강력한 원동물은 누구였을까요?"
rows["127:1735933359"]="네 말이 사실 같지만 왕도 혼자 이 결정을 내릴 수 없다."
rows["127:1752499122"]="|TInterface\\Icons\\inv_weapon_hand_30.blp:20|t 스노우드리프 마스터는 그의 |cFFFF0000|Hspell:106853|h[Fists of Fury]|h|r 기술을 사용합니다!"
rows["127:1762304465"]="\"그게 끝났어, 고드프리\"... 내가 절벽에서 뛰어내리기 전에 그가 말했죠."
rows["127:1792052838"]="다시 이 동굴에 들어가면 열풍수 문을 잊지 마세요."
rows["127:1793536253"]="여러분, 이곳이 스톰윈드 왕궁이랍니다. 1차 대전쟁 당시 호드에 의해 파괴된 스톰윈드 성의 폐허 위에 건설된 것이죠."
rows["127:1803485666"]="|TInterface\\Icons\\spell_fire_twilightimmolation.blp:20|t 초하색은 |cFF9900CC|Hspell:106395|h[최고 불안정성]|h|r까지 도달한다!"
rows["127:1827826723"]="전투나 임무는 잠시 접어 두고 이 멋진 물건들 한번 보시라니까요! 이 안토니오가 어둠골에서 장사를 한다는 건 신께서 은혜를 베풀어 주신겁니다요!"
rows["127:1831924397"]="얼라이언스가 이 지역으로 안전하게 수송하는 길은 단 하나뿐이네. 게다가 그마저도 저 무시무시한 안개 때문에 놓칠 위험에 처해 있지."
rows["127:1833348824"]="유령사령관이 있는 유령화랑 그 모든 것 같은"
rows["127:1848968629"]="그대들의 힘, 기술, 무용이 모두 꼼꼼히 평가될 것이다. 이 경기는, 아제로스 최고의 용사들을 가려내는 자리이다."
rows["127:1892444636"]="하이번은 돌아왔고, 그들과 함께 수백 년 동안 세상에 사라진 마법소송도 함께 왔습니다.$B$B내가 조사할 게 있어?"
rows["127:1901730758"]="저 친구 중 한 명과 전투를 하지 않고 자신의 긍지를 보여주고 싶지 않으신가요? 손님께서 어느 도시를 응원하든지, 손님께서 원하는 건 제게 다 있습니다요!"
rows["127:1917275855"]="네 얘기는 사실이야 하지만 우린 여기서 갈 거야"
rows["127:1924436308"]="예수 께서는 그 들 에게 힘 을 회복 시키실 수 있도록 도와주셨습니다."
rows["127:1960006186"]="다시는 하지 말아요! 다음번엔 부상당한 군인이 전선으로 돌아가고 싶어하면, 저는 내 발을 내려놓을 것입니다."
rows["127:1973471356"]="우린 마을에 있는 워건의 관심을 유지해야 돼, 젠."
rows["127:2002254336"]="돌에서 울리는 거침없는 목소리...$B$B안녕하세요, 장군님. 실리투스 소식은 어떤가요?"
rows["127:2008959699"]="네 불쌍한 불평은 그만해, 계속할 거야 리치 왕죽음도 넘어서"
rows["127:2034934127"]="저는 고대 기록관으로 돌아가 신호를 방해해 볼게요. 당신들이 그를 상대하는 동안 시간을 좀 벌어 보죠."
rows["127:2038171005"]="진짜 파티에 초대됐어 왜 항상 뭔가 일어나는데 내가 갈 수 없어?"
rows["127:2053471611"]="어쨌든 장비 테스트를 해야 돼$B$B몇초만 줘서 연습을 하러 올게$B$B준비 됐어?"
rows["127:2068109940"]="이 판다렌들, 내 친구들은 죽었지만 그들의 희생과 여러분의 숭고한 행위로 판다리아가 살아있다는 것을 알고 있습니다."
rows["127:209309824"]="조만간 수정 둠해머를 얻으면 전 이 마을을 등지고 곧장 오크에게 달려갈 겁니다. 그들은 그제야 후회하겠죠..."
rows["127:2102290800"]="내 개인용 인체 포터 테스트 준비됐어요"
rows["127:211422825"]="할아버지는 뱀의 척추 그림자에서 씨앗을 심었을 때 무슨 일이 벌어지고 있는지 알고 있었습니다."
rows["127:2122030045"]="이 링은 챔피언들이 서로 싸우는 연습장이고 제 임무는 기사들을 훈련 전투에 초대하는 것입니다."
rows["127:2127082633"]="내가 훈련하기 전에 아직 배울 수 있는 교훈이 있다. 썬더 블러프 도와줄 수 있어요"
rows["127:2134108972"]="마을 북서쪽 모퉁이에 있는 큰 진막 안에 파일 실린트스트라이드를 찾을 수 있어"
rows["127:227389141"]="아자크, 당신은 바위처럼 서 있습니다. 라카트는 더 움직입니다. 당신이 움직이면 또는 당신이 침수 sting 또는 bristlepine 발톱에 의해 상처받습니다."
rows["127:227928092"]="유일한 생존자인 '브로켄'로서, 제 의무와 영광은 '프어시어 노부두'의 샤머니즘 가르침을 계속하는 것입니다."
rows["127:259710128"]="그 때 참이었어, 네가 노란 배의 눈  ⁇ 자였다고 믿으려 하지 않았지만 지금은 의심할 여지가 없어"
rows["127:274917799"]="그리고 당신이 거기 있는 동안 발 아래 트롤을 걱정하지 마세요. 그들은 고대인들의 발걸음으로 땅에 걸려질 것입니다."
rows["127:294233543"]="자부심이 가장 속임수죠. 나쁜 때까지는 좋고, 그리고 그 다음에는 다른 모든 것보다 더 위험합니다."
rows["127:299624207"]="불모의 땅에서 배운 교훈은 불타진 땅만이 이 호드 동물들을 물리칠 수 있다는 것입니다."
rows["127:304260951"]="만약 당신이 나에게 물어보면 밤 엘프들이 이 지역을 잃었지 10천년 전 그들의 추방은 오늘 우리의 손에 불과한 형식일 뿐이야"
rows["127:308863044"]="이 언덕과 숨겨진 경로는 내 고향이니까 몇 년 동안 사냥에 사용했어$B$B전쟁에 사용할 줄은 몰랐어요"
rows["127:360410620"]="그는 칼이나 마술이 필요없고, 우리의 다음 도전자인 헤 ⁇ 스는"
rows["127:363843845"]="이런 건 정말 처음 봐요. 지배하는 동안 대상은 집중하지 못하거나 의식을 잃게 마련인데... 그녀를 어떻게 한 거예요?"
rows["127:369182498"]="자, 필멸의 존재여, 달라란에 있는 신비술사 티발린과 이야기하기 바란다. 그가 선리버와 협상해 책을 볼 수 있게 해줄 게다."
rows["127:378602641"]="키가 부족해지면서 마법으로 보완해$B$B멍청한 강아지들"
rows["127:422010562"]="|TInterface\\Icons\\inv_elemental_primal_air.blp:20|t ⁇ 은 미팅이 |cFFFF0000|Hspell:119981|h[Whirling Dervish]|h|r!"
rows["127:453508892"]="드렉 타르, 우리 민족에 영원히 충성하시오 영들이 당신을 축복해 주십시오."
rows["127:459828038"]="이... 이건 뭐지? 내 기도에 대한 답인가? 엘룬께서 악마를 물리칠 수 있도록 내게 이 낫을 무기로 주셨구나."
rows["127:479479322"]="우리는... 음, 빛, 지금보다 많은 금이 필요할 것입니다.$B$B그 얘긴 할 때, 훈련이 필요해?"
rows["127:480953138"]="우리 의 전쟁 은 우리 의 생활 을 희생 시켰습니다. 우리 는 얼라이언스의 승리 를 우리 와 우리 의 사랑하는 사람 들 의 피 로 지불 하였습니다!"
rows["127:493349085"]="휴식을 취하고 싶다면 무료 침대를 제공해줄 수 있어 편리하지는 않지만 "
rows["127:509819721"]="아치 드루이드는 이 골짜기 내 파괴적인 세력에 대해 알게 되면 숲의 주왕 이브스가 올 것이라고 믿습니다."
rows["127:518758912"]="체크포인트 가 어디 에 위치 하고 있는지 기억 해 보십시오. 깃발 을 어디서 들어 올릴 수 있는지 알면 가장 짧은 경로를 지도 할 수 있습니다."
rows["127:522906659"]="자네는 전쟁노래 요새로 돌아가야 하네. 헬스크림 님께서 이곳에서 일어난 일을 분명히 알고 싶어하실 걸세. 그리고 사울팽 님께도 무슨 일이 일어났는지도 말이야..."
rows["127:525479471"]="이 전 세계 영웅들을 환영할 것입니다. 호드 그리고 그들을 존중해 주며 오그리마!\010"
rows["127:525713588"]="반려동물이 여기 널 기다리고 있어 |TInterface\\Icons\\SPELL_NATURE_TIMESTOP.BLP:24|t"
rows["127:526619183"]="그대들은 그런 악마를 고대 신으로 알고 있다. 요그사론을 조심하라. 그 짐승은 입이 천 개이며, 그 악은 볼드랏실의 뿌리 너머까지 퍼졌다."
rows["127:527253302"]="난 이 왜성들을 그들의 게으른 속담에서 벗어나기 위해 모든 것을 시도해봤어$B$B더 강렬한 물건으로 만들어졌어?"
rows["127:533759601"]="아냐, 이럴 리가 없어! 이 약은... 중독을 치유하기 위해서였지 타락의 속도를 빠르게 해서 버림받은 자 따위가 되려고 이날까지 연구한 게 아닌데!"
rows["127:551951699"]="위대한 하르코아, 당신의 자녀 중 한 명을 불러주세요."
rows["127:566403931"]="네, 오그레들은 너무 멍청해서 내 문 닫을 수 없어서"
rows["127:584280402"]="|TInterface\\Icons\\warrior_talent_icon_lambstotheslaughter.blp:20|t당신은 |cFFFF0000|Hspell:127275|h[집행에 표시]|h|r!"
rows["127:590435468"]="타이탄의 아카이브에서 이 크리스탈과 태블릿을 발견했는데"
rows["127:59165783"]="전 한동안 일꾼이 선리버를 이끌고 있었다"
rows["127:62999831"]="거대들이 살고 있다고 소문들 노스렌드다발로 만든 턱이 있고, 죽은 시원한 눈으로 불을 끄는 거요."
rows["127:645121542"]="가끔은 끔찍한 사진들이 나눈다 밤에는 그림자가 우리를 공격하고 친구들은 서로를 공격하고"
rows["127:647193394"]="여기 새로 왔어요? 아이들이 물 속으로 들어가지 말라고 말하는 것처럼요."
rows["127:66645278"]="사실, 그랬어요. 저는 그것을 틀어서 아이언포지의 남자들에게 웃음으로 보여주려고 했는데,"
rows["127:682471588"]="중반 상승에서 아크나 리포저인 헤림이라는 피의 엘프가 도너스트라이더 매춘부에서 당신을 도울 수 있을 겁니다"
rows["127:683041858"]="보아라, 마치 마블라이트 컬트가 구 신들과 그들의 부패를 와임레스트로 가져왔던 것처럼 보입니다."
rows["127:692674325"]="맙소사! 이것 좀 보세요... 양초가 이렇게 많다니. 분명 어떤 끔찍한 의식이나 암흑의 소환 같은 걸 치르는 데 사용하는 거겠죠. 서두르는 게 좋겠어요!"
rows["127:727989177"]=" ⁇  발다르는 아주 나쁜 상태이고, 재건할 수 있는 물량이 부족해 얼라이언스 물품을 모으는데 도움이 필요해요!"
rows["127:750111366"]="스노프폴 묘지는 윈터엑스 홀드의 동쪽에 있는 전투 현장에서 언덕 꼭대기에 위치하고 있습니다.$B$B얼라이언스는 현재 이 기구를 통제하고 있다."
rows["127:751874429"]="그들이 숨어있는 곳이라면 Twilight's Hammer를 물리칠 것입니다."
rows["127:785543385"]="이 \"얼라이언스에 대해 모르겠지만, 당신은 신뢰할 수 있는 것처럼 보입니다."
rows["127:788119609"]="이 포털사이트가 건설되는 것을 모두 보았고, 공예에 감탄했고, 호드의 영광의 기념물로 어떻게 서 있는지도 보았습니다."
rows["127:791295966"]="언제 물어볼지 궁금했는데 오늘 못 가요 시장에서 일을 끝낼 때 곧 올게요"
rows["127:79764776"]="아비사일 해체에서 전투가 진행되고 있습니다."
rows["127:805599018"]="여러분께서 자리를 뜨지 않은 것만 봐도 블러드 엘프들이 얼마나 매력적인지 알 수 있죠. 그 말의 요지가 바로 그거였습니다. 전달하는 과정에서 약간 오해가 있었을 뿐이죠."
rows["127:82480325"]="코넬리 요원, 그 남자가 매력적이고 용감한 사람이야 아이언포지!"
rows["127:841416937"]="발사선이 불어, 이제 공격할 때입니다. 이 전투 깃발 중 하나를 가져와 호드의 묘지에 심어주세요!"
rows["127:869009478"]="이 비행은 싱링 리지의 가장 먼 곳으로 데려다줍니다. 매우 위험합니다!$B$B이 경우, 서명된 면제서가 필요해요"
rows["127:887749047"]="|TInterface\\Icons\\ability_vehicle_electrocharge:20|t%s's |cFFFF0000|Hspell:137422|h[전점 광명]|h|r 널 집착시켜"
rows["127:910161333"]="이렇게 해서 빠져나갈 수 있을 것 같아? 동지들이 날 구하러 오면 네 자만심에 대한 대가를 치르게 될 것이다."
rows["127:924508275"]="착각한 포저들이 공격하고 있어 그들의 귀여운 얼굴이 당신을 속이지 못하게 해"
rows["127:925668993"]="내가 익힌 무기들을 사용하도록 훈련시키는 것이 영광입니다. 만약 여러분이 스스로 배울 수 있는 능력을 가지고 있다면요."
rows["127:927721365"]="우리 는 같은 물 을 숨 쉬고 같은 신 을 숭배 하고 있었습니다. 그렇다면 왜 나가 들 이 우리 에게 반발 할 수 있습니까?"
rows["127:930874934"]="사르게라스 주, 내가 당신을 실망시키지 않을거야. 되살아난 자 불꽃과 어둠 속에서"
rows["127:933830001"]="차라리 혀를 깨물겠다. 이 쓰레기 같은 놈... 넌 부하들을 배신했어, 아서스! 맹세코 널 가만두지 않겠다!"
rows["127:969709234"]="물론 그래요, 제 귀여운 그리리 그리고 보세요. 미크로 메차치킨의 안정화는 완전히 성공한 것 같습니다!"
rows["127:993875926"]="브랜더 아이언햄러는 당신이 보고 싶은 사람이 될 겁니다 아이언포지."
rows["127:999941325"]=" ⁇ 도글렌은 안 좋아진다는 걸 알지만, 이 숲으로 돌아오는 것은 언제나 집으로 돌아오는 것과 같죠.$B$B항상 평화롭고, 항상 순수합니다."
rows["128:100462226"]="네가 고엘이야, 두로탄과 드라카의 아들야! 호드의 정당한 워치프라임!"
rows["128:1005197120"]="콜드투트 광산은 호드 지역에서, 프로스트울프 묘역 북쪽의 산맥에 위치하고 있습니다.$B$B얼라이언스에 의해 통제됩니다."
rows["128:1012097369"]="내 비전에서 적과의 협상은 우리 민족에게 일시적인 평화를 가져다주었고 그 다음에는 끔찍한 배신과 파괴가 있었다"
rows["128:1014570376"]="언젠가 라이트의 희망 사당에 가게를 열고 싶지만 난 전투가 아니지만"
rows["128:1014729916"]="마쳤어 영혼은 당신과 함께 있고 당신이 어둠의 해안에 있을 때마다 그것을 가지고 갈 것입니다."
rows["128:1040454040"]="물론, 어떻게 다른 방법으로 그들의 순위에 침투해서 드레네이처럼 지나갈 수 있었을까요? "
rows["128:104817737"]="저기요, 그건 제 잘못이 아니에요! 저기... 그러니까 돈을 돌려 드릴테니, 치유사에게 가보시면 되지 않겠어요? 제게서 뭘 바라시는지 모르겠네요!"
rows["128:104850889"]="대대사령 웨스트윈드는 계획을 가지고 있습니다. 우리는 이 계획을 충실히 수행해야 합니다."
rows["128:1059867300"]="네가 떠나서 공격한 후 캡틴이 쓰러져 그 놈들을 물리쳤고 나머지는 동굴로 물러났어"
rows["128:1070856571"]="내가 사라에게 증명한다면 그는 내 딸 중 한 명을 위해 싸우도록 허락할 것 밖에 없을 거야"
rows["128:1077284566"]="안녕하세요, 만약 여러분이 도블린 엔지니어링 스케마에 접근하기 위해 여기 있다면, 우리는 인증된 도블린 엔지니어만 접하고 있다는 것을 알고 있습니다."
rows["128:1089941598"]="워시프, 오해해 보군 가로쉬 펠스크림은 이 해변에 해안을 두고 있어"
rows["128:1103230779"]="우린 너무 많은 것을 잃었어, 워치프 우리 가족들은 죽었어 친구들은 잃었어 고향은 사라졌어"
rows["128:1146303392"]="환상은 이번은 멈추지 않을 거야 그들의 공격은 무궁무진해"
rows["128:1149410791"]="와일드햄어 왜들은 빠른 말들을 가지고 있을지도 모르지만, 그 에어리 픽 그리폰들은 그레이트 포지의 열을 견딜 수 있을까?"
rows["128:116058403"]="다른 경호원들은 서로 맞서기 위해$B$B우리도 돌아갔을텐데, 야리아의 빠른 생각 덕분에 안전해"
rows["128:1169765549"]="여기 북쪽으로 멀리 떨어진 빛의 전화가 들려요$b$b빛은 많은 세대 동안 알지 못했습니다."
rows["128:1172221371"]="|TInterface\\Icons\\inv_misc_monsterfang_02.blp:20|t %s은 그의 먹이를 자신의 |cFFFF0000|Hspell:126187|h[비서 사슴]|h|r! 그를 죽여라!"
rows["128:120427556"]="내 철을 \"고시장\"에 반해 할 수 있지만 그의 부패한 군대에 반해할 수 있습니다. 민간인을 피 흘리지 않도록 해!"
rows["128:1209916479"]="그는 모가족을 통합하고 다른 판다레인 인종들을 물리치고 정복한 사람들의 노예 노동으로 영광스러운 나라를 세웠다."
rows["128:1238319618"]="그런데, 은빛 여명회가 자랑하던 미덕의 수호자, 이니고 몬토이 신부가 어째서 자신이 그토록 증오하던 존재로 변해버렸을까?"
rows["128:1243472896"]="오래전 카르타크는 산에서 프렌즈하트로 왔고, 라크자크는 크라트크의 큰 혀 노예들을 먹여서 이제 카르타크가 프렌즈하트를 먹지 않는다."
rows["128:1246265765"]="테레잔의 세력이 스톤하더스를 공격하지 않도록 해야 합니다.$B$B그렇게 한다면 세계 기둥의 중간 조각을 훔칠 것입니다."
rows["128:1255903477"]="그 괴물들은 내 고엘을 훔쳤지만, 나는 그를 버리지 않을 것이다."
rows["128:1256865429"]="팔꿈치 기름 좀 넣고, 또 보통의 지방도 넣고"
rows["128:1267383719"]="생존은 항상 좋은 기술입니다.\010카에브루스, 보통 공원 중 한쪽 달수목에 있어"
rows["128:1278999658"]="히포그리프 (Hippogryph) 는 귀족하고, 자부심하고, 빠른 동물입니다. 훈련하는 것이 영광이며, 그 라이더를 빠르게 멀리까지 데려갈 수 있습니다."
rows["128:1289758208"]="진정하라고? 캘타스 님께서 그분께 실망을 안겨준 자들에게 어떻게 하시는지 알고나 하는 소린가, 기즐? 영원한 고통과 괴로움에 몸부림치는 거다... 이번 일을 망치면 알아서 해, 멍청한 고블린 녀석."
rows["128:1293573341"]="아, 어머.$B$B\"나는 하루에 충분한 시간이 없다고 생각합니다!\"$B$B너무 강제로 들렸어 시장에서 날 수 있다고 생각하니?"
rows["128:1303922769"]="뭐하고 싶니? 영웅의 계곡에 있는 이상한 드레네이 생물 중 한 마리에 대해 들어봤어요."
rows["128:1314522056"]="\"살리\"라고 부르고, 배에서 내려가서 처음으로 육지로 올라갔어요."
rows["128:1327635456"]="이 땅을 여행할수록 팬데라인 사람들의 사랑을 더 많이 받습니다."
rows["128:1347781772"]="우리는 대비를 해야 하오. 전에 언데드와 마주한 적이 있소만 그들은 감정이나 동정심이라곤 전혀 없는 무자비한 살인 기계요."
rows["128:1373521948"]="네놈이 정 그렇게 싸우고 싶다면, 그 소원을 들어주마. 하지만 네놈이 여기서 하는 짓은 아무것도 무쇠 거대괴수의 완성을 막을 순 없을 것이야!"
rows["128:1375298507"]="왜성무기 마스터인 부리우이프는 1개와 2개 팔의 축을 훈련시킬 수 있습니다 아이언포지."
rows["128:1379289067"]="네, 조심하십시오, 무라딘 형님. 함께하고 싶지만 세상에서 아직 보지 못한 가장 대단한 발견 직전이라서 말입니다. 지금은 이 일을 단념할 수가 없답니다."
rows["128:1385814248"]="아마 지구 어머니만이 그 원인을 알고 있을지도 모르지만, 이런 일이 계속되기 전에 우리가 뭔가 해야 합니다."
rows["128:1401841629"]="우리는 천상의 신뢰를 얻었고 밸리를 열었지만 우리가 평화의 임무에 있다는 것을 계속 보여줘야 합니다."
rows["128:1408443392"]="격노의 심장이라... 오래전 나는 벨렌이 격노의 심장을 사용할 때 그 힘을 몸소 목격했지. 지금 느껴지는 힘은 그때 그 힘과 똑같군그래!"
rows["128:1412701627"]="|TInterface\\Icons\\spell_frost_fireresistancetotem.blp:20|t 어둠의 샤먼 드롭 |cFFFF0000|Hspell:144290|h[Ashflare Totems]|h|r!"
