rows["128:1441795424"]="경고를 드리겠습니다. 이 레시피는 세대를 거쳐서 전해져 왔고, 위대한 원숭이 왕으로부터 제 가족들에게 가르쳤습니다."
rows["128:1443203418"]="위대한 티리온 폴드링을 쥐구멍에서 끌어내는 게 이렇게 쉬울 줄이야. 성기사여, 넌 이제 허허벌판에 섰다. 무엇도 널 지켜줄 순 없어..."
