rows["128:1590205271"]="당신의 지능은 전투 능력만큼이나 유용할 겁니다."
rows["128:1600322712"]="자네가 바람과 맞서 싸웠던 일은 벌써 수백 년도 더 된 일일세, 스톰후프. 자네가 그 바람을 약하게 한 덕분에 내내 잠잠했었지."
rows["128:1626775422"]="내가 맡은 일은 도시 보호를 위한 것이 아니라 그래서 그들이 너희를 평화유지군이라고 부르는지 모르겠어요"
rows["128:1638652745"]="수업의 특성에 대한 불합병으로 인해, 난 당신이 능력이 부족한 어떤 상황을 수정하는 데 도움이 될 수 없습니다."
