rows["128:1695101121"]="당신의 능력은 중요하지 않습니다. 당신은 충분한 경험을 가지고 있는 것처럼 보이므로, 저는 여러분의 도움이 필요한 문제입니다."
rows["128:1715578367"]="만약 당신이 더 많은 훈련을 위해 여기 있다면, 당신은 내 능력을 과대평가했습니다."
rows["128:1741546974"]="아빠는 조친의 벽 너머로 나가는 게 너무 위험하다고 생각했는데"
rows["128:1756460596"]="각 룬이 폭발할 때, 불의 발사기가 한 가지 또는 여러 개의 가까운 룬으로 이동하여 다음 룬 중 하나가 터지게 됩니다."
rows["128:1761651801"]="루테라랑 마을로 돌아가는 비행기를 찾고 있다면, 밤 엘프의 동료인 실바 필네벳과 이야기해봐"
