rows["128:1792279584"]="반갑습니다, 외부인들 스노우드리프 마스터가 학교 안에서 여러분을 기다리고 있습니다."
rows["128:1795950223"]="아, 너 둘은 친구가 될거야? 아마 습지에 좋은 곳을 찾아서 네 자신의 중간 언어가 있을 거야?"
rows["128:1808202154"]="오, 제가 방해가 된 것 같으면 죄송합니다. 저는 노스워치의 사람들을 두려워합니다."
rows["128:1808295677"]="바리트라스의 허약한 몸을 물에 돌릴 때 머리에 잔혹한 부상을 입었을 때 왜 살아남지 못했는지 알 수 있습니다."
rows["128:1810483888"]="전혀 없는데, 우리 스카우들이 게이트 앞에서 발견한 거대한 기계 구조와 관련이 있다고 생각합니다."
rows["128:1819308966"]="크롬쉬, 네가 뒤에 있어 반시 여왕이 잘 지켜졌는지 확인해줘"
rows["128:1829734540"]="그의 속죄가 올 때까지, 벌레는 자신의 운명을 탈출하고 노스렌드."
rows["128:1831816596"]="이 배가 찢어지지 않도록 할 수 있는 유일한 방법은 이뿐이고, 여전히 피즐 같은 거칠고 거칠고 난한 놈들을 다루어야 합니다!"
rows["128:1832224189"]="물론, 그녀는 드레스를 입고 있고 무릎이 틀린 방향으로 굽는 것도 있지만 그렇다고 널 다 걸을 수 없다는 건 아닙니다."
rows["128:1857932321"]="내가 말하는 대로만 해 이 전쟁은 무사히 끝나게 될거야 로데론 사건으로"
