rows["128:1885896791"]="스틸파인 홀드에 여행해봐 친구, 거기 있는 펄볼그들은 아주 도움이 됐고,"
rows["128:1894204641"]="위층의 경비원장이 열쇠를 갖고 있어야 돼 빨리 가"
