rows["128:1968477979"]="전직 챔피언이 은퇴한 날, 레오나 에어더윈드에게 손을 잡으세요!"
rows["128:1972445821"]="콘솔은 오래 된 것 같지만, 쇠퇴나 부패의 흔적 은 없다. 하나의 슬롯은 큰 원형 디스크 에 꽂아 있는 것 같다."
rows["128:1974369771"]="난 학생 뿐이야 리안논은 전문가야 저쪽 상자 옆에 있어"
rows["128:1995319527"]="여러분, 이제 선생님을 따라서 바리안 린 국왕께서 왕좌에 앉아 계시는 왕궁을 보러 가요."
rows["128:1995529467"]="스트롬가르드에서 숨어있는 데네브 워커가 첫 번째 구호 기술을 개선하는 데 도움이 될 책 있다고 들었습니다."
rows["128:2014417515"]="당신 자신감이 높고, 바르로쉬가 금지한 전염병을 사용하지 않길 바랍니다."
rows["128:2021176225"]="조상들, 힘을 줘 주 주둥이의 힘은 점점 커지고 있어"
rows["128:2034285379"]="지금 우리는 진전을 하고 있습니다. 이것은 확실한 방법입니다. 비록 많은 경비자처럼 보이지만, 정말 당신이 나를 도와야 합니다!"
rows["128:205030956"]="배고프게 해줘서 왜 너무 큰지?"
rows["128:2054264104"]="고맙네, 아카마... 내 가는 길을 형제들에게 둘러싸여 맞이하게 되다니 영광이로군. 친구여, 안녕히... 우리 종족을 잘 부탁하네."
rows["128:2054495181"]="아마 위대한 수강자의 재능을 가지고 있을 것 같지만, 제가 여러분에게 무엇을 가르쳐 주기 전에 "
rows["128:2057126128"]="마구, 워치프. 판다레네 역사의 책에서 그들은 잔인하고 불쌍한 지도자로 기록되어 있습니다."
rows["128:2073747867"]="잘했어, 다른 사람들이 뭐라고 했든 내가 옳았어"
rows["128:2089286098"]="해 초에 우리 장로 들 은 잠시 방문 하여 살아 있는 사람 들 에게 조언 을 주고 조상 들 과 함께 온 사람 들 을 환영 합니다."
rows["128:2112620074"]="얼음혈 묘지는 전쟁터 남쪽에 있고 얼음혈 탑 동쪽에 있습니다.$B$B호드는 현재 이 기구를 통제하고 있다."
rows["128:2128086585"]="아니, 아니, 난 용 비행을 배신하지 않았어. 우리 모두는 배신당했다. 이세라는 꿈에 사라졌는데 이 세상이 무너져 내렸다."
rows["128:2128158090"]="좋다. 일이 이렇게 되어 슬프구나. 너희를 모두 내 자식처럼 생각했건만... 그래야만 한다면, 죽여 주마!"
rows["128:214572415"]="저기요, 오늘은 방패를 팔지만, 철퇴는 없답니다. 멍청한 누군가가 제가 판 무기로 정신을 좀 차리기만을 바랄 뿐이에요."
rows["128:2146429188"]="은빛십자군이 여는 마상시합에 여러분을 초대합니다. 다른 아제로스의 용사들과 명예로운 전투를 치르고 자신의 실력을 가늠해 보십시오."
rows["128:2182934"]="하지만 집중해야 합니다. 내면의 조화가 이 땅에서 생존을 위해 결정적입니다."
rows["128:227570701"]="너? 넌 아이언하이드의 차기 재는 장난감이 될 준비가 돼 있어? 아니면 얘기할 준비가 돼 있어?"
rows["128:263781954"]="이게 뭐지? 용사들이 날 도우러 왔다고? 어둠의 존재가 개입한 기운이 느껴진다. 정말 이 신성한 행사는 그의 축복을 받은 것인가?"
rows["128:274469385"]="잘 해, 영웅들, 이 짐승을 보내기 위해 만들어진 바로 그 포털로 돌아가자 썬더 블러프."
rows["128:276118984"]="은빛 여명회와 은빛 성기사단이 하나가 될 것이다! 수많은 이가 실패했어도, 우리는 승리하리라!"
rows["128:286039579"]="전투는 승리했고, 그들이 소중한 성전으로 도망치면서 지켜봐요. 곧 모든 사람들이 파괴될 것입니다. 그들의 지도자들은 파괴 될 것입니다."
rows["128:291107016"]="이제 언더시티로 진군한다! 왕의 권능으로 그대들에게 힘을 주노라! 나를 따르라, 영웅들이여! 얼라이언스의 영광을 위하여!"
rows["128:291385066"]="스컬지 군대여, 내 말을 들어라! 붉은십자군 대참사가 시작됐다! 이 땅을 갈가리 찢어발기고, 너희가 지나간 자리에 죽음만을 남겨라!"
rows["128:306211011"]="|TInterface\\Icons\\spell_fire_fireball.blp:20|t 하얀 더 언스톱블은 캐스팅을 시작한다 |cFFFF0000|Hspell:120167|h[Konflagrate]|h|r!"
rows["128:332819746"]="조심해, 앞 문은 너무 많이 보호돼 있어"
rows["128:337540847"]="...그것에 대해 확신이 없지만, 전 여러분에게 말할 수 있습니다. 어떤 위대한 제국은도"
rows["128:33854041"]="수호자의 흠집 없는 심장을 얻어 도전 정신과 힘을 보여라. 질투심 많은 짐루크가 거느리는 자들이 그것을 숨기고 있다."
rows["128:348502283"]="믿음이 충만한 자는 높임을 받으리라! 하지만 아직 할 일이 많다. 우리는 온 아제로스가 그분의 그늘에 놓일 때까지 진군할 것이다!"
rows["128:364308801"]="말리고스는 너희 지휘관이 이 협정을 가장 우선하여 처리할 것이라고 내게 친히 말했다. 이제 길을 비켜라!"
rows["128:379238329"]="첫 번째 임무는 이 사악한 영혼의 기관 안에서 죽음의 기계를 파괴하고 병사들이 나아갈 길을 마련하는 거예요."
rows["128:395852173"]="이 먼 지역에서 다른 사람을 보는 것이 얼마나 좋을까요?"
rows["128:404072810"]="내 최고의 군대를 데려가라 걱정마, 배틀메이든 빨리 우리로 돌아가"
rows["128:412550717"]="그  ⁇ 은 버려지고 무력해 보입니다.$B아마 근처에 있는 곳이 있을지도 몰라서 전투장과 조화를 이루는 곳도 있어"
rows["128:414951979"]="괜찮아, 여자들이여, 그냥 제 그림을 봐서 더 좋은 날들을 기억해 주세요. 아니면 저를 보고 더 나은 미래를 상상해 보세요."
rows["128:431038281"]="너희 가운데는 몇 년 동안 평화로운 사람이 아니라 여러 해 동안 무작위로 앉아도 많은 세월 동안 싸웠던 사람들이 있습니다.\010"
rows["128:439728053"]=" ⁇ 키를 찾고 있어? 내가 말한 걸 듣지 못했지만..."
rows["128:474989686"]="언젠가 더 많은 세계를 볼 수 있을 때, 다시 와서 나와 이야기해봐요."
rows["128:512365636"]="우리는 그 지역에서 전염병의 상태를 파악하는데 어려움을 겪고 있습니다. 곧 다시 확인해 보시면 더 나은 아이디어를 얻을 수 있을 것입니다."
rows["128:512510158"]="여성 블러드 엘프 사령관의 가물거리는 환영이 나타납니다. 주변 풍경으로 보아 그녀는 폭풍우 요새 안에 있는 것이 분명합니다."
rows["128:524769849"]="타워 포인트 (Tower Point) 는 남쪽에서 전투장과 호드 영토 사이의 경로를 지킨다.$B$B얼라이언스에 의해 통제됩니다."
rows["128:540904610"]="큰 두려움에 직면해 검은 황소들은 나에게 용기를 가르쳐줬습니다. 공포와 어둠 속에서 인내했습니다. 두려움은 물리쳤습니다."
rows["128:548117568"]="조심하게. 이전에 우리를 구했던 그 저주받은 검에 대해 들은 적 있네. 서리한 때문에 무엇이 생겨났는지 주위를 둘러보게나."
rows["128:574834903"]="그는 우리 모두에게 옛 영광을 되찾을 기회를 제공해 다시 진정한 톨'비르가 되도록 했습니다.$B$B하지만... 우리가 그에게 충성을 맹세한다면만"
