rows["128:625534490"]="그럼 호위는 누가 합니까? 무슨 일이라도 생기면 일리단 님께서 절 가만두지 않으실 겁니다."
rows["128:633755765"]="분석 결과 시스템의 손상이 발견된다면, 이 행성을 재창조하는 것이 전 우주를 위하는 길이다. 방해하지 마라."
rows["128:638292178"]="|TInterface\\Icons\\spell_shaman_thunderstorm:20|t%s는 강렬한 |cFFFF0000|Hspell:137313|h|h|r를 채널하기 시작합니다!"
rows["128:654112134"]="본래의 홀은 이곳 동쪽에 있고, 타나리스 사막 모래 근처에 있습니다."
rows["128:656103697"]="네, 당신은 치료자 나나를 찾고 있어요.$B$B네 지도에 그녀의 위치를 표시할게요"
rows["128:658287380"]="레슨과 기름은 예매크가 가르쳐줄 것 같네요"
rows["128:683500660"]="|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:143497|h[Bond of the Golden Lotus]|h|r."
rows["128:710028044"]="내가 널 따라다니는게 싫냐?"
rows["128:714302076"]="우린 거의 이 전투를 시작할 준비가 됐어 형제들아,  ⁇ 지조그 왜 엉덩이를 덮고 있어?"
rows["128:724141746"]="타워 포인트 (Tower Point) 는 남쪽에서 전투장과 호드 영토 사이의 경로를 지킨다.$B$B이 둘 다 통제됩니다."
rows["128:738356243"]="네더가르드에서 상황이 좀 안좋아질 수도 있어 왜쟁이는 잠시동안 일을 그만두기 위해 술 한잔만 먹어야 할 때가 있어요"
rows["128:789990861"]="|TInterface\\Icons\\inv_misc_head_dragon_blue.blp:20|t 칼레고스는 |cFF0000FF|Hspell:105903|h[마법의 원천]|h|r!"
rows["128:794965670"]="우리는 공허한 공을 없이 황후를 위해 목숨을 바칠 것입니다. 빛그리고 그녀 없이는 우리의 삶은 어둠에 사라질 것입니다."
rows["128:831935782"]="내가 널 여기 못 뜯어내는 게 행운이야, 조롱자야"
rows["128:840188817"]="|TInterface\\Icons\\ability_warlock_baneofhavoc:20|t%s가 출연하기 시작한다 |cFFFF0000|Hspell:126299|h[Unleash Souls]|h|r! 빨리 움직여라!"
rows["128:883933838"]="치유 크리스탈을 보완해줘서 다시 고마워요."
rows["128:886281542"]="고대의 해적 Dice를 조심스럽게 굴리는 경우 9, 그에게 |cFF3366FF|Hspell:142107|h[거운 피부]|h|r."
rows["128:904840901"]="모든 사람이 코렌의 독한 맥주를 맛볼 수 없다는 게 아쉽군요! 불경스러운 말인 줄은 알지만, 검은무쇠 드워프 녀석들이 부러울 정도라고요!"
rows["128:909812347"]="오늘 수천 명의 정신을 돌려줬지만, 널 묶어서 봐서 전 기꺼이 교환할 거야"
rows["128:911828064"]="리야라, 두 명만 남았어요. 내 목숨으로 맹세합니다."
rows["128:913619086"]="첫 번째 목표는 여기 길네아스 유적에 있습니다."
rows["128:94086841"]="(한호가 다시 불을 지르고 불꽃이 피고, 그리고 어떤 텍스트 기반의 형태를 통해 감사 표현하는 놀라운 완성 이벤트)"
rows["128:945904627"]="이 구멍에 앉아있다는 건 지쳤어."
rows["128:963877287"]="우린 깊은 곳의 보호와 편안함을 착취하기 위해 선택했어요."
rows["128:973124735"]="눈은 영혼의 창이라고 합니다. 만약 그렇게 된다면, 이 손님과 그들의 영혼은 숨기는 것이 있다고 생각합니다."
rows["128:975821528"]="고대의 해적 Dice를 조심스럽게 굴리는 경우 9, 그녀를 인정 |cFF3366FF|Hspell:142107|h[거운 피부]|h|r."
rows["128:999449350"]="이 계곡 안에 있는 강력한 비밀을 알지 못해 내가 그들을 가져다가 너희 종들을 모두 파괴할 것이다."
rows["129:101232236"]="비극이야... 저들은 용감하게 싸웠지만, 노스렌드의 야수들이 승리를 거뒀네. 쓰러진 영웅을 위해 잠시 묵념을 올리세."
rows["129:1012659140"]="'대투'라고 부르면, 혁명을 시작하게 될 거야."
rows["129:1080313085"]="철수자들은 모두 공예의실에서 왼쪽으로 들어갑니다.$B$B지도에 위치를 표시해 줄게요"
rows["129:1080476090"]="에코 섬 공격이 곧 시작될 거야$B$B쉬고 앉아 이 노래는 아노타에서 끝납니다 $5071W 몇 분 후에 가자"
rows["129:1090142464"]="제발 $p오늘 우리가 뭘 했는지 가르로시에게 말하지 마요."
rows["129:1131830279"]="날 죽이러 보냈어 너무 예측할 수 있어$B$B하지만 넌 그 사람들 중 한 명도 아니야"
rows["129:1163800927"]="그래, 전쟁주님 함정이 준비됐습니다. 신성 벨은 이 동굴 안에 안전해"
rows["129:1172258051"]="저 어리석은 원로원의원들을 제거해줘서 고맙군. 이제 라그나로스의 가장 강력한 부하의 손에 죽을 준비나 하게."
rows["129:1179728744"]="키린 토의 마법사여, 브란의 명령에 따라 보호막을 해제하라! 목숨을 걸고 이곳과 우리의 동맹을 지켜라! 달라란을 위하여!"
rows["129:1186211700"]="오세요, 내가 보여드릴게 가장 멋진 짐승을 타고 다니는 방법을요"
rows["129:1195739287"]="다른 사람들과 함께 남길 수 있어 북쪽으로 데려가라 난 와이버너들과 함께 도망갈 거야"
rows["129:12173082"]="친구, 기회가 되면 입을 다물지만 가끔 침묵을 제외하고는 다른 소리를 듣는 건 좋죠."
rows["129:1248981343"]="이 잡지의 페이지들은 거래, 구매자 및 다른 다양한 비즈니스 관련 사건에 대한 정보로 가득 차 있는 것 같습니다."
rows["129:1258885827"]="토로와 나는 불지방 침략에 참여하고 함께 살면서 함께 싸우고 함께 죽고 형제들이 그러기 위해"
rows["129:1270903953"]="...그리고 그 길을 떠나면, 너랑 너의 무더운 친구들은 내 목록에 다음이 될거야"
rows["129:1298861054"]="난 귀가  ⁇ 어버리고 있어요 그 큰 녹색 하피는 5초 동안 입을 다물지 않을 거예요"
rows["129:1309832165"]="농담이야, 장트레이즈는 오래 전에 찾았어."
rows["129:1313415762"]="머나먼 알터랙 산맥에서 왔습니다! 지금껏 이 투기장에 모습을 드러낸 이 중 가장 강력한 전사, 피의 광전사 콜라크입니다!!!"
rows["129:132347601"]="하지만 어느 날 원숭이왕은 망치를 훔쳐서 장난으로 숨기기로 결정했습니다. 그 이후에는 망치에 대한 기록도 없습니다."
rows["129:1340690843"]="우리 계열에 가입하고 싶은 모든 분들을 환영합니다. 하지만 시작하기 전에 더 많은 경험이 필요합니다."
rows["129:134141317"]="가로쉬는 구제할 수 없지, 할아버지는 마하르에게 도움을 주면서 가로쉬가 지도할 능력이 없다고 확신하게 됐다고 생각합니다.\010"
rows["129:1376032521"]="내 참새의 발자국 능력을 이용해서 땅 자체를 찢어내려"
rows["129:139097697"]="|TInterface\\Icons\\spell_shaman_stormearthfire.blp:20|t 알리스라저는 |cFFFF0000|Hspell:100744|h[Firestorm]|h|r를 충전하기 시작합니다!"
rows["129:1396225166"]="처음으로 안도감이 느껴지는군요. 저는 당신을 모르지만 당신이 원한다면 목숨이라도 바치고 싶습니다."
rows["129:143396024"]="얼라이언스은 제 백성들에게 많은 도움을 주었고, 블랙 테플을 이리던의 지배로부터 해방시켰습니다.$B$B저는 상호 신뢰를 보여드리겠습니다."
rows["129:1455877206"]="아르코니소스는 없어졌어$B$B킬제덴은 해방됐습니다. 세계 영웅들이 이제 우리의 유일한 희망입니다."
rows["129:1479144922"]="필멸의 존재여, 쓸데없이 참견한 대가를 치르리라. 주인님께서 거의 깨어나셨다. 완전히 일어나시는 날, 너희 세계는 끝이다."
rows["129:1495280663"]="|TInterface\\Icons\\ability_thunderking_thunderstruck.blp:20|t%s가 출연하기 시작한다 |cFFFF0000|Hspell:135096|h[Thunderstruck]|h|r!"
rows["129:1500160507"]="뭐야, 내가 더  ⁇ 어  ⁇ 어 놔두고"
rows["129:1513805765"]="이쪽은 정말 추운데... 그래서 왕의 아들 아르타스는... 우더와 함께 악과 싸우고..."
rows["129:1533339260"]="네, 겁쟁이 탐구자여, 화려한 말 위에 앉아 오르쿠스가 호드에 영광을 가져다 주면서! 나는 천 개의 두개골을 가지고 돌아올 것이다!"
rows["129:1545003528"]="애래시인이 잘 돌봐주어야 할 애완동물을 믿을 수 있습니다. 그는 사냥꾼들이 모여있는 Cenarion Enclave에 거주합니다."
rows["129:1555784216"]="모가들은 사용 가능한 자원의 일부만 사용했고 그들 중 몇 명만이 Thunder King의 속임수를 가지고 있었다."
rows["129:1561397759"]="내 친구 중 한 명도 아니잖아, 왕은 항복을 협상하러 보냈어"
rows["129:1570362086"]="이제 창조자들의 지성들을 위한 의도들을 이해하게 됐어요."
rows["129:1573984417"]="당신 혼자 풍자마스터를 찾는 게 너무 힘들어?"
rows["129:158112483"]="두 가지 부패의 경로는 모두 매우 직선으로 보입니다."
rows["129:1598116698"]="존스는 우리 마지막 카드 경기에서 빚을 지고 있어요."
rows["129:160799895"]="아키아니즘을 숙달하기 위해서는 세미드만 더 이상 찾아야 합니다."
rows["129:1620173339"]="|TInterface\\Icons\\spell_yorsahj_bloodboil_yellow.blp:20|t수행! 당신은 |cFFF00000|Hspell:122064|h[부식성 용암]|h|r에 덮여있다!"
rows["129:1626320990"]="그 녀석은 산 반대편의 늑대 우리에 잡혀 있다. 아루갈에게 바쳐지기로 되어 있어. 이제 우릴 풀어줄 건가?"
rows["129:1629434088"]="레드 크레인의 길은 실패의 길입니다.$b$b모든 길은 절망으로 이어집니다. 당신은 희망이 없습니다!"
rows["129:1640054473"]="선웰 전투는 새로운 길의 첫 단계입니다."
rows["129:1669725838"]="습지인 메네틸 항구 북쪽의 블루글 Marsh은 해안에서 물가로 흘러내린 많은 박스를 보관하고 있습니다."
rows["129:1675636118"]="|TInterface\\Icons\\spell_fire_fire.blp:32|t$b$b브레이저나무에서 불타는 트위거를 가져다가 라이트파이어로  ⁇ 루부 티키스를 태워버리자!"
rows["129:1693416031"]="다른 걸 보여줄 수 없어, 제비그를 찾아라"
rows["129:1699921526"]="이 거칠고 똑똑한 협상자가 내 가격을 곧 파산시킬 거야"
rows["129:1704646047"]="리치 왕의 죽음으로 남은 것은 제 의무뿐입니다. 가족도 없고 친구도 없습니다.$b$b전쟁"
rows["129:1726510256"]="호드은 집중 아이리스를 되찾을 수 없습니다. 그들의 힘의 잔해를 제거하고, 나는 유물을 확보할 것입니다."
rows["129:172686924"]="그렇다면 우리 는 역사 에 대한 지식 을 시험 해 보겠습니다. 어떤 강력한 검 이 죽은 자 들 을 그 힘 으로  ⁇ 어 먼지 만이 남아 있을 수 있습니까?"
rows["129:1756064365"]="나를 더 기다리게 한다면 에테리움과 푸른용군단의 협정을 다시 고려할 수밖에 없다!"
rows["129:1788908714"]="모가 틴 경호를 섬겼어요. 그의 이름은 \"라\"였습니다. 모가 언어로, \"라-덴\"은 \"마스터 라\"라는 뜻입니다."
rows["129:1808349004"]="그만! 더 멀리 가지 마시오, 필멸의 존재여. 무한의 용군단에 맞서기에는 아직 준비가 부족하오. 이리 오시오. 내가 돕겠소이다."
rows["129:1827471087"]="파괴자는 전력을 모아 세계를 갈라놓을 때 공격하자!"
rows["129:1856420200"]="계피를 조금 넣었나요, 아니면 육두구를 넣었나요? 뭐든 간에 한 가지 확실한 것은 쿠키 씨, 당신만큼 당나귀를 제대로 요리하는 자는 아무도 없다는 겁니다."
rows["129:1862886506"]="괴물들의 문제는 그들이 너무 빨리 쓸모를 넘어서게 된다는 겁니다."
rows["129:1877163564"]="빛이 우리를 인도한다. 이번 일은 너희가 오기 전부터 추진되었다. 우... 우린 우리가 들은 대로 한다. 반드시 해야 하는 일이다."
rows["129:1879236494"]="슬바나스, 결국 우리 모두가 창조주 앞에 서서 심판을 받아야 합니다."
rows["129:1881239051"]="우리를 소환할 수 있다고 생각했나? 소환하는 것은 바로 우리지 네가 아니다! 이 무례함에 대한 보답으로 죽을 때까지 때려주지. 그런 다음 뼈를 추려주마!"
rows["129:1885467201"]="네, 내 스카우들은 이 모든 걸 알아냈어 \"사일라 왕\""
rows["129:1889615645"]=" ⁇ 더는 너무 간단해서 작동했지, 하지만 이제 새로운 운영체제가 생겼어."
rows["129:1909795071"]="아르타스, 내 말 들어! 아르헨티나 십자군 전쟁은 네 왕국의 힘으로 무너질 것이다. 빛!"
rows["129:1917913667"]="챔피언, 전 시간 전격 프로가 되길 생각해 본 적이 있나요?"
rows["129:1920076547"]="<피 엘프는 테이블에 허무고 있고, 숨을 쉬는 동안, 그는 강력한 진정성 독소의 희생자인 것 같다.>"
rows["129:1920594529"]="|TInterface\\Icons\\inv_misc_dust.blp:20|t두루무는 캐스팅을 위해 눈을 뜨기 시작합니다 |cFFFF0000|Hspell:134169|h[분해]|h|r!"
rows["129:1923916795"]="이 곳은 특별해, 우리 할아버지는 숲의 이 부분을 고향이라고 불렀어요"
rows["129:1939827218"]="고대의 해적 도자 를 조심스럽게 굴러 내다. 도자 는 추락 으로 인해 6, |cFFFF2222|Hspell:142058|h[Cannon Barrage]|h|r"
rows["129:1947325908"]="그리고 얼마 후 어떤 짐승을 보게 되었다. 깃털은 분명 올빼미의 것이지만, 곰의 힘과 의지가 있었노라."
rows["129:1955107680"]="그럼요! 마그니 형님도 형님을 보면 매우 기뻐하실 겁니다! 지금까지 오랫동안 나쁜 소식 말고는 아무것도 듣지 못하셨으니 말이죠. 하지만 형님께서 나타나셨으니 모든 게 바뀔 겁니다!"
rows["129:1966199330"]="저는 라이트의 희망 사당에 난민들을 돌보는 금금을 청했습니다."
rows["129:1974165598"]="적군 가운데 앉아있어서 이 닭이 우리를 보호해주는 것 이상은 아니지"
rows["129:1984271009"]="어떤 사업 을 시작 하기 전 에 손 을 깨끗 하게 하라. 피부 를 피 이나 흙 으로 염색 하는 것 은 자연적 인 아름다움 을 빼앗아 버릴 것 이다."
rows["129:1987523901"]="배가 영광스럽게 폭발하고, 지와 아이사는 더 멀리 떨어진 곳으로 날아갔지만,"
rows["129:1990290621"]="우린 이 배를 적시에 준비하지 못해 겨울이 오고 그 와 함께 우리의 멸망이 올 거야"
rows["129:199775207"]="카야미트에서 수분을 비추는 것인데 맛있는 탄산 음료가 만들어서 사람들에게 아이디어를 줄 겁니다"
rows["129:2028235195"]="누가 왔어요? 내버려둬! 이 불쌍한 해적들이 날 뱉어내면서 녹색 달걀과  ⁇ 을 만들기 전에 내놔둬!"
rows["129:2038659630"]="에테레얼 들 가운데, 일부 의원 들 은 구체 로 육신 과 육신 의 존재 들 을 다루고 있다. 그러한 개인 들 은 육신 을 다루는 사람 이라고 알려져 있다."
rows["129:2091366482"]="내가 내 주인에게 은혜를 베풀어 침입자들을 쫓아낼 것이다. 나의 가장 조용한 바람은 여전히 그들에게 너무 많을 것이다."
rows["129:223423946"]="참아, 수나, 혼자 타운롱으로 진출하면 문제가 더 심해지겠지"
rows["129:227078258"]="그들은 하나님의 뜻대로 산을  ⁇ 는 파동이라 그러나 그들은 아무것도 하지 못하더라"
rows["129:233357394"]=" ⁇ 프라인 로지, 약속했듯이 한 조각으로!"
rows["129:26952920"]="우리는 마스터의 예언을 실현하기 위해 왔고 의식은 이미 시작됐고"
rows["129:276825049"]="하지만 여전히 그들을 감지할 수 있습니다. 내 겁쟁이 형제 자매들이 어둠 속에 남아 있다면 말할 수 없는 고통을 초래할 것입니다."
rows["129:277379185"]="이쪽은 좀 조심해$b$b이제 드라크 진 유적으로 내려가서 기둥 근처에 마시자!"
rows["129:284835425"]="대리인이 당신과 대화할 때, 그는 당신의 이름을 통해 모든 문장을 시작할 것입니다. 당신이 당신의 이름을 보지 않으면, 그는 아직 당신에게 말을 하지 않습니다."
rows["129:373821966"]="그 비행기를 타도 좋지만, 좌석에 톱날이 있다고 투덜거리지는 마세요. 구할 수 있는 부품이 그게 다였으니까요."
rows["129:390718799"]="그는 너무 강하군요. 당장 여길 떠나야 해요! 내 마법으로는 그를 잠깐만 저지할 수 있어요. 영웅들이여, 서두르세요!"
rows["129:403300276"]="당신 같은 거북이를 다룰 수 있는 연습을 해왔고, 이 끔찍한 얼음 속에서 아는 유일한 사람이 나예요."
rows["129:406096683"]="그럼, 난 긴 비행기를 싫어 그래서 내가 내장 화재를 발사하고"
rows["129:415157448"]="내 하원들, 로켓 상장과 그의 아래 로켓을 파괴해라 52무릎, 닥터 부미 앞에 무릎!"
rows["129:42465698"]="어차피, 카라반 안에 있는 모든 물품을 빌릴 수 있어... 당신이 다하면 가져오면!"
rows["129:457793141"]="우리가 계속 서로 싸우는 데 힘을 소비하면, 로켄이 울두아르의 자원을 이용해 호드와 얼라이언스 둘 다를 무너뜨릴 겁니다."
rows["129:47685084"]="거의 집에 왔어, 우리 시간은 너무 짧아. 당신은 다시 변할 것입니다, 고엘 - 하지만 나는 당신을 찾을 것입니다!"
rows["129:48791636"]="\"어방한 지평선에서 운명을 쫓아다니는 것에 감사해요. 꿈꾸는 것에 감사해요\"."
rows["129:487959536"]="제왕후 셰크지어가 우리 제국이 혼란에 빠졌다고 보아도, 우리는 이 문제를 해결해야 합니다."
rows["129:522845247"]="여러분이 이 기기의 도착을 기다리는 동안, 제 보조와 저는 이 놀라운 항공기의 몇 가지 특징들을 잠시 보여드리겠습니다."
rows["129:541693768"]="나무에 있는 마을에서 그를 잡았어. 베일... 베일 샤라스! 로카그가 즉시 이 사실을 알아야 한다. 가서 그에게 말하라."
rows["129:557873033"]="내 구조 계획은 훌륭하고, 절대적이지. 괴물이만 성공하는 걸 막을 수 있어. 날개 있는 괴물이요. 무서운 생각이었죠."
rows["129:563366715"]="척추고래는 네 지도에 있습니다.  ⁇ 라이 정상에서 빈안 마을의 해안에서."
rows["129:60335805"]="미안해. 하지만 크로미가 말하길, 미래에 대한 그 어떤 정보도 너에게 알려줘서는 안 된대. 만약 그랬다가는 내 존재 자체가 사라져버리는 모양이야."
rows["129:618548775"]="스톰윈드에 오신 것을 환영합니다. 재건하는 데 오랜 시간이 걸렸지만, 그것은 매우 가치가 있습니다. 그래서 당신은 방문하고 있습니까?"
rows["129:633820465"]="사냥꾼이 찾고 있다면, 당신은 다자라르를 방문해야 합니다. 그는 보통 도라나르의 숙소 바로 밖에서 발견 될 수 있습니다."
rows["129:650779728"]="만약 당신이 그 중 하나를 고칠 수 있다면, 10분 동안 쉬게 해 줄게요."
rows["129:654431161"]="시간이 있다면, 빈의 유명한 브루문 페스티벌을 방문해 보시면 됩니다. 저는 제 유명한  ⁇ -라이 키커 브루를 만들겠습니다."
rows["129:656631808"]="자비로운 지구모아, 파괴의 범위를 보세요! 우리는 행운이 있습니다. 전체 불모의 땅는 바다에 붕괴되지 않습니다."
rows["129:669808454"]="와우, 이 항구들은 엄청나게 크네요! 여기 항구하는 배들은 제펠린만큼 큰 것 같아요. 이건 제가 오그리마에서 볼 수 있는 바다인가요?"
rows["129:674149123"]="운명의 불꽃에서 야롱들은 태어났습니다. 그들은 벽을 넘어 살아남습니다. 왜냐하면 그들은 자기 자신의 법칙을 제외하고는 어떤 법을도 따르지 않기 때문입니다."
rows["129:67550542"]="브래보 회사 필드 키트 액티브, 새로운 능력은 이제 액션 바에 있습니다.$BBravo 회사 필드 키트를 비활성화하도록 설정하세요."
rows["129:681292969"]="알렉스스트라사 역시 스태겔름을 거절했고, 그녀의 축복 없이는 테일드라스실의 성장은 결함이 있었고 예측할 수 없었다."
rows["129:682997844"]="거가 한 번 싸우고 크로콜리스크에게 먹여$b$b모두 고가의 반대를 하시오$b$b고가는 이 때문에 슬퍼하고 있어요."
rows["129:704493893"]="그가 찾은 행성에는 티탄의 청사진을 벗어난 종족들이 살고 있었다. 그곳은 티탄의 계획과 다르게 돌아가고 있었다."
rows["129:705908894"]="내 누드러 텐트에서 환영합니다. 우리는 모든 종류의 누드러를 먹어야 합니다. 우리가 그것을 가지고 있지 않으면, 당신은 그것을 먹지 말아야 합니다."
rows["129:730512279"]="진짜 의사가 아니지만, 다음 상대에게 얼굴 재조리 수술을 해볼 거야"
rows["129:776608543"]="사막의 북쪽 사르테리스 스트랜드나 배드랜드의 안고르 요새의 물에는 잠겨 있는 상자가 있어 열 수 있다."
rows["129:788462878"]=" ⁇ 푸스 굴에 들어가서 불꽃놀이를 시작해 여러 적과 동시에 싸울 준비를 해줘"
rows["129:79911590"]="베마린은 페어스트라이더스 광장에서 금수업을 가르치고 있지만, 다소 더러운 직업이지만,"
rows["129:802614139"]="로데론에서 칼림도어까지, 그들은 그의 이름을 알게 될 것이며, 그들은 영광의 노래를 부르며, 호드의 타락한 챔피언을 찬양할 것이다."
rows["129:819103094"]="고르트는 가끔 혼란스러워하고 사람을 죽이는 데 잘해서 고르트는 장교로 임명되지만 이제 고르트는 아무것도 죽이지 않는다"
rows["129:846948489"]="왜 야이가 제대로 된 위를 가지고 다른 버키들처럼 저녁을 먹지 않았을까?"
rows["129:861145489"]="분명 로켓을 발사할 때까지는 긴 시간이 걸릴 겁니다. 가족들이 있는 집으로 우선 돌아가는 게 좋지 않겠습니까?"
rows["129:868131954"]="이것은 카라잔의 탑이며, 제 주인 메디브의 거주지입니다. 겸손한 문장으로서, 더 이상 설명할 수 있는 것은 거의 없습니다."
rows["129:888667899"]="좋은 친구, 팁 좀 해줘서 큰 채소를 원하시나요?$B$B물, 비료와 사랑을 줘"
rows["129:912860511"]="다른 영역에서 열렬한  ⁇ 을 위해 달걀을 요구했습니다.$B$B그리고 한 달걀은 특별한 달걀이 다른 달걀보다 더 많이 찾았습니다."
rows["129:915264759"]="내가 숙주로 임하려고 했지만, 넌 죽지 않을거야!"
rows["129:921489828"]="이 문을 통과하면 지금 당장 실패할 겁니다. 여러분 모두는 오만이라는 악성 전염병으로 부패한 것입니다."
rows["129:97270368"]="이 존재가 공포를 먹일 수도 있지만, 우리는 그것을 제공할 수 없습니다."
rows["129:973371977"]="조람가르 포스트를 파괴하라 블랙파토름 캠프를 파괴하라 우리는 마에스트라 포스트로 진군할 것이고 밤이 되면 아스트란아르는 헐렁거릴 것이다"
