rows["130:1055169430"]="이 뼈들은 많은 새로운 정보를 공개하고 연구의 진행에 도움이 될 것입니다."
rows["130:1060954452"]="이 곳을 깨끗하게 해냈을 때, 다시 건립할 수 있고, 브래보 회사에 줄 수도 있습니다."
rows["130:1082921535"]="우리는 죽으면 더 낫습니다. 하지만 죽음도 이 전쟁의 잔혹한 행위에서 해를 주지 않는 것을 볼 때..."
rows["130:1104122228"]="저쪽은 훌륭했어요, 최고급이야 이제 다른 문제도 있어"
rows["130:1109950619"]="내가 당신을 시작하게 할 수 있습니다 노스렌드준비되면 알려줘서 출발점으로 이동할게요"
rows["130:1116011210"]="이 짐승은 시골에서 양을 학살하는 걸 잡았어요. 그는 회개하지 않고 쉽게 흥분합니다."
rows["130:1129587984"]="젠장, 탕자르 자유로울 거야!$b$b행운이군, 다리도 못  ⁇ $b$b매혹된군, 그게 내가 하는 거야"
rows["130:1147569782"]="자매 여러분, 훈련은 잘 진행됐습니다. 제 가르침이 필요없어 곧 당신들이 자기 백성을 이끌게 될 것입니다."
rows["130:1170910855"]="난 네가 같은 영웅이 늙은 남자를 산으로 싣고 가는 일을 거부할 거라고 생각했지"
rows["130:1173524896"]="우리 사제 훈련자들은 나루의 성당 입구에서 빛의 질서의 방 안에 있습니다."
rows["130:1182142500"]="재판이 시작되면, 당신 밑에서 오는 그림자는 주기적으로 해방될 것이고,"
rows["130:1222885503"]="광부 훈련 및 물품은 달라란 북서부 마구스 무역 거래소에서 모든 광부 발굴 회사에서 발견됩니다."
rows["130:1226872268"]="우리 마음은 마침내 자유를 얻었네. 그랬지... 그렇게 자유로운 마음으로, 우리가 불타는 군단에 영혼을 빼앗겼을 때 저질렀던 끔찍한 일들을 다시 떠올렸네."
rows["130:1227594109"]="아크니즘의 추종자인가요? 아주 잘..."
rows["130:1239121981"]="아, 아, 아, 이봐, 이봐, 내 동생과 함께 타운롱 스텝에서 일했었지"
rows["130:1253780945"]="잠시만 기다려주세요. 화면에 표시된 순서대로 도와드리고 있으며, 차례가 되면 이름을 불러드리겠습니다."
rows["130:1261012737"]="이 지역 사람들은 잠금잡을 것을 싫어합니다. 전문적인 예의를 표해서 제가 배운 몇 가지 트릭을 보여드리겠습니다."
rows["130:1289745779"]="호텔관 파라는 몸과 정신을 쉬게 해 줄 겁니다."
rows["130:1293388991"]="그리고 고맙습니다... 저주받은 자들의 속박에서 날 풀어주신 걸 진심으로 감사드려요. 그대는 영웅이에요... 그대가 위대한 일을 해내리라는 걸 알 수 있답니다."
rows["130:1329751934"]="내가 이 끔찍한 고통을 내린 게 아니라, \"상\"이었어."
rows["130:133111565"]="여보, 기사 여러분, 우리는 완전히 장갑과 무장되어 있지요. 그럼 그들이 모험이라고 부르는 것에 깊이 들어가자!"
rows["130:1360295375"]="몇 명의 사우르 사제들이 호드와 얼라이언스의 피를 요구하고 있습니다.$b$b당연히 잠들면서 죽였어"
rows["130:13657884"]="예, 기억할 수 있는 만큼 여기 갇혀있어요$B$B전 전 전무사였는데, 뭔가 고칠 수 있겠지?"
rows["130:1370913141"]="내 정신이 다시 돌아왔고, Vol'jin에게 내가 배운 것을 말할 수 있게 해줬어\010"
rows["130:1395025534"]=" ⁇ 라이에 갔어? 아주 좋네요. 길고 흐르는 농경지, 아름다운 산들이 있고, 전혀 위험한 것은 없습니다."
rows["130:1397390074"]="코도가 매일 풀에서 자신의 무게를 먹을 수 있다는 걸 몰랐잖아"
rows["130:1420511642"]="아르헨트 오브란스는 동부 플라그랜드의 라이트의 희망 사당에서 스컬지의 반대를 조정합니다."
rows["130:1426756062"]="이런 함선에서 기숙사가 되는 게 너무 많지"
rows["130:143300300"]="당신은 지원할 것으로 예상됩니다 얼라이언스 필요한 구성원, 인간이나  ⁇ 놈, 드레네이 또는 여러분 같은 판다렌이든 간에"
rows["130:1442528979"]="다르나서스에서 워리어 테라스에서 거주하는 밤 elf 무기 마스터 인 Ilyenia Moonfire는 활을 사용하는 법을 훈련시킬 수 있습니다."
rows["130:148950187"]="장갈마르쉬에 사는 페랄펜은 똑똑한 잠금으로 된 빗바구니를 가지고 있습니다."
rows["130:1495175859"]="그 마을에 너무 오래 머물렀어요. 멋진 곳이죠. 그리고 그곳에서 봉사하는 것을 즐겼지만, 저는 여기서 머무르는 것을 더 좋아할 것 같습니다."
rows["130:1507407451"]="|TInterface\\Icons\\ability_whirlwind.blp:10|t OMG 내가 캐스팅하고 있는거야 |cFFFF0000|Hspell:88481|h[Overdrive]|h|r!"
rows["130:1545774834"]="저게 가난한 자연주의자 비트의 깨진 형태입니다. 지식에 대한 그의 열정은 그의 죽음 방식에 의해 잔인하게 일치했습니다."
rows["130:1561282212"]="형식적인 일을 하기 위해서, 내 허공은 나머지 사람들과 함께 죽었어요."
rows["130:1599411762"]="치 치는 자신의 농장을 가지고 있는 것 뿐이야!$B$B<Chee Chee는 자부심을 가지고 가슴을 찌르다.>$B$B내 친구, 언젠가 제 농장에 오세요."
rows["130:1606498488"]="저 짐승들이 우리 배를 태워버리지 않았더라면, 이제 집에 있었을 거야."
rows["130:1627908942"]="다른 사람들은 다르나서스의 지도자인 우리 민족의 빛나는 빛인 타이란데 위스퍼윈드와 그의 갈등이 격화되고 있다는 소문을 인용한다."
rows["130:1630827569"]="이건... 이건... 정말 아름답구려. 수정을 만졌을 때의 느낌이란... 성스러운 빛이 내 몸을 흐르고 나와 소통하였소이다... 나의 영혼이 치유된 것이오."
rows["130:1632347329"]="드라짓에게 행운이 따라 랩터를 잡아줄 분이 불쑥 나타날 것 같진 않네요. 벌써 보상금을 두 번이나 올렸던 터라 하는 말이에요..."
