rows["130:1640822211"]="우리가 해변 요새를 확보해야 합니다. 만약 호드이 여기 서지도록 한다면, 모든 판다리아는 테라모레처럼 보일 것입니다."
rows["130:1644133757"]="듀어너, 훌륭한 일 네스피라의 상자에 오래 머물지 마. 당신은 분노한 반신에 의해 초래되는 위험을 알고 나처럼 잘합니다."
rows["130:165728563"]="우리랑 같이 있는 동안, 왕아, 네가 떠나면 다른 괴물이 널 대신할 거야."
rows["130:1658643483"]="내가 네 부족을 끝낼 때, 내 분노에서 널 구한 오크시스  ⁇ 을 사냥할 거야"
rows["130:170126671"]="물량이 많을 때, 테라바인 장군은 남쪽의 발리스트 포지션에서 전투장에 배치되어 있습니다."
rows["130:1709809474"]="자넨 돈을 벌어야 해, 하지만 이 주 내면의 정보를 얻으면 수익을 올리고"
rows["130:1725832692"]="이 발리스트들은 우리가 필요로 하는 장점이야! 다른 한쪽을 불러올 수 있다면 우리는 정말 사업에 들어갈거야."
rows["130:1751192058"]="이런 조건에서 어떻게 일할 수 있을까요? 그리고 여기 있는 이 모든 혐오스러운 포세이큰!"
rows["130:1755260667"]="오 내 친구, 그 끔찍한 소리. 수백 세대의 번개가 반다레네의 마음을 공포로 가득 차게 했다."
rows["130:1762868752"]="북쪽으로 흐르는 모든 물품 잿빛 골짜기 여기서 쉬고 다시 연료를 공급해주는 게 중요합니다."
rows["130:1765271604"]="저희와 제임스를 도와주셔서 감사드립니다. 제임스를 만나시면, 저와 꼬마 지미가 사랑한다고 그리고 기다린다고 전해주세요."
rows["130:1765483410"]="|TInterface\\Icons\\ability_titankeeper_uncheckedcorruption.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:147011|h[Manifest Rage]|h|r!"
rows["130:1869503599"]="어둠이 다가오면 붉은십자군에 종지부를 찍으리라. 너희는 다시 한번 싸울 것이다! 스컬지를 위하여! 리치 왕을 위하여!"
rows["130:1878651046"]="여러분들이 이번 기념일을 축하하는 것을 보고 정말 기쁘네요."
rows["130:1878710771"]="만약 당신이 요금 징수와 소환에 대해 여기 있다면, 다른 사람을 생각하게 해줘야 해요."
rows["130:1884966983"]="트롤은 모든 힘을 이용해 아제로스의 부위를 안정시키고 있습니다."
rows["130:1943323489"]="나 좀 약해졌지만 아만니와 잔다라리가 이 방에 숨겨진 보물에 대해 얘기하는 걸 기억해요"
rows["130:1969401425"]="<아크마지 바르고트가 미소를 짓고 당신을 선호합니다.>$B$B저 망할 바이올릿 타워에 충분한 공간이 있습니다.$B$B해마다 날 찾아볼 수 있어"
rows["130:1971923703"]="로크레이인의 군인들이 여기 있네  ⁇ 트래그, 우트보치, 크롬가르 요새에 있어"
rows["130:2041540546"]="저는 수호루가 이곳을 신전을 지키기 위해 남겨졌다고 믿게 되었지만, 신전처럼 그는 적절한 결정이 없으면 무력합니다."
rows["130:2126412114"]="난 와일드햄어 클랜의 딸이고 지구 반지의 샤만이야"
rows["130:2140736643"]="왜 누가 이렇게 끔찍한 일을 파고 내려고 했을까요?"
rows["130:2143920293"]="그렇다면 역사 에 대한 지식 을 시험 해 보겠습니다. \"피가 흘린 왕관 이 사라지고 잊혀지지 않도록 하라\"는 기록 을 포함 한 무덤 은 누구 의 것 입니까?"
rows["130:247280687"]="아냐 마우레이와 상류 아웃도어트의 맨 위에 있는 숙소에서 얘기해봐요"
rows["130:253172778"]="망할 오우거들. 전부 지옥에나 떨어져라. 이 야만족으로부터 우리를 구해줄 자는 없소!? 이번이 벌써 50번째 납치 사건이오."
