rows["130:275876953"]="|TInterface\\Icons\\inv_misc_idol_02.blp:20|t가라'잘은 무작위로 플레이어를 선택하여 |cFFFF0000|Hspell:122151|h[보두  ⁇ 스]|h|r!"
rows["130:292239715"]="내가 도와줄 수 없어, 당신들의 일은 내 일을 넘어선 것 같아. 아서 무어와 이야기해, 상자에 있는 저쪽. 그는 당신을 더 훈련시킬 수 있을 것이다."
rows["130:29249482"]="아름다운 꽃이 많이 자란다. 하지만 제가 좋아하는 것은 마쉬 리리입니다. 불행히도, 그 아름다운 꽃은 거의 찾아볼 수 없습니다."
rows["130:307352113"]="세계 기둥 조각이 어디에 있는지 말해줘요"
rows["130:31488161"]="다른 왜성 지도자들은 그들의 행동에 부끄러워했고, 다시는 두려움이나 불신이 그들의 판단을 흐려버리지 않겠다고 맹세했습니다."
rows["130:326082705"]="알겠습니다, 대장님! 누군가가 저에게 세나리온 수풀의 드루이드들이 몰살당했다고 전하려고 했던 것 같습니다!"
rows["130:329177582"]="여기 궤짝에서 종을 꺼내는 것을 잊지 마세요. 그리고 $n 님, 만약 제가 길을 벗어나 엉뚱한 쪽으로 가면 종을 울리는 것을 잊지 마세요. 그럼 제가 당신을 다시 찾아가게 될 테니까요."
rows["130:34398826"]="하지만 저는 한 가지의 유일한 존재입니다. 아버지의 부패로부터 자유로웠던 검은 용입니다. 그리고 그렇게 남아있으려는 마음도 있습니다."
rows["130:346164831"]="호랑이 구라미는  ⁇ 도파나 수도원 인근에 발견될 것입니다. $b$b<벤은 네 지도에 지점을 표시한다.>$b$b"
rows["130:347320510"]="하지만 이런 것들은 나무에서 자라지 않습니다.$B$B<신령 호출자는 잠시 그 생각을 해봐요>$B$B잠깐만요"
rows["130:375006885"]="예, 어제 파티에서 트와라이트의 해머에 대해 말하는 사람을 들었는데"
rows["130:387956500"]="이 칼에 내가 가장 강한 악마를 물리칠 힘을 심어주겠소"
rows["130:408760780"]="게다가 다른 문제들을 처리하는 데 바빴어요. 그 두 적들이 전선으로 들어가서 수십 명의 용이 죽었습니다."
rows["130:425270260"]="이 모든 것에 대해 어떻게 생각해야 할지 모르겠지만, 정말 공감을 느끼고 지갑을 돌려주셔서 감사합니다."
rows["130:432101707"]="불! 파괴! 죽음! 군주의 분노를 두려워하라! 안 돼! 난 싸워야해! 알렉스트라자여, 도와주소서! 난 싸워야해!"
rows["130:435561745"]="임무가 끝나면 반 베어하트에게 보고해줘요"
rows["130:447238636"]="우리 군대가 모인 즉시 Twilight Precipice에 진출해"
rows["130:477589882"]="내 백성의 피를 더 이상 헛되이 흘리지 않게 하겠다"
rows["130:486249593"]="무기를 내려놓고 장갑을 챙겨라, 좋은 고전적인 복싱 경기가 됐어"
rows["130:487092537"]="이 전 세계 영웅들을 환영할 것입니다. 얼라이언스 그리고 그들을 존중해 주며 스톰윈드!\010"
rows["130:489087780"]="싸우고 죽고 먹어 또 하루 살라$b$b네가 죽으면 네 형제들이 널 먹을 수 있는 곳에 죽어라"
rows["130:48971573"]="발사선이 불어, 이제 공격할 때입니다. 이 전투 깃발 중 하나를 가져와 얼라이언스의 묘지에 심어주세요!"
rows["130:499537519"]="스니프... 그 영 군인이야... 난 이 군대에서 너 같은 군인들이 더 많으면 좋겠어."
rows["130:507935577"]="저렇게 낮은 거리의 쥐의 원인을 옹호하겠소?"
rows["130:513265672"]="브라보 회사 필드 키트 액티브, 시포륨 플랜트는 이제 액션 바에 사용할 수 있습니다.$BBravo 회사 필드 키트를 비활성화하도록 설정하세요."
rows["130:51347337"]="마침내 정의의 시간이 다가오고 있습니다. 이 괴물은 모든 얼라이언스 이 전쟁에서 잃어버린 생명."
rows["130:560647451"]="영혼의 힘은 너무 크다. 나는 그것을 안전하게 사용할 수 없습니다. 그 안에 분노하는 세력들은 우리 모두를 멸망시킬 수 있습니다."
rows["130:569947109"]="그는 너무 강하군요. 당장 여길 떠나야 해요! 내 마법으로는 그를 잠깐만 저지할 수 있어요. 영웅들이여, 서두르세요!"
rows["130:618224236"]="만약 당신이 어떤 종류의 도움을 필요로 한다면,  ⁇ 씨 씨앗의 한 무리와 화살표의 총까지, 주'스 워치가 그것을 제공할 수 있다는 것을 알고 있습니다."
rows["130:632348379"]="좋은 sempstress는 늦은 Saltheril의 Haven에 점유되어있다; 바늘과 끈을 그녀의 실력 확실히 거기에 평가된다."
rows["130:65120039"]="난 다시는 단축선을 택하지 않을 거야! 내가 어떻게 알았지?"
rows["130:662927802"]="그대가 그들 가운데 우호를 얻으려 한다면 그들이 그대에게 그들의 비밀을 가르쳐 줄 것이라 그러나 나는 너희를 경고하노라"
rows["130:664084732"]="걱정 마, 운전은 겉으로 보기엔 어렵지 않아요$B$B이 시도를 하기 전에 더 많은 찌꺼기를 바르고"
rows["130:693212902"]="이건 키버가 원하던 게 아닌데... 뱀뿌리를 너무 많이 넣었나 보군. 두 번째 물약은 키버가 원하는 효과가 있을지 한번 봐야겠어."
rows["130:701343941"]="내 남편은 물가에 무슨 일이 일어나고 있는지 보고 싶어서$B$B<요온 수 장로가 통제할 수 없는 울음을 터뜨리기 시작했어요.>"
rows["130:715065153"]="재건할 수 있는 물품이 많고 조금만 더 있으면  ⁇  발더를 복구하고 다시 전투에 들어갈 수 있을 거야"
rows["130:719917108"]="이 같은 격변 이 있는 때에도, 음식 은 항상 필요 하고 소중 히 여긴다. 그래서 내가 요리 하는 시간 들 을 충분히 가치 있게 해 준다."
rows["130:72735574"]="셀로누스는 악마의 소환에 대한 전문가입니다."
rows["130:736275005"]="한샤시 와 사요크 는 한 손 이나 두 손 을 사용하는 데 훈련 할 수 있다. 오그리마"
rows["130:7399867"]="한 곳에서 이렇게 많은 종류의 버섯을 본 적이 없어요. 충분한 시간이 주어지면, 저는 모두에 대한 용기를 찾을 수 있을 것이라고 확신합니다."
rows["130:764251314"]="우리 중 작은 그룹인 드루이드와 경호가 우리 공통의 적인 그림토메 클랜의 자유풍 포스트의 타우렌에게 도움을 줄 수 있게 왔습니다."
rows["130:770412833"]="세상이 작아지면 구름 속에서 죽음의 날개를 찾아가기 시작했어요$b$b|TInterface\\Icons\\spell_frost_arcticwinds.blp:32|t"
rows["130:772785818"]="여기 드루이드들은 없는데 스톰윈드 밤 엘프들이 자기들만의 걸 만들어냈다는 겁니다."
rows["130:773825820"]="치료법도 실패했으니 불행히도 이 짐승의 혈액에 세륨이 투입되면 곧 그 생명이 끝날 것입니다."
rows["130:776581158"]="제가 죽는다면, 제 의지에 따라 죽겠어요! 언데드 무리와 싸우다가 말입니다! 죽는다면, 아버지와 함께 죽겠어요!"
rows["130:781807455"]="그럼요! 마그니 형님도 형님을 보면 매우 기뻐하실 겁니다! 지금까지 오랫동안 나쁜 소식 말고는 아무것도 듣지 못하셨으니 말이죠. 하지만 형님께서 나타나셨으니 모든 게 바뀔 겁니다!"
rows["130:785257366"]="생각해보세요. 작은 목소리만 해도 세상을 바꿀 수 있습니다."
rows["130:801420098"]="엿먹지 마, 친구$B$B크로운의 휴일 상품을 사려고 한다면, 도시의 사랑스러운 상점에서 해야 합니다."
rows["130:801940781"]=" ⁇ 드햄어 씨의 하빈 프로스텀어는 썬더브루 디스틸러리에서 당신을 도와 샤만의 길을 가르쳐 줄 수 있습니다."
rows["130:829935321"]="계획말이오? 물론 언데드의 침략에 준비를 하여야 하오이다. 사랑하는 가족과 친구들을 위해 언데드의 공격 가능성에 대비해야 하는 것이오."
rows["130:837383476"]="난 너처럼 사람을 본 적이 없어 $p난 이기적이긴 하지만, 당신에게 부탁할 게 있어요"
rows["130:85147461"]="식물학자 타이니어렐보다 파티에 꽃을 준비하는 사람이 더 좋은 사람이 누구지?"
rows["130:858863993"]="페렐리 씨, 당신은 물건을 들여오려고 여행을 많이 하시는 걸로 압니다. 스컬지에 대한 소문이나 정보를 들어본 적이 있으십니까?"
rows["130:860641945"]="좀비들이 될 때 잔질이 될 거야 젠다라 트롤들은 거루바시의 힘을 다해서 스트랭글스톤을 되찾아낼거야"
rows["130:871160888"]="우선, 내가 사업가이고, 나를 다시 살려줘서 난 널 괴롭히지 않을거야."
rows["130:876807314"]="제 가르침은 지금 너무 발전해졌어요. 더 많은 약물을 배우고 싶다면, 여기서 텔 아티르와 이야기해 보세요."
rows["130:878953850"]="너희는 그분의 선택받은 자들이라 불멸의 피로 정결된 육신으로 태어났노라"
rows["130:882041856"]="네, 네, 그의 눈빛이 날 향해 다가오고 있어."
rows["130:888200572"]="그래... 달라질 건 없지. 하지만 제대로 되돌려놓을 수는 있어... 그렇게 해야만 한다. 그를 뒤쫓아 그가 한 모든 일에 대한 해답을 들어야겠다."
rows["130:896187785"]="다라란으로 갈래? 레이디 제인 프라우드머가 당신을 기다리고 있다고 들었어요."
rows["130:945218113"]="아타스는 그의 죽은 개들이 우리를 동부 왕국으로 돌려보내길 바라고 생각했는데..."
rows["130:97118189"]="|TInterface\\Icons\\ability_dualwield.blp:20|t%s는 그의 |cFFFF0000검을|r 및 이득 |cFFFF0000|Hspell:74981|h[다발 블레이드]|h|r!"
rows["130:985237282"]="태블릿의 기하학적 글자는 이 메커니즘이 다시 작동하는 방법이 있다는 것을 나타냅니다.$b$b어떻게 해야 할지 알아내야 해"
rows["130:987804587"]="가로쉬는 곧 가장 뛰어난 군대를 보내게 될 것입니다. 그들은 여러분을 호드의 열린 팔에 인도할 것입니다."
rows["130:996779017"]="어떻게 우리 사람들을 좀비로 바꾸고 우리에게 던지는 용기가 있어?$B$B거기 올라가서 엉덩이를 밟기 전에 훈련이 필요해?"
rows["131:1004494142"]="|TInterface\\Icons\\ability_warrior_battleshout.blp:20|t라오페의 영이 투입 |cFFFF0000|Hspell:126471|h[공제 약자!]|h|r!"
rows["131:1026286789"]="페라라스도 참사가 됐다고 이해하지만 모자체 캠프는 안전해 보이네요"
rows["131:1050649803"]="타루온 대사가 저를 데려왔는데, 저는 새로운 동맹국들에게 이 세상의 요소들을 가르쳐 줄 수 있기를 바랬지만 아무도 듣지 않을 겁니다."
rows["131:105730649"]="내가 가진 것이 아니라, 당신에게 유용할 것이 없다.$B$B아마도 D'lom가 그의 컬렉션에 대해 당신에게 관심을 가질 것입니다."
rows["131:1068208934"]="은행이 여러분이 원하는 곳이라면, 여행은 여러분을 다르나서스의 중심으로 데려가게 되는데, 그곳에서 여러분의 보물을 보관할 수 있을 것입니다."
rows["131:1084332796"]="마을에 나름 스카이캐서라는 지혜로운 사람이 있습니다. 그는 샤만의 길을 따라 당신의 학습을 계속할 수 있습니다."
rows["131:1110481430"]="|TInterface\\Icons\\inv_shield_76.blp:20|t%s는 그의 |cFFFF0000Shield|r를 장착하고 |cFFFF0000|Hspell:74908|h[개인팔랑크]|h|r!"
rows["131:1134663833"]="선택받은 알가르는 여기서 북동쪽으로 가면 나오는 고통의 성물함에 있다. 나바리우스 왕자가 있는 곳은 동쪽에 있는 죽음의 들판 반대쪽이다."
rows["131:1153472076"]="피곤하면 일에서 빠질 수 있어, 경보님"
rows["131:1212125259"]="우리 모두가 공유하는 힘입니다. 우리 민족을 파괴하는 중독에서 해방될 필요가 있는 힘입니다."
rows["131:1212202124"]="|TInterface\\Icons\\ability_creature_poison_06.blp:20|t 대제사장 베노시스는 캐스팅을 시작한다 |cFFFF0000|Hspell:96637|h[Bloodvenom]|h|r!"
rows["131:1233119395"]="준비를 단단히 시키세요, 라엘로라즈. 말리고스의 힘은 지금까지 본 그 어떤 것과도 다릅니다. 작전이 성공한다 해도 그의 계획을 다소 지연하는 정도에 지나지 않을 거예요."
rows["131:1282322455"]="20년 동안의 연구와 희망과 꿈이 모두 멈춰버렸지만 이제 남은 것은 임무와 딸 리야야뿐입니다."
rows["131:1312336977"]="카이마스는 죄수들에게 끔찍한 짓을 하고, 그들을 반려동물들과 싸우도록 강요한다."
rows["131:1326690340"]="드래곤마우 스카이브레이커와 상승자들에 주의하라. 그들은 우리의 마법에 속이지 않는다! 항상 그 존재로부터 거리를 유지하십시오!\010"
rows["131:1351290819"]="7팀의 보고서를 가져와, 얼마나 많은 호드가 남아 있고, 얼마나 많은 사람들이 아직도 남아있는지"
rows["131:1369940835"]="그대들에게 감사한다. 볼드랏실의 뿌리는 고대 악마의 거처까지 뻗어가 버렸고, 그래서 현명한 드루이드들은 볼드랏실을 파괴하기로 한 것이다."
rows["131:1381080910"]="착각한 배신자, 그들의 관심을 가져와 빨리 날 멀리 데려가라"
rows["131:1390227976"]="잘 봐라. 부정의 헤이건이다. 아름다운 아제로스를 역병지대로 바꾸어 버린 역병 가마솥을 배후에서 조종한 인물이지."
rows["131:1397046234"]="피즐과 포지크의 스피드바지, 내 귀여운  ⁇ 아! 내가 이 물건을 만들었어!$B$B ⁇ 키의 스피드바지라고 불러야 돼!"
rows["131:1406639285"]="얼음혈 묘지는 전쟁터 남쪽에 있고 얼음혈 탑 동쪽에 있습니다.$B$B현재 어느 쪽도 통제하지 않습니다."
rows["131:1412505516"]="그만! 너희 같은 버러지는 이 신성한 장소에 들어올 자격조차 없다! 명예는 내팽개쳐 버렸군! 나아지는 모습도 없어!"
rows["131:1439798896"]="끔찍한데 내가 말했다고 말하지 마, 전방에 벌레가 퍼져나가고 있고 작물이 자라지 않고 있어"
rows["131:1459439402"]="우리의 장군인 반나르 스톰파이크는 전투에서 쓰러졌어요$B$B우리 쿼터마스터와 얘기해, 우리의 군대를 재건하는 데 도움이 돼"
rows["131:1461362898"]="우리는  ⁇ 다레나들과 대결하는 것에 낯선 사람이 아닙니다. 다가오는 전투는 여러분의 영혼을 시험할 것입니다. 천상의 자들이 여러분의 행동을 인도해 주시기를 바랍니다."
rows["131:1480319337"]="네, 내 동료가 개척자입니다. 제 적의 친구도 제 친구의 적이에요. 그리고 그래..."
rows["131:1500834545"]="뭐?$B$B다시 깨어났어$B$B<소니는 깊은 숨쉬기를 내린다.>$B$B이 비가 시작된 이후로, 아무것도 할 생각이 들지 않아요."
rows["131:1509130294"]="기계노움 수행원들 사이에 싸움이 있었던 것으로 보입니다. 수행원들이 한구석에 어지러이 쌓여 있습니다."
rows["131:1514546732"]="|TInterface\\Icons\\inv_sword_2h_mantid_01.blp:20|t풍의 주자 멜'jarak은 발기를 시작한다 |cFFF00000|Hspell:122407|h[Blade of Rain]|h|r!"
rows["131:1530661244"]="고대의 해적 도자 를 조심스럽게 굴러 내다. 도자는 추락하여 3, |cFFFF2222|Hspell:141962|h[Scurvy]|h|r로 고통받는다."
rows["131:1546709633"]="오슈건은 아직도 남아있지 않을까 궁금합니다. 어둠이 되기 전의 이야기들..."
rows["131:1551677459"]="미스터리는 약한 사람들을 망치게 합니다. 마녀의 길을 따르지 않더라도, 기억해야 합니다."
rows["131:1582601944"]="역병이 그다지... 치명적이지 않았습니다. 하지만 메스꺼움, 불안감, 심한 복통 같은 증상을 유발했다고 보고되었습니다."
rows["131:1582690119"]="모든 물건은 철저히 검사되고 정확하게 배송됩니다. 만약 이것이 왕이 직접 서명하지 않았다면 당신은 결코 시멘도 볼 수 없었을 것입니다."
rows["131:1585667772"]="우리 가운데 있는 호젠과 진우를 본 적 있을 겁니다. 누구나 배우고 싶은 마음이 있으면 수도원에 환영합니다."
rows["131:163006210"]="다양한 드래곤 비행의 피에서 요충을 추출함으로써 나는 착용자에게 보이지 않는 시력을 줄 수 있는 마늘을 만들었습니다!"
rows["131:1677971733"]="덩거는 무역 구역의 성벽에 새를 싣고 있어 "
rows["131:1699839154"]="왜 다른 전신들을 허용했지? 그는 얼라이언스의 깃발 아래 세계를 통합할 수 있었지. 나는 그의 야망을 믿었던 바보였어!"
rows["131:1723103419"]="그래, 내가 그를 싸워 봤어. 그는 오크가 될 정도로 큰 놈이야. 그놈에 대한 배팅을 한 주 동안 벌었어. 다시는 그런 실수를 하지 않을거야!"
rows["131:1726730526"]="이제  ⁇ 진 수가 아프고 우리 모두 위험에 처해 있어"
rows["131:1770120887"]="워터로드 히드랙시스는 폭풍의 만의 섬인 아즈샤라에서 숨어 있습니다."
rows["131:1771081475"]="미안, 지금 좀 바쁘네요. 여자들이랑 나눌 기회가 있어요. 이 싸움에서 승리하면 얘기해 주세요!"
rows["131:1798010209"]="그래, 누가 다음으로 갈지 모르지, 누가 다음으로 죽을지 모르지$b$b내 조언은 누구에게도 너무 애착하지 말아요"
rows["131:1811589503"]="우리 는 죽은 사람 들 을 슬퍼 하는 동안, 당신 의 노력 이 아니라면 더 많은 사람 들 이 잃게 될 것 이다. 얼라이언스의 감사 의 선물 을 받아 주시기 바랍니다."
rows["131:1864820556"]="여기 안개 너머에서 온 또 다른 방문자가 있는데, 그는 \" ⁇  스톰스타우트\"라고 불립니다. 그는 판다렌이지만 다른 고향에서 왔습니다."
rows["131:1865669927"]="이 유물 들 은 참으로 큰 신비 이다. 아마도 그 유물 들 을 정기적으로 연구 한다면 그 들 의 능력 을 더 잘 이해 할 수 있을 것 이다."
rows["131:1866607779"]="어! 도와줘요! 그 물건은 뭐죠? 상관없어요, 아무것도 저를 막지 않을 겁니다. 지금 그렇게 가까이 있을 때 아니죠."
rows["131:1868279348"]="미안해, 하지만 칩은 내 남자친구이고 지금은 트레이드 프린스한테 일해요$B$B앞으로 나아갈 수 있어?"
rows["131:1884199966"]="내가 무역 왕자야, 이 섬에서 나가서 아즈하라의 왕이 될 계획을 세워야겠어"
rows["131:1888571196"]="이 그림자의 벽은 우리가 넘을 수 있을 만큼 악마들을 억제할 것입니다.\010$b당신이 다른 엘프들과 건너면 따라가겠다"
rows["131:1892966063"]="누군가가 이런 결정들이 자연 상태에서 파란색이라고 말했죠. 저는 누군가 적절한 미술을 적용하는 시간을 가져서 너무 행복합니다."
rows["131:1897451503"]="여기 오면서 큰 실수를 한 것인데, 이 대회장은 빛의 요새이고, 당신의 힘은 그것과 비교할 수 없다."
rows["131:1901618197"]="여러분! 여기 겹셔츠 좀 보세요! 펄럭거리고 거추장스러운 휘장을 입지 않아도 응원하는 도시의 색상을 자랑할 수 있답니다!"
rows["131:190777650"]="이 곳 에서, 이 재앙 이 얼마나 파괴 될 지 볼 수 있습니다. 우리 이 세상 이 얼마나 취약 한 곳인지 보는 것 은 참 참 추울 것 입니다."
rows["131:1931115398"]="타이탄 웨이게이트가 거의 열리고 있습니다. 우리는 톨'비르에 울두만 재구성하고 아제로스!"
rows["131:193555033"]="가끔은 한 대상을  ⁇ 어야 합니다 적 뒤에 있는 클로로폼을 사용하세요|TInterface\\Icons\\SPELL_NATURE_SLEEP.BLP:16|t\010"
rows["131:1943246063"]="방문자님, 판다리아에게는 놀라운 시간입니다. 안개가 떨어져서 우리는 다시 세상으로 돌아갑니다."
rows["131:19580415"]="칼날첨탑 일족은 정정당당하게 싸우지 않는다. 그들을 도와주는 그론 있지. 너 칼날 산맥으로 가라. 주름투성이 모그도그와 얘기해라. 그론 죽여라."
rows["131:198091263"]="다시 본론으로 돌아가서... 우리는 마나괴철로에 주의를 기울여 대처해야 합니다. 적들이 어떻게 그리고 왜 그것을 사용하는지 알아내야 하는 것입니다."
rows["131:1992860818"]="오늘, 당신은 그의 걱정의 일부를 해결해냈을 것 같아요. 귀족과 통제력을 보여줬습니다. 아마도 그가 생각하는 것보다 더 많은 것을 보여주셨겠죠."
rows["131:2038213159"]="대지를 감싸는 공포 속에서 아메스아란은 분리의 고통을 겪었어. 그 속에선 살아남을 수 있는 희망은 거의 없었지."
rows["131:2089211659"]="경고. 식별할 수 없는 생명체입니다. 기록 처리를 중지합니다. 혼선이 계속되면 지정된 작업을 실행합니다."
rows["131:2099875633"]="난 아마 여기 머물게 될거야 데스넬하지만 일이 잘 풀리면 누가 알겠어?"
rows["131:2118787768"]="제가 탄돌 교각 부순 얘기를 해드린 적이 있던가요? 그래요. 그걸 무너뜨린 건 검은무쇠 부족 따위가 아니라 바로 저였다고요!"
rows["131:2135840519"]="안녕, 이웃$b$b난 너에 대해 많이 들었어, 이 섬에서 다투어 승부를 한 거야"
rows["131:220447283"]="미소적인 활동? 비서장 위드스판은 아무도 호수의 북쪽으로 가길 원하지 않습니다."
rows["131:232167403"]="아직 도와드릴 수 없어요, 먼저 기본이 필요해요 스톰윈드!"
rows["131:234647318"]="바보 같은! 불의 군주 사이루크 말일세! 연결 고리가 끊어졌을 때 사이루크가 깨어났지. 사이루크의 눈물이 흘러내려 이 땅을 용암으로 채운 걸세."
rows["131:244676359"]="$p 그들을 보세요. 그들은 쥐처럼 달려가고, 그들의 멸망으로 향해 머리를 돌리고 있습니다. 확실히 크라우리와 블러드펀그는 이 모든 것의 헛된 것을 알 수 있습니다!"
rows["131:253669182"]="그냥 프로스트노바를 캐스팅하는 법을 배우고 배마가 총을 쏘는 훈련 도미니에게 가서"
rows["131:258467853"]="고령인 히라 스노우다우스는 추운 날씨 비행을 가르칩니다.$B$B동달라란의 크라스스 상륙지구에서 그녀의 용어 상자 위에 발견될 수 있습니다."
rows["131:271715491"]="랄라잔, 내가 죽었으니 네가 내야!"
rows["131:284604117"]="저 우주선에서 추락한 사람들 중 한 명일지 모르겠지만,"
rows["131:288079651"]="왕국의 왕관을 입기엔 너무 부드러워서 걱정되요 안두인 왕자"
rows["131:299347423"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 붉은십자군의 이 수호자 는 펠테리스 의 무서운 주인 을 죽인 동안 살해당했습니다."
rows["131:312117613"]="이 해충들은 날 밤에도 바쁘게 해$B$B난 그냥 파이프로 뛰어내려서 도망칠 수 있었으면 좋겠어"
rows["131:323610495"]="이 곤충들은 아직 그들의 자리를 배우지 못해 가라'질."
rows["131:324674691"]="이 힘은 모든 생각의 민족들이 치유하거나 해를 끼치는데 사용한다. 그것은 생명의 힘이다."
rows["131:343199114"]="남달라나의 다양한 상인들은 장신품, 유적품, 유서품, 그리고 모든 종류의 오프핸드 아이템을 판매한다."
rows["131:346072872"]="맥주 병에 갇힌 쥐는 들어봤지만 빵은 안 들어"
rows["131:347703216"]="얼굴을 보니 마음이 놓입니다, 밀사여. 크라서스가 고대의 용이 벼려낸 검이라는 책을 우리에게 하나 내줬습니다."
rows["131:356610103"]="|TInterface\\Icons\\ability_warrior_offensivestance.blp:20|t 나즈그림 장군은 |cFFFF0000|Hspell:143589|h[ 전투 입장이]|h|r!"
rows["131:379984014"]="우리가 깨달은 존재가 되기 위해 노력했음에도 불구하고 우리는 과거의 실수를 반복했습니다.$B$B이 땅이 다시 위협받습니다."
rows["131:384009351"]="스랄! 네가 탈출할 수 있다고 생각하나? 너와 네 동료들은 블랙무어와 대면해야 할 것이다. 내가 충분히 재미를 본 다음에 말이지."
rows["131:397921561"]="눈앞에서 네 나라와 도시가 무너질 때 너도 함께 쓰러질 것이다. 우리 군주께서 이곳에서 큰 승리를 거두고, 네 이름은 누구의 기억에도 남지 않으리라!"
rows["131:424426744"]="얼음혈 묘지는 전쟁터 남쪽에 있고 얼음혈 탑 동쪽에 있습니다.$B$B얼라이언스는 현재 이 기구를 통제하고 있다."
rows["131:464839578"]="샤도-판 쿼터마스터는 타운롱 스텝의 샤도-판 가리소에서 발견된다.$B$B지도에 위치를 표시해 줄게요"
rows["131:482420658"]="고양이는 나를 동반하고 있어. 부모님이 돌아가신 이후로 농장에서 외로운게 느껴졌어.$B$B아뇨, 그렇게 많이 말하지 않으려고 했거든요"
rows["131:515403054"]="다른 훈련생들은 모두 좋은 라이더들이고, 언젠가 그들처럼 잘 할 수 있기를 바랍니다. 그 동안, 저는 계속 연습해야 합니다!"
rows["131:517012650"]="바라딘 기지 수용소에 오신 것을 환영합니다. 지금은 별로 안 보여요. 하지만 조금만 열심히 하면 이 곳을 잘 만들 수 있습니다."
rows["131:523031100"]="수영장의 마법은 그들의 마음을 확장시키고 몸들을 키워주었고, 그들은 판다리아의 위대한 고대 문화 중 하나가 되었습니다."
rows["131:538341313"]="고대의 해적 도자 를 조심스럽게 굴러 내린다. 도자 는 추락 으로 3, |cFFFF2222|Hspell:141962|h[Scurvy]|h|r로 고통 을 당한다."
rows["131:540619640"]="키린 토르는 다라란을 지키고 있어 내가 가장 좋아하는 곳은 적의 경계 뒤에 있는 곳이야"
rows["131:543371774"]="여자들이여, 제가 절실히 아끼고 있어요."
rows["131:572613457"]="우리는 우리의 홀을 형성하는 황무늬처럼 흔들리지 않습니다. 그녀의 힘으로 우리는 그녀의 신성한 집에 침입할 용기를 가진 모든 사람을 정복 할 것입니다."
rows["131:588310957"]="내 보장하오, 감독관이여. 왕립 연금술 학회는 많은 이의 목숨을 앗은 그 비극적인 사태에 대해 진심으로 보상하고 싶어하오."
rows["131:59813204"]="이 일에 책임 있는 배신자들에게 남은 구원은 고통스러운 죽음뿐이다. 내 복수는 빠르고 자비 없을 것이다!"
rows["131:59813217"]="이 반란을 주동한 배반자들에게는 고통스러운 죽음만이 구원일 것이오. 내 복수엔 자비도 주저함도 없소."
rows["131:642080424"]="바보같은 존재들아, 너희들의 소소한 불평은 리치 왕당신은 죽음을 넘어서도 그를 섬기게 될 것입니다!"
rows["131:658549848"]="|TInterface\\Icons\\spell_fire_totemofwrath.blp:20|t 재앙 수확자 5000 |cFFFF0000|Hspell:88522|h[안전 제한은 오프라인]|h|r!"
rows["131:669957966"]="많은 노력이 필요하지만, 그것은 가치가 있습니다.$B$B하지만, 조금 더 도움이 필요할 수도 있어요."
rows["131:71393798"]="가장 높은 봉우리 위에 서서 바람과 눈물이 피부를 부딪히고 나무가 마르고 산이 바다로 떨어지는 때까지 서있을 수 있습니까?"
rows["131:721713831"]="나무에 있는 마을에서 그를 잡았어. 베일... 베일 샤라스!"
rows["131:742928377"]="아타스는 아직도 여기 있는 것처럼 보이지만, 그는 사라졌어요."
rows["131:755192501"]="자발적인 일이 내 통로가 될 거야 부두술사 학교, 네가 도와준다면 내가 무료로 도와줄게"
rows["131:771461039"]="리 브라운은 크리스탈 레이크에 낚시를 하고 있어"
rows["131:792517189"]="당신의 힘은 이 땅을 오랫동안 유지된 어둠으로부터 해방시키는데 도움이 되었어요."
rows["131:805318343"]="상처가 치유되고 용기를 얻었고 달콤함과 불의 맛을 느꼈고 모든 작은 인종을 정복할 힘을 주었습니다."
rows["131:821515702"]="안심에 방해해 죄송합니다, 대장님, 하지만 형제의 영혼이 위험에 처해 있을지도 모릅니다."
rows["131:822421294"]="|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|t제국 비지르 조르록 |cFFFF0000|Hspell:122852|h[인하스]|h|r 큰 숨결!"
rows["131:849766206"]="하이트는 항상 우리가 해야 할 일에 대해 이야기합니다. 당신이 그를 그렇게 말할 수 있는지 확인하십시오. 그것은 술 게임과 같습니다."
rows["131:865013484"]="지금껏 이 세계에서 싸워 온 모든 이유를 잃었다. 아버지와 어머니... 그리고 둠해머가 품었던... 희망과 꿈이... 사라졌구나..."
rows["131:866344071"]="리거 기젤톤입니다! 제 짐마차가 만노로크 소굴을 무사히 통과할 수 있도록 도움이 필요합니다. 저희는 지금 그늘수렵 마을의 동쪽 길에 있습니다."
rows["131:868277018"]="아내는 미인도 아니었고 그의 아내가 되고 싶어하는 여자들도 많았는데도 5년이 지나고, 10년이 되도록 그는 여전히 아내를 찾아다니고 있습니다."
rows["131:882458508"]="인내심을 갖고, 여러분의 차례에 따라 이름을 부르겠습니다."
rows["131:885699148"]="제 수도사들은 트롤에 의해 축소되었습니다 부두술사전투에서 그들을 마주하고 싶으세요?"
rows["131:978550028"]="|TInterface\\Icons\\ability_warlock_soulsiphon:20|t%s가 시작된다 |cFFFF0000|Hspell:126299|h[불출한 영혼들]|h|r! 물 속으로 들어가라!"
rows["131:980950117"]="마커넌트 그린필드의 씨앗 공급을 본 적 있나요?"
rows["131:994496940"]="누가 이런 작은 돌과 끈이 어떤 힘을 가지고 있다고 믿겠습니까?"
rows["131:99646304"]="안녕하세요, 이름이 뭐죠?$B$B무슨 일이 있어? 아름다운 시골에 있는 내 고향으로?"
rows["132:1017880669"]="내가 네 머리에 찌르면 경고하지 않았다고 말하지 마"
rows["132:1041183246"]="난 자네와 싸우지 않아, 내가 이미 승리한 것 같아."
rows["132:1057560887"]="당신 마음은 이해합니다, 마쿠루. 세다이는 제 형제였습니다. 하지만, 그의 이상에 어긋나는 일로 그의 명예를 더럽혀서는 안 됩니다."
rows["132:1074607782"]="저는 거의 노스렌드의 차가운 물먹기를 이 끔찍한 습한 열보다 선호합니다. 마치 나무들이 우리를 질식시키려고 하는 것처럼요."
rows["132:1089732904"]="당신은 조그만하게 당신의 사람들의 생명을 버리는 동안 자신의 왕은 거짓말의 왕좌에 앉아, 도움으로 손가락을 올리지 않습니다."
rows["132:1109527512"]="라슬로 크루시코그에게 방어에 대해 지시해줬어"
rows["132:1138599242"]="곧 그 격차가 너무 커서 가흐릴라가 이교도들의 도시를 직접 공격할 수 있을 것입니다. 그녀는 그들을 얼음 덩어리로 줄일 것입니다!"
rows["132:1142361100"]="그렇다면 우리 는 역사 에 대한 당신 의 지식 을 시험 해 보겠습니다! 호드의 이 사신 은 실버문 시티 가 조금 더 밝고 깨끗 한 것 이라고 생각 하였습니다."
rows["132:1161777083"]=" ⁇ 은은 몇 일마다 강력 토너먼트를 개최합니다. 파다리아 전역에서 가장 강력하고 용감한 도전자들이만 경쟁할 수 있습니다."
rows["132:1162047949"]="궁금한 건 물론, 하지만 이미 해낸 일은 이미 해낸 것 같아요.$b$b불필요한 공황을 일으키지 않으려 하지 않겠습니다. 그건 현명하지 않을 겁니다."
rows["132:1231683421"]="stranded 얼라이언스 해병들은 그들이 죽을 것이라는 것을 알고 있지만, 그들은 우리에게 치아와 손톱을 싸우고 있습니다.$B$B동시에 인상적이면서도 아픔스러울 뿐이죠."
rows["132:1235086271"]="예, 저는 이 가게를 운영하고 있습니다. 최근 사업은 꽤 잘 진행되고 있습니다. 많은 새로운 모험가들이 오고 있습니다."
rows["132:1252185159"]="어머님, 한 번은 우리의 복수에서 벗어났지만 더크스피어 부족은 다시 침범을 참지 않을 겁니다."
rows["132:1252817587"]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t%s는 방출되고 있다 |cFFFF0000|Hspell:120215|h[죽음력]|h|r!"
rows["132:1268558205"]="야롱 은 매우 결정적 으로 그리고 잔인 하게 짐승 을 공격 하였지만, 그 는 더 많이 공격 할수록 짐승 들 이 더욱 무서운 것 이다!"
rows["132:1286095444"]="제 감사의 말씀을 제 여신 자이나에게 전하고, 우리 왕이 안전하게 돌아오기 전까지 데피아즈단와 그들의 후원자들을 추격하겠다!"
rows["132:1288499939"]="경비자는 잔혹한 싸움으로 죽은 것 같습니다.$B$B그의 물품 가방은 손상되지 않은 것 같습니다."
rows["132:1305606999"]="센리온 서클은 지혜롭고, 지구의 많은 비밀을 깊이 탐구했습니다. 수련자들은 이 드루이드들의 말을 잘 들으면 좋겠습니다."
rows["132:1366981445"]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows.blp:20|t 당신은 |cFFF00000|Hspell:146817|h[Aura of Pride]|h|r로 고통받고 있습니다!"
rows["132:1374071579"]="오직 한 비전은 희망의 희미한 반짝을 내렸는데 그 비전에 대의회는 당신을 위해 이 결정을 내리지 않았습니다."
rows["132:1385266705"]="GG Engineering Inc.는 |cFFFF2222책임자가 아니다|r$B 생명, 장구 또는 얼굴 털이 손실되는 경우$B 이렇게 파괴기를 사용하는 경우"
rows["132:1411330592"]="네, 하위 바람이 들어왔을 거 봐, 들어가서 앉아 잠시 쉬어라. 수수료는 적잖은데, 당신은 확실히 그것을 감당할 수 있을 것이다."
rows["132:1437308509"]="|TInterface\\Icons\\ability_garrosh_whirling_corruption.blp:20|t%s는 캐스팅을 시작한다 |cFFFF0000|Hspell:144985|h[Whirling Corruption]|h|r!"
rows["132:1470154094"]="내 지식이 당신에게 공유되기 전에 다른 사람들로부터 배울 수 있는 교훈이 있습니다. 열심히 일하고 희망을 잃지 마십시오."
rows["132:1512572356"]="여기 있는 제 보트에 몇 가지 수정 작업을 하고 있습니다."
rows["132:1557915290"]="오우거가 너무 큰 거라고 말하고 싶어! 너를 설득해서 당장 나가게 할 수 없다는 건 아는데, 그렇다고 영원히 이대로 머물 수 있을 거라고는 생각하지 말라고!"
rows["132:1568711634"]="난 네 처지에 대해 신경쓰지 않지만 내가 원하는 게 있어"
rows["132:1573021255"]="나루여, 네 어리석은 일꾼이 임무를 완수하지 못했구나. 반쯤 죽었다고 칠만큼 흠씬 두들겨맞고 왔더군... 우리가 너의 배를 지휘했을 때는 그런 실수는 벌어지지 않았다."
rows["132:1599444681"]="내가 캐라반을 목적지로 이끌고, 넌 뒤에 있어 꼬리가 깨끗해지도록 해 "
rows["132:1613419255"]="이 얘기는 이미 했다고 생각하는데, 브록. 이 건물 안에서 지낼 수는 없어. 너를 재울 수도 있지만, 그러면 다른 사람들은 아무도 못 잔다고!"
rows["132:1614287393"]="아침에는 원유 냄새가 좋아지  ⁇ 한 황 냄새가 있어"
rows["132:1623929804"]="이방인이여, 도와 다오. <유물이 산산이 부서집니다. 여덟 명의 검은무쇠 드워프들이 어떤 의식을 치르는 환영이 머릿속을 가득 메웁니다.>"
rows["132:1632682402"]="만약 우리의 적들이 우리가 그들과 조화롭게만 살고 싶다는 것을 알면, 어쩌면 우리 생존을 위해 그들을 공격할 필요가 없을지도 모릅니다."
rows["132:1638689250"]="피블 핀스핀드는 대 포지의 북서쪽에 가게를 운영하고 있어"
rows["132:1640034657"]="세세비를 찾고 있어$B$B그녀는 종종 나무 밑에 잠들어있는 늙은 어부 옴베토의 큰 호랑이처럼 생겼다."
rows["132:1656528434"]="많은 폭탄을 몰아내고 있는 건데, 그 증거는 별로 없어서 조심해"
rows["132:1657801954"]="저쪽은 산책으로 터널을 내려가지 않아서 사루크는 오늘 무력하고"
rows["132:1660843038"]="오치엔두는 내 조상들의 영들이 살고 있습니다."
rows["132:1673291617"]="이 \"도시\"는 이제 전쟁 법에 의해 처해져 있습니다."
rows["132:1719707242"]="전쟁 은 무엇 인가? 생명 을 보존 하기 때문 에? 씨앗 이 흙 에서 튀어나오기 위해 투쟁 하는 것 처럼 우리 는 우리 자신 의 존재 를 위해 싸우고 있습니다."
rows["132:1724461349"]="우리 친구들 얼라이언스 워싱글 골치에서 은 날개 세티넬과 함께 싸우기 위해 모집해"
rows["132:1738824448"]="제 교육은 계속되고, 당신의 지식은 내 지식보다 더 많아요. 더 많은 것을 배우고 싶다면 메일린과 이야기해 주세요. 그녀는 당신을 안내할 것입니다."
rows["132:1773992484"]="이 재앙을 맞이하여 우리의 삶이 얼마나 간편한지 알게 되었습니다. 그리고 저는 제 인생의 한 장도 낭비하지 않겠습니다."
rows["132:1838435493"]="이 얼음 조각은 침입하는 빙하의 깊은  ⁇ 음과  ⁇ 음의 반향을 하고 그 추위가 여러분의 생각을 무생하고 끝없는 겨울으로 바꾸어 놓습니다."
rows["132:1843145663"]="당신 의 저주 와 그 결과 가 될 수 있는 끔찍한 일 들 을 잘 알고 있으며, 자신 은 어느 정도 에 그 에 대해 죄책감 을 느끼기도 합니다."
rows["132:1846905502"]="호토른 장군은 여전히 복수하기 위해 살아있다면 의심의 여지없이 성경적 규모의 보복살을 명령했을 것입니다."
rows["132:1868308603"]="모구지아에 발굴을 한 후 탐색자연합은 그들의 발견들을 영원한 꽃의 계곡에 있는 우리 도시로 가져왔다."
rows["132:1874742905"]="오크, 당신은 당신의 분노와 두려움을 통제 할 수 없습니다."
rows["132:1917029561"]="모든 문제들은 손목으로 해결될 수 없습니다. 때때로 여러분은 스스로를 중심으로 하고, 여러분의 에너지를 멀리 있는 목표로 전달해야 합니다."
rows["132:1948772956"]="미스터리 무역업자들을 지원하기 위해 제한된 종류의 아카니즘 무역 물품을 가지고 있습니다."
rows["132:199806907"]="그루트족을 제외하면 내 형제들과 저는 하이갈 전투에서 싸웠어요 은행에서 훔치려는 사람은 먼저 우리 앞에 서야 합니다."
rows["132:2005352117"]="동물들을 돌보는 사람을 찾고 있다면, 도라나어에서 있는 숙소 밖에서 세리아드나를 찾아라."
rows["132:201956234"]="육체를 고칠 수 있는 평범한 방법들을 더 선호하는 사람들을 위해, 카나리아는 팔콘윙 스퀘어 호스 안에서 깔끔한 정장을 유지합니다."
rows["132:2036192546"]="당신을 무사히 여기까지 인도하신 빛에 감사드려요! 리치 왕을 무찌르고 스컬지를 끝장내려면 할 일이 많아요."
rows["132:2036975158"]="여자들이여, 우리는 썬더스트라이크의 그림자에서 모여서 팬니 썬더마르와 키건 파이어베드의 연합을 기념합니다."
rows["132:2041820791"]="바로 이런 걸 소환해서는 안 되는 거야. 약해빠졌잖아. 철퇴로 한 대만 치면 뼛조각이 날아다닐걸."
rows["132:206782692"]="이 지도는 암흑해안의 지도입니다. 오버딘에서 로르다넬로 가는 길들이 있고, 다른 안전한 항구도 있습니다."
rows["132:2071767589"]="왜 우리 해안으로 전쟁을 가져왔어? 호드?"
rows["132:208135548"]="스톤플로우에서 내 화려함을 훔친 영웅$b$b난 참 싸웠어, 너 옆에 싸웠다는 영광이야"
rows["132:2086576851"]="실바나스 여자의 허락으로 죽음의 스택러들의 숫자가 늘어나고 적들이 가장 기대할 때 더 많은 칼을 쏘는 거죠"
rows["132:2130409235"]="닭들이 피를 방문하면 안 돼요 오늘 시장에서 일을 마치면 만나게 될 겁니다"
rows["132:216726251"]="네, 내가 직접 몇 가지 물건을 가져와 오그리마로 북쪽으로 올라가서 찾아내야 하고 그 곳의 한 분에게 물어봐"
rows["132:225108281"]="잘했다! 적들의 사기가 떨어지고 있다! 검은바위 첨탑의 군주에게 도전한 대가를 치르게 해주자!"
rows["132:236481229"]="강도의 골짜기의 중심 요새에 한 피의 엘프가 있습니다 실버문벨록, 당신이 원하는 사람이야"
rows["132:243369745"]="자부심을 조심하고 겸손해지라 세상은 혼란에 빠지고 있습니다. 오래된 적들은 함께 일해야 합니다. 자부심한 인종들은 도움을 필요로 한다고 인정해야합니다."
rows["132:270287768"]="언더시티 수복 작전을 시작한다! 전쟁의 뿔피리를 불어라! 호드의 용사들이여, 대족장의 힘을 내리노라!"
rows["132:273705410"]="내가 이 구석에 갇혀서 모고를 많이 봤지만 모고 여자 본 적 없어"
rows["132:295606441"]="자이드 뱀의 성전으로 오신 것을 환영합니다.$B$B우리는 모든 사람들을 우리의 문 안에 환영하고, 그것을 찾는 모든 사람에게 지식을 자유롭게 제공합니다."
rows["132:298884512"]="그들이 성공할지는 우리가 이 저주받은 전당 안에서 무엇을 발견하는지에 달렸어요. 비록 우리 임무는 너무나 위험하지만, 끝까지 해내야 해요."
rows["132:312797799"]="운명을 피할 수 없지 오닉시아그것은 예언되었는데, 카라잔의 큰 홀에서 울리는 비전입니다. 이제 끝납니다."
rows["132:342730488"]="파괴된 방 앞의 그림은 악동과 다른 영들이 모여있는 것처럼 불명감스러운 말을 입을 펴고 있습니다."
rows["132:345359874"]="포위 엔진이 거의 완성됐으니 좀 지루해\010공학자가 아니니?"
rows["132:347201719"]="그래, 내가 알아, 고엘. 트롤은 호드의 지도자이지만, 당신은 그 역량으로 여기 있지 않습니다."
rows["132:373659717"]="산산조각이 났어도, 사방에 있는 수정은 나를 약하게 한다... 티탄들을 그렇게 얕잡아보지 말았어야 했다..."
rows["132:40413561"]="그밖에는 아는 게 없다... 고위사령관님은 갈 자와 남을 자를 결정하신다. 더는 아는 게 없다... 제발 믿어다오!"
rows["132:423064793"]="그는 웬더브루이고, 그녀는 골든드래프트예요 딸을 돌려보내면 한 달 동안 일 안받게 될 거예요"
rows["132:440446048"]="고대의 해적 Dice를 조심스럽게 굴러. 8, 그에게 |cFF3366FF|Hspell:141968|h[해적의 부온]|h|r."
rows["132:453213614"]="내가 여기서 뭐 하냐면, 얼마 전에 만난 어떤 분의 뜻을 따라 땅에서 쓸모없는 쓰레기들을 파낸다고... 이게 말이 된다고 생각해?"
rows["132:454443813"]="바리안 윈은 한 번 디레 마울에서 싸웠는데 5명의 야생 흉터를 맨손으로 죽였어"
rows["132:460282019"]="미친 짓, 혼란, 난 타이탄들의 일을 해소하는 것을 보고 흥분하지만"
rows["132:472108351"]="내 친구, 뭔가 줄거리가 있어. 이야기의 다음 장을 경험해볼 수 있었으면 좋겠다. 하지만 아쉽게도, 난 그저 스토리텔러일 뿐이야."
rows["132:511399936"]="크루시코가 패배하면 테르말플러그는 메카노 탱크에서 떨고 있을 겁니다. 그리고 맞습니다. 당신은 다음 테르말플라그입니다."
rows["132:516895108"]="< 고대인들은 당신의 머리 전체를 넘어선 눈을 가지고 당신을 쳐다보고 있습니다. 그들을 들여다보는 것은 깊은 파란 바다에 떨어지는 것과 같습니다.>"
rows["132:528305993"]="그리고 그롬은 영광스러운 죽음으로써 우리 모두를 피의 저주에서 자유롭게 했지만... 과거의 끔찍한 기억까지는 씻어내지 못했지."
rows["132:588756548"]="공급 관리의 힘을 과소평가하지 말아요. 전사들은 전투에서 승리할 수도 있지만, 전쟁은 물품에서 승리합니다. "
rows["132:591186627"]="난 잘 알지만 전문가가 아니야 누구와 얘기해야 할지 알아? 언더시티"
rows["132:607360998"]="쉐도우퍼가 패배한 후 그의 브루마스터라는 칭호는 내게 주어집니다. 이제 저는 그가 이 계곡에 끼친 피해를 되돌려 계속해야 합니다."
rows["132:64238133"]="용의 식사를 준비할 때에는 용이 보는 앞에서 포로를 고문하는 것을 잊지 말도록. 식전 오락에 아주 좋은 반응을 보이니까 말이야."
rows["132:665332762"]="여기서 내가 제일 똑똑하고, 강하고, 문화적인 골록이라고. 하지만, 감독은 전부 수세이가 하지... 이게 말이 된다고 생각해?"
rows["132:701531510"]="전쟁이 끝나면 어떻게 될까요? 당신은 목격한 끔찍한 사건에도 불구하고 무사히 민간 생활에 돌아갈 수 있기를 기대합니까?"
rows["132:724611671"]="불타는 군단에 대한 당신의 도움은 매우 감사 할 것입니다. 레이디 제인 프라우드무어 전선에서 당신의 도움이 필요할 수 있습니다."
rows["132:745158700"]="훌륭한 작품. 내 마음의 불은 웅장한 순결으로 빛나고, 그 불꽃의 모든 점수를 용 영혼에 전달할 것이다."
rows["132:798433619"]="많은 고통을 겪은 것처럼 보이네요. 여행에 도움이 되는 물건을 사면 알려주세요."
rows["132:823621035"]="만약 천개의 바늘의 슈하로가 무너지면 그리모테마 족속이 곧 당신의 문 앞에 있을 것이다."
rows["132:839282076"]="꽤 잘 보이지만 너무 오래 타는 거야!"
rows["132:839838744"]="두 명의 보석거래가 거주하고 있는데 하나는 크라이어와 밀접한 협력하고 다른 하나는 알도르에게 충성하고 있습니다."
rows["132:85113640"]="오그리마에서 풍자 라이더 마스터를 찾을 수 있습니다. 북쪽으로 도로로 이동하고 더 많은 방향을 요청 오그리마 Grunt."
rows["132:855914555"]="우리 민족은 마지막 마을을 지키기 위해 싸우고 있습니다. 우리가 지금 패배하면, 위대한 황제들과 철학자들의 후손이 사라질 것입니다."
rows["132:86315637"]="\"개둥이 발사하기 훨씬 전에 하늘이 떨고, 지뢰의 힘이 소모된 후에도 산에서 거동이 울린다\"."
rows["132:872872509"]="그럼... 봐요, 내 계산에 따르면 아무도 없어요."
rows["132:886915739"]="우리가 가진 모든 것을 위해 싸웠고, 텐타클과 치아를 위해서요."
rows["132:944893637"]="제가 할 수 있는 만큼 자주, 좋은 운동입니다. 그리고 그들이 뭘 하고 있는지에 대해 항상 알 수 있게 해주죠. 제 경험에 따르면, 항상 좋지 않습니다."
rows["132:97461229"]="고대의 해적 Dice를 조심스럽게 굴러. 8, 그녀를 인정 |cFF3366FF|Hspell:141968|h[해적의 부온]|h|r."
rows["133:1069533826"]="최고의 조언가를 상대로 잘도 버텨냈군. 허나 그 누구도 붉은 망치의 힘에는 대항할 수 없지. 보아라, 군주 생귀나르를!"
rows["133:1084040914"]="내가 할 때 시작할 준비가 돼 있어 마블라이트 해머가 뭐라도 시도할 경우 신부와 신부를 가까이 두고 있을 거야$B$B준비 됐어?"
rows["133:1096154552"]="당신이 해야 할 일은 부패를 캐스팅하는 법을 배우는 것이고, 그리고 배마가 총을 쏘는 훈련 도미니에 그것을 사용해야 합니다."
rows["133:1107099460"]="뭐든 필요해, 브라지  ⁇ 스!$B$B그리고 법적인 것 뿐 아니라, 당신이 필요한 모든 것, 친구!"
rows["133:1120411745"]="오그레, 이제 네 부족이 제대로 된 서류를 서명했으니 어떻게 우리한테 일하러 올 수 있을까요?"
rows["133:1127694740"]="그는 포기하지 않았어, 아이론트리 대장이 그들이 오염시킨 모든 땅값을 지불하게 해 줄 것이라고 말했습니다."
rows["133:1145020945"]="만약 내가 노스렌드에서 재보급할 수 있다면, 나는 살아있는 사람들의 마음을 냉각시킬 수있는 무기를 만들 수 있을지도 모른다."
rows["133:1213969242"]="주무시나 봐요, 위대한 자님? 이해해요. 위대한 자님으로 저희가 바친 반짝이를 거두시려면 얼마나 피곤하시겠어요."
rows["133:1222437598"]="이 문자들은 어떤 사건을 말해 주는군. 앞부분의 그림은 우리가 하늘 감시초소에서 만난 생물과 매우 흡사하군요..."
