rows["133:1300575555"]="호드가 어디로 데려다 주든지, 우리는 머리를 높이 올려놓고 피를 깨끗하게 유지해 나갈 것입니다."
rows["133:1309533369"]="자, 필멸의 존재여, 달라란에 있는 마법학자 하소렐과 이야기하기 바란다. 그가 은빛 서약단과 협상해 책을 볼 수 있게 해줄 게다."
rows["133:1329029280"]="내 친구도 곧 깨어나지 않을까봐 걱정이 난 항상 악어들의 음식을 진정시켜"
rows["133:1389502857"]="더 이상 우리 민족은 난민과 외로움을 당하고, 광기적인 전쟁 기계의 멍에에 묶여 있는 비참한 노예처럼 살지 않을 것입니다!"
rows["133:1418679806"]="환상적인 풍경호가 날개를 이용해 당신을 뒤집을 수 있어"
rows["133:143249247"]="아직은 때가 아닐세, 마이에브... 난 여러 해를 준비해 왔어. 괜히 서두르다가 계획을 망치는 실수를 범할 수는 없어."
rows["133:1436373993"]="우리는 코크론에 직면해 있습니다. 호드 '디스 트레이닝'을 통해 잠들지 않을 것 같군"
rows["133:1450826087"]="저는 kaja'mite가 우리 고대 조상들에게 있었던 것과 같은 지능 증진 효과를 원숭이에 미치는 것으로 확신합니다."
rows["133:1467872877"]="많은 충성 스럽고 헌신적 인 수련자 들 이 있다는 것 은 참으로 축복 이었습니다. 이 수련자 들 이 많이 들어온 것 이 없었다면 내 일 은 불가능 할 것 입니다."
rows["133:148656291"]="영세계에 오신 것을 환영합니다. 예쁜, 우리가 가슴을 확인하고 어떤 좋은 걸 찾아내면 내 시체를 찾을 수 있는지 보자!"
rows["133:1499171215"]="우리 가운데 악당들이 있습니다. 경계하세요. 에본 블레이드는 그들의 진정한 주인인 리치 왕를 파괴하는 것을 막으려 합니다."
rows["133:1503556715"]="하지만... 세상 만물은 조화를 이루는 법이오. 심지어 죽음까지도. 나는 그곳의 파괴와 죽음이 필요한 일일지도 모른다는 생각 자체가 끔찍하다오."
rows["133:1522049175"]="더 많은 물품! 얼라이언스 머신처럼 되겠네 곧 가로쉬의 놈들을 통과하게 될 거야"
rows["133:1547439068"]="스톰송이 프리텐더를 죽였으면 좋겠어."
rows["133:1550728079"]="전투 능력은 존경할 만한데 영웅이군 전투에서 유용하게 해줘"
rows["133:1607226525"]="지난번에 누군가 황천바위거인의 목에 걸린 현상금을 노리고 나간 적이 있었는데 우리에게 돌아온 것이라고는 무모한 모험가의 납작한 시체뿐이었다고!"
rows["133:1626958577"]="그리고 당신의 실패가 완료되고 당신의 \"힘\"이 무의미하게 될 때, 나는 당신의 통치를 빨리 침묵으로 끝낼 것이다."
rows["133:16283020"]="먼지바람초의 브래켄월 마을의 발라이 로크'웨인 (Balai Lok'Wein) 는 당신의 기술을 향상시키기 위해 당신이 공부해야 할 수 있는 설명서를 판매합니다!"
rows["133:1642209306"]="오, 가난한 자, 너는 모래로 머리부터 발까지 덮여 있어. 이 아름다운 오아시스에서 쉬고 젊어지기를 자유롭게 해봐요."
rows["133:1650016847"]="준비하라. 키트릭스가 남동쪽에서 발할라스로 들어올 것이다. 명심하라. 투기장을 벗어나는 순간, 전투에서 패하는 것이다."
rows["133:166221105"]="이 지역은 재앙의 중심지였습니다.$b$b나가 활동은 우연이 아니죠. 그들의 의도가 밝혀져야 합니다!"
