rows["133:1727595858"]="다른 걸 보여줄 수 없어, 어릴레. 가서 '인어 홀드'에서 레보스키를 찾아봐. 지옥의 반도에서요. 저보다 더 많은 것을 가르쳐 줄 수 있어요!"
