rows["133:1969784619"]="당신의 결과에 반박할 수 없지만, 무리의 자랑스러운 전사가 도망가는 농민과 농부들을 쫓아다니는 이름을 어떻게 만들 수 있을까요?"
rows["133:19754457"]="치폭의 예술을 익히기 위해 수년 동안 공부해 왔고, 당신 옆에 싸워서 영광이 될 것 같아요."
