rows["133:500238243"]="<피온의 눈은 공포로 넓어진다.>$B$B아뇨, 사우라노크가 신종교 지도자라는 걸 알아냈어요 오그리마비밀은 안전하다고 말해줬어\010"
rows["133:543225356"]="파란색 드래곤레인 (Azur Dragonshrine) 가 레이 라인의 직접적인 힘으로 투입되고 있다고 들었습니다."
rows["133:550380412"]="나가 존재의 표면을 지르면 됩니다.$b$b저는 그들이 이렇게 조직적이고 징계된 것을 본 적이 없습니다."
