rows["133:712828856"]="타우렌 족장들! 그들의 숨 막히는 실황 공연이 세상의 끝 선술집에서 펼쳐집니다! 놓치지 마십시오, 매시간 정각입니다! 샤트라스에서 쫓겨나신 분이라고요? 어딘가 몰래 들어올 구멍이 있을 겁니다! 그 대신 걸려도 저는 책임 못 집니다!"
