rows["134:1197592461"]=" ⁇ 이 물었지 아무 것도 아니겠지만 조금 더 아프게 되겠지$B$B|TInterface\\Icons\\INV_Misc_monsterfang_02.blp:32|t"
rows["134:1209374475"]="우리 사람들은 강합니다. 우리는 당신에게 미묘한 마술에 대한 마스터를 가져다줍니다."
rows["134:1244189506"]="그래서 당신은 빛의 궁전에 침입하고 우리의 비밀을 가지고 도망칠 수 있다고 생각했어요!"
rows["134:1248466736"]="젠틀 샌라는 전투 훈련자가 있는데, 그는 주 테라스에서 반려동물을 훈련합니다.$B$B지도에 위치를 표시해 줄게요"
rows["134:1259052580"]="모고, 오! 모고! 그들의 마음은 너무 작았어요. 그들은 봉사하기 위해 만들어졌습니다. 그리고 그들이 주인을 잃었을 때, 그들은 스스로를 섬기게 되었습니다."
rows["134:126205173"]="이 더러운 트롤들이 영원히 평화롭게 지낼 거라고 기대하지 않았는데 호드."
rows["134:1282072082"]="죽음의 날개는 마지막 재앙을 불러오고 있습니다. 에메랄드 드림도 떨고 있습니다. 우리가 마법을 막으려면, 우리는 함께 공격을 해야 합니다."
rows["134:1310236733"]="우리가 서 있는 땅인  ⁇ 진수, 깊은 고통에 시달리고 있습니다. 그 기원을 모르지만, 자신의 몸 안에서 그의 고통을 느낄 수 있습니다."
rows["134:132270035"]="브렉 스톤호프는 스톤호프 지질학에서 아래쪽 상승에서 발견될 수 있으며 귀중한 광석과 보석을 채취하는 올바른 방법을 가르쳐 줄 수 있습니다."
rows["134:1347283728"]="호드, 얼라이언스... 무슨 차이가 있을까요? 둘 다 좋은 맥주를 사랑하지 않습니까?"
rows["134:1409891564"]="지금 그렇게 강하지 않아? 네, 그래요. 넌 바닥에 누워있는 멍청한 것처럼 보이네 $p 더 많은 배럴을 던져"
rows["134:1423513092"]="나는 내 피와 육체를 호드에 바칠 것이다. 나는 대족장님의 뜻을 실천하는 도구가 될 것이다. 나는 대족장님의 명령을 따르는 무기가 될 것이다."
rows["134:154609849"]="약국 의사들은 리치 왕의 전염병 을 치료 하기 위해 밤낮으로 노력 합니다. 그것 들 이 없으면 호드 과 얼라이언스 모두 사라질 것 입니다."
rows["134:1555514228"]="드루이드와 샤만들이 세계 나무를 회복하기 위해 연합한다면"
rows["134:1559729895"]="워커 백스 본 적 있어?$B$B나이트워치 중 가장 강하다고 생각했는데 내가 여기 있는지 알아차린다고"
rows["134:1562438548"]="우리 는 전혀 안전 하지 않았습니다. 그들은 우리를 기다리고 있었습니다. 우리 군대는 습지에 흩어져 있고, 우리는 적의 선 뒤에 혼자 있습니다!"
rows["134:1564279433"]="이 판다렌은 꽤 좋은 음료를 만들지만, 그 중 누구도 내 좋아하는 음료를 들어본 적이 없습니다.$B$B언젠가 내가 가르쳐 줄지도 몰라"
rows["134:1615600506"]="하찮은 승리에 도취할 것 없다, 어리석은 생명체여. 너희와 다른 용군단이 여기선 이겼을지 모르나, 우리는... 마력 전쟁에서... 승리할 것이다."
rows["134:1621041776"]="벨의 통계는 9:00 오후입니다. 나로서는 휴식 시간! 4 시간 안에 모두 볼게요. 여러분 중 한 명이 잠에서 나를 죽이지 않는 한 (부탁합니다)."
rows["134:1621899171"]="수세이는 이끼걸음골록들이 이상한 날씨 얘기했을 때 자세히 알아보지 않았고, 그래서 지금 다 죽었어... 이게 말이 된다고 생각해?"
rows["134:1644289246"]="우리는 조심해야 합니다. 성전은 모고와 그들의 사우로크 노예들이 경찰하고 있습니다. 그리고 그들의 짐승들은 길에서 잔디에 숨어 있습니다."
rows["134:1647473856"]="네 말이 맞을지도 모르지. 난 조국에 대한 임무는 끝냈다. 하지만 아직 나 자신에게 빚진 게 있어."
rows["134:1702707691"]="피부 벗기는 사람들은 보통 모든 피부를 아이언포지 가봐, 훈련할 수 있는 사람을 찾아봐"
rows["134:17125943"]="그레고리는 길네아스 출신 신동맹 중 한 명인데, 그가 여기에 관여할 수 없다고 가정하기 쉽기 때문에 그를 신뢰하기로 결정했습니다."
rows["134:1749237902"]="다르나서스에만 그런 공식적인 문제들이 처리됩니다. 당신은 당신의 길드의 창조 과정에 시작하기 위해 그곳에 가야합니다."
rows["134:1785774103"]="사실 스라이어들은 도서관에서 그 이름을 찾을 수 없다고 합니다."
rows["134:1791444423"]="당신 밑의 드레이크는 치명적으로 상처받았고, 떨어질 뻔했습니다!\010|TInterface\\Icons\\inv_misc_hook_01.blp:32|t"
rows["134:1797260696"]="라스 프로스트비스퍼의 힘을 빼앗아 죽게 하고 한번에 죽게"
rows["134:1835385800"]="다르나서스로 가는 길에서 라드나알이 집 밖에서 그의 공예를 연습하는 것을 발견할 수 있습니다."
rows["134:1841031988"]="조상들의 축복을 받아주십시오. 하지만, 제 대리 없이 줄 수 있는 것은 다 아닙니다."
rows["134:1874448016"]="라그나로스, 게든, 가르의 중위원들이 내 주인에게 배신을 저지른 것입니다."
rows["134:1879785969"]="군단의 최후가 눈앞으로 다가오고 있다. 수없이 많은 세계를 불길에서 구해냈다는 사실을 자랑스럽게 여기며 당당히 서라."
rows["134:1922593528"]="우리는 이제 마침내 우리의 조상들의 집에 발을 들여놓고 있습니다. 우리 생애 처음으로요. 그리고 당신은 돼지 농장에서 휴식을 취하고 싶으세요?"
rows["134:1926176712"]="모든 예방 조치를 취하고 있다고 믿습니다.$b$b이건 위험한 곳이고, 만약 당신에게 무슨 일이 생기면 용서할 수 없을 겁니다."
rows["134:1927609191"]="하오한과 같은 우정을 맺으면 틸러스 조합장이 직접 찾아서 도움을 줄 것 같습니다."
rows["134:1937052935"]="|TInterface\\Icons\\spell_shadow_rainoffire.blp:20|t 화려한 끝의 헤럴드 캐스팅을 시작 |cFFFF0000|Hspell:100761|h[카타클리سم]|h|r!"
rows["134:1950821973"]="어두운 시대는 이상한 우정을 만들어 냅니다. 로데론 이 포세이큰 그들의 작은 빗자루를 태워라"
rows["134:19650018"]="네싱워리와 그의 소년을 서쪽으로 보면 우리가 얼마나 많은 것들을 죽였는지 말해줘"
rows["134:1991278861"]="웨일든은 겁쟁이야 스컬지에서 도망쳤고 이제 영웅처럼 여기 오려고 용기가 있어?$B$B- 바!"
rows["134:1995171727"]="글쎄. 하뮬은 우리를 잘 이끌었고, 나도 그에게서 너무나 많은 것을 배웠소. 전설에 따르면 태초에 드루이드는 우리 족속이었다지..."
rows["134:2006559898"]="우리는 호드 고대 유수의 비밀들을 우리한테 반도할 수 있게 해"
