rows["134:2034676612"]="이 전쟁에서 승리하려면, 우리는 바닷물이 우리를 뒤덮고 앉아서는 안 됩니다. 우리는 강력하고 빠르게 공격해야 합니다. 아니면 아라티는 다시는 우리의 것이 될 수 없습니다."
rows["134:2050672817"]="아무것도 안 했어, 자네와 얘기하고 트롤과 얘기해야 했어\010"
rows["134:2052366303"]="흠, 분명 그녀는 자신이 스토나드의 새로운 주인이라고 믿고 있어. 그녀의 서큐버스를 도와 난장판을 정리해 주겠다고 제안하는 게 어때?"
rows["134:2057741342"]="배흐'로르, 반타르,  ⁇ 트리퍼, 심지어 강력한 투커까지 모두 잡았어"
rows["134:2090510573"]="페어브리즈 마을이 여전히 남아있다는 것은 우리 인종의 끈기라는 증거입니다. 우리는 다시는 스컬지에 패배를 인정하지 않을 것입니다."
rows["134:2121482114"]="나무보다 높은 버섯을 처음 봤을 때, 이 곳을 고향이라고 부를 수 있을지는 몰랐어요."
rows["134:2124331172"]="이런, 별볼일없는 놈이로군. 채석장에서도 못 써먹겠구나. 마지막 순간을 즐겨라. 곧 넋 나간 언데드가 될 테니 말이다."
rows["134:2134331288"]="마지막으로, 우리가 훈련해온 기술을 활용할 기회가 있습니다. 누가 알겠어요?"
rows["134:2141793040"]="오그리마에 있는 한 개 있어요. 거기 있는 한 사람이 어떤 방향을 알려줄지 알겠죠. 북쪽으로 가서 이 길을 따라가세요."
rows["134:214217587"]="아무리 어두운 것처럼 보이더라도, 저는 희망을 잃지 않아야 합니다. 야롱의 폭력에 당당하지 말아야 합니다.\010넌... 우리를 도와줄게 왔어?"
