rows["134:389308792"]="그래, 내가 시초였다... 죽음의 수레바퀴가 수도 없이 돌았지. 참으로 오랜 세월이 흘렀어... 끝내야 할 일이 너무 많다."
rows["134:402358620"]="우리의 원래 의무는 이 땅을 지키고 있어야 하지만, 만약 판드랄이 실제로 불지방으로 탈출했다면,"
rows["134:403693714"]="더 쉬워지는 거 없어, 스트라톨메가 불타고 있습니다. 우리는 스컬지와 불에 용기를 기울여야 합니다."
rows["134:41804932"]="로르나 모닝라이트는 도라나르에 사는 사람들에게 치유를 제공해줍니다. 어쩌면 그녀는 목사들의 길을 가르쳐 줄 수 있을지도 모릅니다."
