rows["134:567135943"]="조람의 힘이 일어나자! 우리 적들이 우리의 굴레 안에  ⁇ 겨져 버리자! 나가서 그들에게 화살표에 직면하는 것이 무엇을 의미하는지 가르쳐라!"
