rows["134:623015857"]="그 전에 큰 갈색 남자가 북쪽으로 여행을 찾고 있었는데, 가라도가 뭐... 가노쉬가 뭐..."
rows["134:62594925"]="이제 떠나게 되요, 친구 타우렌의 친구가 에루나크가 바다마들과 함께 밖에서 기다리고 있을 겁니다. 사실, 그는 지금 여기 있는 것 같습니다."
rows["134:693277434"]="오늘날 마법은 과거 수천 년에 비해 희미해졌지만, 우리는 아크니얼에 대해 많이 알고 있습니다."
