rows["135:1095993471"]="치 치는 북서쪽에서 자신의 농장을 가지고 있습니다.$B$B저 가난한 놈은 한 번씩 병에 걸려"
rows["135:1111939001"]="벨가리스트라스는 진실을 말하고 있습니다. 시간이 지워지고 있습니다.\010드레이크의 전력은 풀려났어 에레고스를 물리치기 위해 그들의 힘을 사용하라"
rows["135:1115170461"]="저들이 추적자들을 더 많이 보낼 경우를 대비해서 여기서 헤어지는 게 좋겠소. 우리 중 한 명은 가로쉬에게로 돌아가야 할 테니 말이오. 몸조심하시오, 이방인이여."
