rows["135:1151616219"]="인간들은 먼지바람의 많은 부분을 자기들만의 것으로 주장했지만, 스톤말족은 우리의 도움으로 그들을 밀어내게 되었습니다."
rows["135:116343396"]="난 나즈그림, 전쟁의 총장과 호드 오늘 죽어야 한다면, 전장에서 명예로 죽을 거야 호드!"
