rows["135:1190792834"]="만약 우리가 흙구멍처럼 시간을 형성하고 형상화할 수 있다면 어떻게 될까요? 어떤 가능성은 기다리고 있을까요?"
rows["135:1200222261"]="놀랐겠지, 쓰레기 같은 녀석! 내 동생이 어디 있는지 말하지 않으면 네 아내에게 진은 탄환을 한 통 가득 박아주겠어."
rows["135:1210254617"]="흥미롭게도, 네더트론 배출량은 고보-시인 곡선 규모를 이용해서 증가하고 있지만,  "
rows["135:1224502104"]="하지만 물론, 우린 호드의 이익을 염두에 두고 있습니다."
rows["135:1224876913"]="내가 혼자 돌아갈 거야 로이스 덤스비스터에게  ⁇ 어줄게"
rows["135:1229630875"]="하지만 크로스로드 이 지역은 불모의 땅타우라조 캠프의 조용함을 선호합니다."
rows["135:1235887139"]="악! 조용히 합시다, 에드! 악당들이 근처에 있소이다! 저자들을 귀가 밝아서 방금 당신이 낸 소리도 다 들을 수가 있단 말이오!"
rows["135:1238145397"]="하자라, 드림비버$B$B악몽의 힘은 그의 것이며, 그의 적들은 영원히 잠들게 하소서.$B$B하자라가 이제 미친 짓의 가장자리에 꿈꾸고 있습니다."
