rows["135:1429551497"]="진정 쿠엘델라가 맞군. 살아서 탈로리엔 돈시커가 지녔던 전설의 검이 우리에게 되돌아오는 날을 맞이하리라고는 생각 못 했소."
rows["135:1431870276"]="책들이 사라지고 있습니다. 로리키퍼와 그의 부하들은 광기에 빠져 있습니다. 그들은 엘드레'타라스 안에서 악행을 의심합니다."
