rows["135:1443864324"]="이제 악몽이 현실이 됐지. 닥터 테러블이 왔다. 널 공포에 떨게 하고, 온 세상을 무릎 꿇게 하리라. 그리고 난... 아무것도 느끼지 않을 거야."
