rows["135:1467842044"]="그 냄새가 뭐야? 그 냄새는 뭐야?! 그 냄새는 너 그래프타가? 어떻게 그런 냄새를 가질 수 있어? 이것은 매우 모욕적입니다. 가장 모욕적인 것은, 그렇습니다."
rows["135:1488323320"]="우리의 가장 위대한 영웅은 세상을 떠나셨습니다. 우리 모두를 구한 것이 바로 그롬 님이셨지요... 그가 만노로스를 쓰러뜨리고 피의 저주를 영원히 끝냈을 때 저는 그분의 옆을 지켰습니다."
