rows["135:777306117"]="아달의 목소리 울리는 소리가 당신의 마음을 안심하게 울린다.$B$B걱정 마, 꼬마, 가방에 들어가면 다시 찾을 거야"
rows["135:778405541"]="|TInterface\\Icons\\creatureportrait_bubble.blp:20|t%s 캐스트 |cFFFF0000|Hspell:124653|h[물 껍질]|h|r! 워터 스팟을 사용하여 팝업하십시오!"
rows["135:795893919"]="밖이 저렇게 소란스러우니 오늘 언제까지 장사할지 기약할 수가 없네요. 수리해야 할 물건이 있으시다면, 제가 얼른 봐 드리지요."
rows["135:802988186"]="|TInterface\\Icons\\ability_warrior_riposte:20|t%s는 발사하기 시작합니다 |cFF9900CC|Hspell:109893|h[Arcane Infused Armor]|h|r! 그녀의 갑옷을 노출하십시오!"
rows["135:877590743"]="아직 스프리트들이 많지만, 도움이 정말 감사해요."
rows["135:895237375"]=" ⁇ 돌에서 일할 수 없는 먹이, 마지막 순간들을 풀어주면 곧 넌 무의식적인 죽은 자일 거야"
rows["135:8983604"]="우리가 돌아가야 하는데, 나는 내 사촌의 마을에 나의 기술이 필요할 것이라고 확신합니다. 그리고... 우리는 잃어버린 사람들을 위해 장례식을 준비해야 합니다."
rows["135:916612039"]="외계인, 샤도파인의 동맹자$B$B<노인 야롱은 이상한 말을 쓴 채로 뱉는다.>$B$B목을 찢으면 더 가까이 와!"
rows["135:944212340"]="지나의 심장에 두 가지 방법이 있다는 걸 알고 있었나? 하나는 내 시장에서 좋은 고객이고, 다른 하나는 스윙글 미스트  ⁇ 입니다!"
rows["135:971743852"]="오늘 네가 할 수 있는 모든 것을 해줬어 난 널 안전하게 지켜줄게"
rows["135:981821208"]="내가 더 잘 알지 못하면 내가 죽을 수 있는 나를 비웃고 있다고 생각하겠지만, 네, 그것은 대부분 옳습니다. 당신은 완전히 옷을 입었으면 좋겠습니다."
rows["135:982107657"]="우리의 유일한 목적은 리치 왕우리는 우리의 운명을 호드 그리고 우리의 구원의 길을 시작했어요."
rows["135:993985598"]="분노가 폐하를 삼켜버릴까 두려워요, 스랄. 이성을 찾으시길 바라지만, 최악의 상황도 준비해야 합니다... 전쟁 말이에요."
rows["136:1013831835"]="아무도 이 호수 바닥에 있는 걸 알 수 없는데 그 아래로 갔던 사람들만 알고 있고, 그 후에 이야기한 사람들만 빼고는"
rows["136:1040822426"]="전 옛 친구인 엘프들이 '호드'와 동맹을 맺었다고 소문을 들었는데 항상 우리가 그들에게 신뢰하는 것은 어리석은 짓이라고 했지"
rows["136:1043321820"]="지침에 따르면 얼마나 많은 마나 이 크리스탈이 필요해?"
rows["136:1078289931"]="나가들이 항구와 우측에서 공격하고, 얼굴 없는 놈들은 머리를 맞대고..."
rows["136:1092962959"]="레트트라벨은 고고학계의 영웅이 되어 거의 40년이나 됐습니다. 그가 기억할 수 있다면, 오, 그가 이야기 할 이야기들..."
rows["136:1094905501"]="불에 대해 놀라며, 두려움과 놀이에서 모인 필사자들은 그 불은 그들의 음식을 요리하고 그들의 집을 따뜻하게 만들 수 있었습니다. 그들은 그것을 붙잡고 보호했습니다."
rows["136:1106504461"]="아델 필더는 엘윈을 둘러싼 가죽 노동자로 이름을 알렸다."
rows["136:1124571118"]="쿠엘다나스 섬은 캘타스 선스트라이더 왕자의 군대가 장악했다. 그가 죽었다는 정보가 입수된 바 있지만, 이 정보는 잘못된 것이다."
rows["136:1126576801"]="최근 좋은 살인사건이 있었나요?$b$b어제 드레네이를 죽였는데, 여전히 쓰레기  ⁇  근처에서 찾을 수 있어."
rows["136:1130274137"]=" ⁇ 과 콩의 전통에 관심이 있습니까? 요즘 많은 젊은이들이 그렇게 매력적인 지적 여행을 할 준비가 되어 있지 않습니다."
rows["136:1144513634"]="그리고 이 지진이 얼마나 위험한지 알고 있는 사람들은 오늘날까지, 우리의 갑작스러운 도착으로 인해 에크소더가 여전히 흔들리고 있습니다."
rows["136:1152824410"]=" ⁇ 차가 당신의 애완동물을 안정시켜 명예의 계곡에서 아레나와 사냥관 사이의 양궁에서 찾아내라"
rows["136:1176016002"]="워워, 아직 로켓 준비가 덜 끝났습니다. 퓨즈가 완전히 타 버리거나 저 위에 당신 혼자 남는 일이 없도록 퓨즈 길이를 조절해야 해서 말이죠."
rows["136:1195649688"]="은 계약은 대회에 오신 것을 환영합니다. 아르헨티나 십자군 전쟁은 참가자 등록과 훈련에 대해 요청했습니다."
rows["136:1315451062"]="탭링은 세대를 거쳐 온 예술의 형태입니다. 그 사실이 아닌지 다른 사람에게 묻지 않아도 됩니다."
rows["136:1323615741"]="만약 킬제덴이 선웰을 통해 일어나면 우리 세계는 10,000년 동안 본 적이 없는 전쟁에 투입될 것입니다!\010"
rows["136:1332417235"]="드래곤 해조리 때문에 왔어? 미안해."
rows["136:1345496979"]="정해진 시간에, 그들은 폭풍의 원자력을 방출하여 도시를 씻어내고 우리 주인 영광스러운 복귀를 준비합니다!"
rows["136:1349049964"]="너의 희생이 네 충성심을 증명하는구나. 그래. 넌 자격이 있다. 일어나라. 이제부터 네 이름은 스발라 소로우그레이브다!"
rows["136:136181655"]="호크스트라이더는 귀한 생물입니다. 항상 당신의 것을 잘 대접할 수 있도록 하십시오. 분노한 호크스트라이더보다 더 위험한 것들은 적습니다."
rows["136:1383090365"]="전염병이 일어나기 전에 저는 피부에 대해 아무것도 몰랐습니다. 이제 다른 사람들에게 가르치기 위해 충분히 알고 있습니다. 죽음은 저에게 많은 시간을 남겼습니다."
rows["136:1401009261"]="만약 내가 나가서 싸우지 않는다면 아제로스내가 군에 왜 들어가야 하는 거야?"
rows["136:1414679451"]="결국, 천둥왕이 쓰러졌고 벨은 손을 바꾸었습니다. 많은 사람들이 그 힘을 사용하려고 시도했습니다. 일부는 그 소리를 침묵시키려고 노력했습니다. 모든 것이 실패했습니다."
rows["136:1422739082"]="샤프비크는 에리 피크에서 가장 훌륭한 기리폰이야 지нта'알로르의 정상까지 데려다 줄 거야"
rows["136:1437035299"]=" ⁇ 라이에서 바람이 불어오고, 수년 동안 보이지 않았던 존재가 다시 돌아오고 있을지도 모른다고 생각합니다."
rows["136:1442625526"]="이 먼 곳들을 둘러싼 알도르의 친구들을 보는 게 좋지만, 이 엘프들의 거칠고 거칠고 말들을 더 참을 수 없을 것 같아요."
rows["136:1470669574"]="우리는 얼라이언스의 အာ라티에 그들의 권력 기지를 확장할 수 없게 해줘야 합니다! 그들의 작은 피난처 지점도 언젠가는 우리를 위협할 수 있습니다."
rows["136:1501094841"]="시내에서 새 향수와 콜론을 주문했는데, 포장 풀면 다시 체크해 줘서 판매할게"
rows["136:1521996956"]="한 날, 한 아버지 는 어린 새끼 의 잘못 행태 를 보고 피곤 하게 되었다. \"너는 마치 똥구리처럼 행동 한다!\"고 아버지 는 고문 하였다. 그럼에도 불구하고 그 아들 은 잘못 행하였다."
rows["136:1526786745"]="도끼, 곡괭이, 씨앗, 못, 음식, 담요, 물... 필요한 건 뭐든지 거기 다 있소. 가격도 딱 적당할 거요."
rows["136:1537849166"]="그 길을 따라가는 사람은 없는데 그 설명과 일치하는 사람이 있다고 들었어요"
rows["136:1548477635"]="비술사에게 일러라. 그의 동족은 호드와 얼라이언스의 곁에서 함께 싸우며 말리고스와 리치 왕의 군대에 맞서야 한다고 일러라."
rows["136:1548581204"]="좋습니다, 대족장님. 왕실 지구는 이쪽입니다. 경계를 늦추지 마십시오. 바리마트라스와 퓨트리스가 무엇을 준비했을지 모릅니다."
rows["136:1627096065"]="우리 관계에서 장점을 보실 겁니다. 우리가 지휘하는 힘이 엄청나게 많아요. 우리의 도움으로, 여러분의 적들이 잘 멸망할 수 있습니다."
rows["136:164401349"]="우리의 임무는 놈의 총알받이를 최대한 많이 없애면서 우리 지도자들이 모셔온 전문가들을 지원하는 것이다."
rows["136:1644142182"]="썬더머는 와일드햄어의 마지막 포지션이야 내 동생은 우리 마을이 난민들로 가득 차 있는 동안 계속 싸우고 있어"
rows["136:1657926000"]="이 섬은 완벽한 해안 요새가 될 것입니다. 로클라! 보직자들이 도착하면, 나무들을 제거하고 항구 건설을 시작하십시오."
rows["136:1672472282"]="이 예술에서 나보다 더 위대한 사람이 있다. 당신은 그녀의 지식을 받을 준비가 되어 있습니다. 그녀는 안노라입니다."
rows["136:1690402542"]="제가 떠나기 전에, 당신이 바닥에 누워있는 것은 내 잘못이 아니라 제 사장의 잘못이라고 알려야 합니다."
rows["136:1695181962"]="내가 아는 한 가지는 좋은 친구로 항상 의지할 수 있다는 것입니다. 만약 당신이 그런 사람을 가지고 있다면, 그들을 잘 소중히 여기십시오."
rows["136:1715339110"]="모그의 역사를 이해하는 것이 필수적입니다. 성공적인 공격에 대한 우리의 가장 좋은 기회는 적의 지식을 통해 온다."
rows["136:1730282176"]="알갈론은 고대 신이 행성 중추 기능에 미친 시스템 손상 수준을 평가해 진단을 내립니다. 응답 코드 오메가를 도출할 확률은..."
rows["136:1755016181"]="당신이 숲속으로 사라진 직후, 구출된 군인들이 파우돈에서 우리를 찾아오기 시작했습니다."
rows["136:1777063712"]="파티에 '탐탁지 않은 것'들을 너무 많이 들이는 것 같지 않아요? 제 친구들이 어떻게 생각할까 걱정이랍니다."
rows["136:1788765048"]="무역업자들이 필요로 하는 물품은 세계 곳곳에서 많이 구할 수 있습니다. 그렇지 않은 사람들에게는 적당한 가격으로 제한된 선택지를 제공합니다."
rows["136:18679398"]="새매야, 정말 고맙구나. 네가 없었으면 우린 몇 년이고 까마귀 경전을 찾느라 헤맸을지도 몰라. 이제 나그란드에 있는 네 집으로 돌아가거라."
rows["136:1874292423"]="가슴에 손바닥을 얹고 다른 손으로 앞으로 손을 뻗어 무한한 것을 만져보세요. 부드러운 느낌인가요?  \010"
rows["136:1876268170"]="여기 도착한 걸 알 수 있네, 이 날엔 해가 터지면서 영원한 우물 붕괴로 세계 대륙이 찢어졌어요."
rows["136:1901093998"]="동부에서 은행을 찾고 있다면 왕립 거래소에서 더 이상 찾지 마세요."
rows["136:1907845369"]="최근 캠프 주변에는 오크가 몰려들기만 했다고$b$b오크 그로그는 내 의견에 동의하지 않는 것 같군"
rows["136:191629737"]="이것은 좋은 소식입니다. 그론에 대한 비밀 작전은 계획대로 진행되고 있습니다. 그리고, 외부에서 누군가가 우리를 도와주고 있습니다."
rows["136:1926574482"]="내 여행 이 시작 되었을 때, 나 는 힘 을 무분별 하게 하였고, 백종 은 통제 를 가르쳐 주었다. 증오 와 분노 와 폭력 은 사라졌다."
rows["136:195540869"]="누가  ⁇ 을 설득해서 사루크들이 경쟁하게 했을까 궁금합니다."
rows["136:196651969"]="네, 우리는 우리의 필사적 코일의 단순한 함정에 넘어 올라서서서 오래 전에 사르게라스가 약속한 힘을 얻을 것입니다."
rows["136:1983749976"]="구신의 귀여운 가흐즈릴라의 축복받은 짐승은 매일 더 크고 강해지고 있습니다."
rows["136:199420070"]="스톰하트 왕은 철 Dwarves의 바람을 잡았다 이 방향으로 이동하고 그는 모든 최고의 전사를 모집 할 수 있었다"
rows["136:201160551"]="난 너같은 놈이 다른 해적들을 영구적으로 처리할 수 있어"
rows["136:2018132471"]="무슨 일이 있었는지 모르겠지만, 방금 베노스피트에 도착했고 갑자기 이 구석에서 깨어나서$B$B날 구하러 왔어?"
rows["136:2032066924"]="용서를 빌어요, 영웅들, 저는 우더를 들어야 했거든요. 저는 직접 보고 싶었어요. 마지막으로 그의 눈을 바라봐야 했습니다."
rows["136:2055693806"]="다른 고르록들보다 더 많은 싸움을 하고 있지만 여전히 네 언어를 제대로 배울 시간을 찾는데..."
rows["136:2116020539"]="귀여운 건 아니지, 어떻게 밸리에서 나왔어?"
rows["136:22129495"]="여기 있네. 당신이 가져온 물질은 대략... 150,000 년이나 됐어?"
rows["136:221497439"]="피즐, 포지크, 진키 모두 우리를 구했다고 생각하지만 내가 해박을 만들었다$B$B라즈리크의 스피드바지라는 이름이 붙어야 해요!"
rows["136:275809383"]="오늘 이 일은 당신 앞에 놓인 시험입니다. 무쇠 감시자가 죽었을 때에만 우리에게 돌아올 수 있습니다. 그러면 서릿결 부족의 전사로서 숭배받을 것입니다."
rows["136:284492632"]="샤타르의 초점은 그림자 달 계곡과 이리lidan에 남아 있지만, 우리는 카엘타스 선스트라이더가 제시하는 위협을 무시할 수 없습니다."
rows["136:29543944"]="핵이 당신 손에 있다면, 제거 과정에서 발생하는 손상을 피하기 위해 안전하게 땅에 놓아주세요."
rows["136:296594236"]="마일고스가 사원을 공격하는 것은 합리적이지 않죠."
rows["136:326109425"]="날 물리치려면 다른 마스터들로부터 배운 모든 것을 사용해야 합니다. 그렇게 할 수 있다면, 훈련이 완료될 것입니다."
rows["136:326353365"]="자네가 무슨 말을 하는지 모르겠군, 용이여... 하지만, 나는 이런 무례한 행동에 겁을 먹지는 않을 것이야. 때가 되면 그때 카라잔을 떠날 것일세!"
rows["136:389652378"]="생각을 바꾸었다, 나의 충성스러운 부하들이여. 포로를 내 서재까지 데리고 올 것 없다. 여기서 지금 당장 해결하겠다."
rows["136:396715324"]="이 모든 이동을 조심스럽게 해야 합니다.$b$b들어가자고 준비됐어?"
rows["136:420746548"]="바다에 많은 시체들이 있어$b$b근처에 전쟁이 있습니다.$b$b사우로크에게 좋은 일이죠. 더 많은 시체들은 더 많은 음식과 더 많은 더러운 것을 의미합니다."
rows["136:433785330"]="글쎄다, 꼬마야. 먼저 '가시덤불 골짜기의 푸른 언덕'을 읽어 보면 어떨까. 그러고 나면 우리 탐험대에 들어올 수도 있을 거야. 어때?"
rows["136:445520125"]="빨리 메카토르크와 얘기해 빨리 공격하지 않으면 늦을 거야$B$B그리고 우리들이 늦으면 내 보스가 싫어해요!"
rows["136:446949541"]="하스테워더와 그들의 지도자인 칼리프 스코피스팅이 남쪽으로 향하는 걸 봤어요"
rows["136:501260118"]="내 노력에도 불구하고 암흑 아이언들은  Twilight's Hammer의 손에 남아 있습니다."
rows["136:528956863"]="하지만 호드은 거대한 군대를 모았습니다. 전쟁 기계와 고장된 참전용사들의 거대한 함대."
rows["136:534254126"]="그들은 하루 종일 이갈루크 바위에서 발견한 모구 무기에 대해 이야기해 왔습니다.$b$b그들은 우리를 전혀 의심하지 않습니다. 계속 좋은 일을하십시오."
rows["136:547116622"]="천상의 도움으로 우리는 모그 진전을 통과했고, 남자들은 그들을 밸리에서 쫓아낼 수 있었습니다."
rows["136:568265225"]="우리의 뇌 해커가 경매에서 팔렸는지 확인해봐야 합니다."
rows["136:571779840"]="새 Shado-Pan 동반자를 선택하기 위해 스카도-판 기병으로 돌아갈 수 있습니다.\010쉐도파인 동료를 해고하고 싶다고 확신하십니까?"
rows["136:581070461"]="내 문으로 돌아오는 모든 관광객을 놀릴 시간이나 에너지가 있는 것처럼 보이나요?"
rows["136:612387186"]="순수한 마음이 있는 사람들은 뉴 아발론에 남아있을 수 있습니다."
rows["136:616091601"]="알렌 브라이트를 사설 근처 스파링 링에서 찾아라\010그는 과 박사 구스타프 반하우젠이 섬의 치료사들의 훈련을 감독합니다."
rows["136:628273045"]="샘플링이 중단됐습니다. 삼비노 제품은 진심으로 사과합니다."
rows["136:629834377"]="마법 을 받은 토리움 은 매우 인기 있는 금속 이다. 그 중 일부를 발견 할 수 있는 가장 좋은 기회 는 공예 한 수강자 또는 광자 와 이야기 하는 것 이다."
rows["136:641823766"]="루트테라네 페리를 가기 위해서는 다르나서스로 이동하고 테일드라실의 기지에 있는 루트테라네 마을로 가는 게이트를 가져가야 합니다."
rows["136:649250348"]="전설에 따르면, 번개왕은 엄청난 힘을 가지고 궁전 요새를 세웠고"
rows["136:650570603"]="크라우리, 당신과 당신의 엘프 동맹들은 왕의 군대에서 복무하도록 명령받습니다. 저주받거나 안되더라도 여전히 길니안 법에 구속되어 있습니다!"
rows["136:650578948"]="육즙이 많은 돼지 갈비와 샌더 선장의 비밀 소스로 양념한 옆구리살을 준비하지요."
rows["136:663263359"]=" ⁇ 메레건 비밀작업의 케일시 스틸스파크가 여러분들의 서비스입니다."
rows["136:70075256"]="넌 확실히 지역인 아냐, 하지만 난 신경쓰지 않아."
rows["136:707264284"]="여기 좋은 일을 해냈어 친구 앞으로 강력한 운영 기반이 있어야지"
rows["136:711031596"]="넌 구 힐파우를 위해 너무 많은 일을 해줬어 그 늙은이 놈이 지금 네 회사를 그리워하고 있어"
rows["136:738050674"]="예, 영영 꽃의 계곡에 있는 지식의 자리에서 글쓰기 트레이너를 알고 있습니다.$B$B지도에 위치를 표시해 보도록 해"
rows["136:743164681"]="여기서 해야 할 일을 잊지 마세요. 이 황폐한 사막에 대한 눈을 감는 동안 의식들을 계속하세요."
rows["136:777411779"]="켈투자드라고? 그 이름을 알고 있다면 내가 가져오라고 했던 책을 읽은 게로군.$B$B미안하지만 자네의 대답은 틀렸네."
rows["136:788700681"]="제플린은 1분도 안 돼 해안을 둘러보죠!"
rows["136:797908460"]="명예의 사각지대장은 서쪽의 큰 벽인 뱀의 척추에 있습니다.$B$B지도에 그들의 위치를 표시해 줄게요"
rows["136:800588459"]="이제 당신은 통치자처럼 생각하고 있습니다. 당신은 문제를 모든 측면에서 살펴봐야 합니다. 자문자들과 협의하고 자신있게 행동해야 합니다."
rows["136:80670771"]="우리는 다른 사람들을 만나게 된 행운을 얻었습니다 호드 이 새로운 땅에서 우리 형제들이 다른 곳으로 떠났다는 것을 몰랐습니다."
rows["136:833602477"]="10분 후에 위커먼 축제가 시작됩니다. 스톰윈드 시티의 문 밖에서 우리와 함께 해로우의 끝을 축하하십시오!"
rows["136:855422505"]="보물을 원하니까 금과 화석을 어디서 얻을 수 있는지 알아?"
rows["136:865921150"]="난 윈터호프 캠프를 그리워할 거야 하지만 아슈토템 장군이 왜 결정을 내렸는지 이해해"
rows["136:892137780"]="제발, 음성을 낮추세요. 우리가 공부하는 것들을 레이디 프라우드머에 상기시키는 것은 현명하지 않습니다.\010이제, 진정한 힘에 대해 이야기 할 수 있을까요?"
rows["136:950928992"]="그레이블해머 부관이 탁자 위 책과 두루마리 더미를 뒤적이다가 한 권을 흥미롭게 살펴보기 시작합니다."
rows["136:958969810"]="용사 사령관 오크하트 지휘관은 타운롱 스텝의 니우자오 성전에서 발견된다.$B$B네 지도에 그녀의 위치를 표시할게요"
rows["137:1012319740"]="사냥꾼의 진정한 징조, 인생의 끝없는 게임에서 자신의 먹이를 쫓는 것입니다."
rows["137:1017010443"]="가족의 개들만 다른 사람들을 자신의 실패로 이끌고 싶어!"
rows["137:1026648868"]="핫 로드 의 열쇠 를 사용 하십시오 |TInterface\\Icons\\inv_misc_key_12.blp:32|t 차에 올라가서 친구들 이지, 에이스, 고버를 찾아"
rows["137:1043586437"]="제 형제들이 얼마 전 이 곳에 없었고, 제 인연은 점점 더 희미해졌습니다."
rows["137:1077528633"]="아니나 다를까 정찰병이 돌아와서 길 아래에 오크가 있다고 보고를 했지. 그들은 아직 우리를 발견하지 못했기 때문에 우리가 가서 안면을 터야겠다고 생각했다오."
rows["137:1087336722"]="과일 상인! 아직도 네 마차가 우리 영업을 방해하고 있다! 앞으로 한 시간을 줄 테니 우리 구역에서 마차를 빼라. 우리 인내심을 시험하지 마라!"
rows["137:1095928515"]="저기서 큰 걸 발견했는데 갑자기 돌들이 반격하고 모든 사람이 미쳤어"
rows["137:1126526199"]="'나'라는 별명을 들었는데, 내 피부를 잘 쓰는 능력 때문에 '발리꾼'이라고 불렀던 시절이었어."
rows["137:1131763811"]="너의 승리는 오래 가지 못한다. 얼라이언스와 호드의 시대도 점차 끝나고 있어! 우리가 다음에 또 만나면 그게 바로 끝이 될 것이다."
rows["137:1174693060"]="사실, 내 가슴에 있는 어린이는 가장 오래된 친구의 이름을 따서 \"코르\"라고 불립니다.$b$b그리고 내 등에 있는 이 젊은 챔피언은 그의 구원자라는 이름을 따서 \"$p\"라고 불린다."
rows["137:1195777990"]="반려동물을 먹이고 잘 취급하고 놀이를 가르치고 있습니다."
rows["137:1212117742"]="여보게, 라그누스. 난 자네가 능력 있는 친구라 생각하네만 난 인내심이 많지 않다네. 무라딘이 이곳에 있는 걸 아네. 내 형제에게 날 인도해 주지 않을 텐가?!"
rows["137:123888534"]="이 전지대는 고기 없는 구역입니다. 기계 장치의 건설에 고기들을 사용하는 사람들은 끊임없이 조롱을 받게 될 것입니다."
rows["137:1291886669"]="나의 형제 스톰후프는 나보다 훨씬 위대한 전사였네. 내가 부족장이 되기 위한 훈련을 받는 동안 그는 더욱 중대한 임무를 준비했지."
rows["137:1364520194"]="자리가 하나 더 있었던 것 같은데... 이런, 내가 잘못 알았군. 하나가 아니라 일곱이었네. 자네가 칼 좀 쓰는 사람이었으면 좋겠군. 병영에 가서 보고하게."
rows["137:1422540349"]="내가 숨을 쉬는 동안 이 코크론 동물들은 없어서 거로쉬를 몹시 화난 개처럼 죽여줄 약속해"
rows["137:1468241180"]="이 비전에서 살아남았는지 궁금해요"
rows["137:1499807150"]="여기 뻗은 피부에 그려진 단어들은 당신이 아직 준비가 되지 않은 것을 요구합니다.$B$B나중에 다시 확인해"
rows["137:1504486669"]="장군  ⁇ 은 고구려의 고대 유물을 악왕에게 넘겨주려고 합니다."
rows["137:1515068626"]="성공을 위해 우리에게 필요한 건 정예로만 구성된 소규모 타격 부대이다. 바로 그 때문에, 우리는 은빛십자군 마상시합을 열었다."
rows["137:1522313923"]="난 싸움을 좋아하는 사람이 아니야 무거운 물건을 챙기는 건 아니지만 근육은 약해지고 흔들리는데"
rows["137:1529932525"]="당신의 매력적인 필요에 대해, 당신은 Jade 숲의 Dawn's Blossom에서 Spellpaw 라이와 이야기해야합니다.$B$B지도에 위치를 표시해 줄게요"
rows["137:153240146"]="그대의 도움으로 데피아즈단과 이번 납치의 주모자이자 왕궁의 일원으로 변장했던 오닉시아를 연결할 수 있었습니다."
rows["137:1536255199"]="분명 왕은 그들이 트롤 문제를 해결하는데 도움을 주면 호드에 대한 그의 캠페인에 더 많은 군대를 줄 것이라고 생각했다."
rows["137:1618133342"]="당신 주변을 둘러봐요, 샤만님, 여러분은 지구, 공기, 물, 그리고 불을 만져 온 요소들의 균형을 볼 수 있나요?"
rows["137:1640257789"]="저는 자동차의 매트릭스 레룰미터에 새로운 장치를 설치했습니다. 이 장치가 자동차의 속도 계수를 15배 이상 증가시켜야 합니다."
rows["137:1679934769"]="헤이건은 낙스라마스의 벽과 바닥에 수많은 함정을 설치해 놓았고, 자신이 원하는 대로 얼마든지 작동시킬 수 있다고 한다."
rows["137:1696378067"]="이자들은 모두 미쳤어요! 자기들의 주인이라면서 로켄을 섬긴다는 말은 계속 중얼대지만, 정작 직접 명령을 받는 자들은 얼마 되지 않는 것 같아요."
rows["137:171980649"]="폭풍, 지구와 불! 난 절대 큰 닭처럼 옷을 입고 달빛을 하늘에서 내리는 건 아니지 "
rows["137:1793177294"]="사우로크는 미혹하지만, 결국 유용하게 쓰일 수도 있습니다.$b$b모그에 대항해 그들을 자극한다면, 그들은 우리의 사람들을 멀리서 끌어낼 수 있습니다."
rows["137:1824572170"]="당신이 내게 부여한 힘은 인간의 마음 위에 큰 정신적 영향을 주었다."
rows["137:18396161"]=" ⁇ 옷을 입고 혼자 유태에 맞서고 보이 칼만 들고 \"부럭\"이라는 칭호를 얻으실 겁니다."
rows["137:1847317844"]="내 시간을 빼앗아갈게 된다면, 당신이 가치가 있다는 걸 증명해줘요."
rows["137:1850021338"]="무기의 마스터는 상인의 최고 수준인 전사 테라스에서 위치해 있습니다"
rows["137:1857735777"]="네 무기가 느끼는 갈망은 앞으로 닥칠 일의 그림자일 뿐이다. 진정한 갈망을 보고 싶나? 진정한 힘을? 영웅이여, 계속 나아오라. 기다리고 있겠다."
rows["137:186244590"]="오그림의 해머에 탑승해 보고서 사우르팡 대장이 기뻐할 겁니다"
rows["137:1873407144"]="이건 끔찍해요$B$B우리 자신의 불편함을 신경쓰지 않지만 뼈 폐기물에서 죽은 사람들의 고통을 완화하기 위해 뭔가 해야 합니다!"
rows["137:1897085582"]="내 진주들을 채굴하고, 내 몸을 조각하고, 내 마음을 왜곡하고..."
rows["137:1911453585"]="네, Cenarius, 우리는 이 영역을 계속 지켜야 하지만 오늘과 우리가 얻은 위대한 승리를 축하하자"
rows["137:19355555"]="우리는 오랜 시간 열심히 죽기 날개를 위해 노력했습니다."
rows["137:1942796862"]="여보게, 라그누스. 난 자네가 능력 있는 친구라 생각하네만 난 인내심이 많지 않다네. 무라딘이 이곳에 있는 걸 아네. 내 형제에게 날 인도해 주지 않을 텐가?!"
rows["137:1969823441"]="심심없는 사우로크들은 작은 도마뱀 두뇌를 가지고도 곧 자신의 위치를 깨닫고 모구의 적들을 죽였습니다."
rows["137:2048915944"]="저브 ⁇ 이 돌아왔을 때 너무 행복해 난 다크 아이언 맥주도 곧 끝나지 않길 바랄 뿐이야"
rows["137:2084784837"]="보석공업은 정말 좋은 일이야.$B$B지도에 위치를 표시해 줄게요"
rows["137:2100371484"]="우리가 암흑에 대한 힘을 가지고 있고 그 힘을 사용해서 큰 돈을 지불합니다."
rows["137:2111747698"]="이 모든 싸움은 헛되이군 어떻게 네 사람들이 항상 그렇게 하는 거야? 언제 간편한 것들을 축하하고 즐길 시간을 찾느냐?"
rows["137:2113361376"]="당신들의 잔은 기쁨으로 가득 차있고, 여러분은 즐거움을 마실 것입니다. 당신의 잔은 슬픔으로 가득 차있어서, 여러분은 슬픔을 마실 것입니다.$B$B술은 현명하게 선택해 내 친구"
rows["137:2135645655"]="구루바시 공격자들은 계속 들어오고 있습니다. 우리는 여기 갇혀 있고, 며칠 동안 외곽 포스트로부터 소식도 받지 못했습니다."
rows["137:213688251"]="|TInterface\\Icons\\ability_hunter_pet_dragonhawk.blp:20|tJi-Kun은 그녀를 보내 |cFFFF0000|Hspell:134380|h[Quills]|h|r 모든 방향으로 날아!"
rows["137:2140210329"]="비안시 (Byancie) 는 종종 지역 야생지를 순찰하는 경비자들에게 서비스를 제공해 왔습니다."
rows["137:2141349097"]="당신은 채굴 재료를 수공관에서 구입할 수 있습니다. 왼쪽으로, 주요 건물에 들어가면$B$B지도에 위치를 표시해 줄게요"
rows["137:24519051"]="우리는 얼라이언스 고대 유수의 비밀들을 우리한테 반도할 수 있게 해"
rows["137:276196813"]="우리가 그를 찾아야 한다면, 우리는 올바른 방향으로 가고 있습니다."
rows["137:290641819"]="강한 광란심장 일족 여기 많다. 다지크가 대부분 가르쳤지. 처음에는 너 같은 것도 가르쳤지. 알겠지만 너는 광란심장 일족이 아니다."
rows["137:311797575"]="좋소, 대족장이여. 이리로 가면 왕실이오. 경계를 늦추지 마시오. 바리마트라스와 퓨트리스가 무엇을 꾸미는지 모르니 말이오."
rows["137:320320596"]="새로운, 더 강한 원자체가 공격하고 있지만 불은 통제를 벗어났습니다!"
rows["137:357967995"]="우린 당신처럼 이 계곡에 새로 왔어요. 문이 열렸을 때 왔어요.  ⁇ 라이에 집을 잃었거든요."
rows["137:385703028"]="하지만 내가 저지른 끔찍한 일들과 내가 해친 사람들을... 나는 그들을 알고..."
rows["137:484036619"]="내가 경고하고 있어, 로르테마르 얼라이언스은 도시를 포위하고 있고 우리는 헬스크림을 파괴할거야"
rows["137:485832518"]="이  ⁇  라이 판다렌들은 잘 나갑니다. 이제 그들이 당신이 가득한 그런 더러운 것을 보여준다면요."
rows["137:50225132"]="새 드래곤마우 동맹의 요청과 호소로 왔는지 모르겠지만, 당신이 안 믿어도"
rows["137:507826481"]="다시 생각해봐, 파오리스 죽음의 날개는  ⁇ 의 힘을 이용해 울담의 비밀을 밝혀 큰 파괴를 일으키게 될 것이다."
rows["137:510587872"]="노겐포거 씨, 저는 당신이 중립적인 무역 기관으로서의 명성을 손상시키고 싶지 않다는 것을 알고 있습니다. 호드와 더 긴밀한 관계를 형성함으로써!"
rows["137:554844830"]="머리, 머리가 없는 멍청한 아이디어들 중 \"아, 브로트, 멋지다... 포세이큰는 우리 머리 위에 금 동전을 내리게 될거야!\""
rows["137:579843036"]="기억하세요, 여러분, 여러분이 하는 매술은 아무리 작은 일이라도 두 가지로 나뉘어 있습니다."
rows["137:59545125"]="질문 있나? 없다면 자세한 지시와 명령은 각자의 분대장에게서 받도록 해라. 이상이다. 건투를 빈다!"
rows["137:61408519"]="재건을 위해 많은 물품을 모았지만 더 많이 필요해  ⁇  발더를 수리하기 위해서"
rows["137:635345390"]="이 사업에 대한 가격으로, 좋은 수익 공유 체크를 기대하고 있습니다."
rows["137:684209429"]="푸른용군단에 도전하겠다니... 그렇다면 네놈들의 영혼과 육신을 분리하는 일로 지루함을 달래야겠다!"
rows["137:711767358"]="|TInterface\\Icons\\ability_druid_ravage.blp:20|t 가라론은 적어도 두 명의 플레이어를 타지 못하고 승부를 올린다 |cFFFF0000|Hspell:122754|h[Fury]|h|r!"
rows["137:734641877"]="여기 스파크터치들은 며칠 동안 늑대와 싸우고 있지만 다른 구두가 그들을 도울 수 없었어요"
rows["137:736976149"]="망자 쿠에츠룬의 감시자가 지닌 돌풍 정수를 얻어야 예언자를 이 세계로 끌어당길 수 있으리라. 이 두 가지 희귀한 물건을 하르코아에게 가져다주어라."
rows["137:749352089"]="이 표본 중 한 조각의 고기를 잘라서 지금까지 배운 것들을 테스트해 봅시다"
rows["137:788980461"]="내 맥주 공장에서 싸움을 하기 위해 온 게 아니지?"
rows["137:793106345"]="아타스는 한때 인간 왕자였는데 노스렌드 끔찍한 운명을 겪었습니다.$B$B내 동생인 타사리아인은 그 군대의 일원이었습니다."
rows["137:81113474"]="윈터그래스프 전투장에서 강화가 필요해!"
rows["137:811321829"]="난 내 주인에게 명령하겠다, 그 값이 얼마든지"
rows["137:818688526"]="제플린을 바다로 떨어뜨리는 것은 어렵다고 생각하겠지만, 4차례 더 힘들다고 생각하겠죠!"
rows["137:837589985"]="...그런데 하뮬의 가르침은 엘프도 이미 아는 것들이오. 나이트 엘프 말이오. 그들은 밤의 소생으로서, 달의 여신을 굳게 믿지."
rows["137:891823776"]="적들이 다가오고 있어 움직일 능력을 이용해 남쪽 램프로 람카헤인 챔피언을 이동시켜$B$B|TInterface\\Icons\\misc_arrowleft.blp:64|t"
rows["137:901867768"]="파다렌 건설 현장에서 놓친  ⁇ 을 사용하여 발전 속도를 영구적으로 높여라! $B$B|TInterface\\Icons\\INV_CASK_04.blp:64|t"
rows["137:912223246"]="괜찮아요! 늙은 브란이 있잖습니까! 무쇠 괴물 좀 맡아주세요. 그동안 저는 이 기계가 도움이 될지 만져보죠."
rows["137:918281528"]=" ⁇  라 이 에서 많은 사람 들 이 집을 떠나게 된 것 을 보고 고통 스럽습니다. 보호 를 필요로 하는 사람 들 에게 안전한 은옥 을 찾은 것 으로 매우 기쁘습니다."
rows["137:957576861"]="알트라세프 트랜스포터도 실망하지 않길 바라지만, 낙하산만장만 들고 다니는 것이 좋습니다."
rows["137:962702980"]="이  ⁇ 은 미끄러지고 속임수 있고 더 나쁜 것은 부끄럽거나 후회하지 않는다는 것입니다.$B$B그들은 욕심과 쾌락을 위해 죽인다."
rows["137:979931825"]="정말 친절하고, 제 음식들을 요리하려고 노력하지만, 불행히도 먹을 수 없어서, 그가 보지 않을 때 내버려두어야 합니다."
rows["137:984188588"]="안녕하세요, 당신은 큰 대포로 빠른 이동을 찾고 있지 않았나요?$B$B내가 할 수 있어!$B$B작은 대가를 치르면 당연히..."
rows["137:999110339"]="피테마는 우리의 앵커리트이고, 사고 피해자를 돌보는 데는 귀중한 역할을 해왔어요."
rows["138:1003389416"]="이 신발은 내가 어렸을 때 지낸 야크의 신발이니까"
rows["138:1015002021"]="보니가 필요한 걸 팔고, 골든 랜턴에 판매하고 있어"
rows["138:1123637574"]="새로운 신병들의 상태가 어떠세요? 우리는 더 많은 군인들이 필요합니다. 블랙록 오크들이 우리 영토를 침공하는 것을 막아야 합니다!"
rows["138:1149556016"]="드레네이 사람들은 나루의 언어로 '엑소다르'라는 단어의 의미를 가지고 있다고 농담하는 것을 좋아합니다."
rows["138:1150505009"]="램 레이싱은 생각보다 쉽지만, 숙달이 필요한데, 램을 잘 조종하고, 사과 먹어도 돼 램을 피해야 한다."
rows["138:115562301"]="이 일의 가치를 언젠가 아셨으면 합니다, 가로쉬 님. 서로 계속 싸운다면 결코 스컬지를 이길 수 없습니다."
rows["138:1197596023"]="진주족은 또한 겸손한 기원으로 원시적인 존재였는데,"
rows["138:1234932202"]="물론, 저는 우리가 훔친 물건을 거래하지 않는다고 말했습니다. 이것은 스톰윈드 경매집이고, 담배로 가득한 거리의 교류회사가 아닙니다!"
rows["138:1247082803"]="우리가 저항해야 했지, 왜냐하면 우리가 그들이 원하는 것을 가져갈 수 있도록 허락했음에도 불구하고 그들은 어쨌든 우리를 죽였기 때문입니다."
rows["138:1251693889"]="조울의 저주가 고엘을 원자상태로 이동시키고 있어"
rows["138:1296745085"]="칭찬은 잘 받을 거야 티리온도 곧 칭찬을 해줄 거야"
rows["138:1369005458"]="이 자료는 프로젝트 블루북에 아주 유용하게 쓰일 겁니다. 제 새로운 모습에 있어서도 좋겠네요."
rows["138:1450590391"]="대부분의 언더시티' 복수 착륙'에 배치된 군대가 노스렌드, 워시프가 우리를 보내서 도시의 방어력을 강화해"
rows["138:1454656010"]="걱정 마, 스셔터포인트는 그들이 올만큼 강하다. 하지만, 기지가 무너질 때, 그립폰에 뛰어들 준비가 돼 있어."
rows["138:1471682923"]="이 말을 들어봐,  ⁇ 한 공작 내가 너의  ⁇ 마어 랩도그가 아니야 난 널 도전하러 왔어"
rows["138:1475173147"]="얼라이언스와 호드의 어리석은 약자들은 지금 우리가 말하는 Twilight 고산지로 이동합니다."
rows["138:148588367"]="몇 년째 달철에 일하지 않았지만, 잊을 수 있는 일이 아닙니다."
rows["138:1532206568"]="이 땅 사람들이 달의 축제를 열리는 것은 놀라운 일이 아닙니다. 저는 무롱라데에 가서 참석하기를 매우 좋아합니다."
rows["138:158329"]="내가 항상 여기 머물지는 않아. 얼마 전까지도 세계 곳곳을 혼자 여행했지. 난 야수와 용족, 신과 보물 이야기를 좋아해."
rows["138:1601785923"]="벤자민 폭스워리와 그의 애완 동물인 슬라이가 수리공사 뒤에 있습니다. 골드샤이어- 가서 도와줄 수 있는지 봐"
rows["138:1602629054"]="오그리알라를 지나간 첫 날부터 준비해 왔어요"
rows["138:1654776130"]="우린 거의 물량이 부족해 전투장에 또 다른 지상 공격을 할 준비가 되기 전에 더 많은 일이 필요할 겁니다"
rows["138:1676294886"]="당신의 힘이 많이 사용된 것 같고... 용어에 대해 용서해주길 바랍니다."
rows["138:1676444287"]="솔직하게 말하겠다. 우리는 그곳을 공격할 것이다! 그럼 제군들 중에 그 임무를 맡을 용감한 오크는 과연 누구인가?"
rows["138:1680809122"]="끝없는 그림자의 지안의 역사입니다."
rows["138:1684805510"]="물론, 또 한 해의 전투가 벌어지고 엄청난 희생자가 썬더 블러프하지만 나머지 호드 결국은 굴복했을 겁니다."
rows["138:1742337357"]="더 많은 보강이 도착할 때까지 여기서 지연할게요$B$B아타스가 우리가 여기 있다는 걸 깨닫기 전까지는 시간이 많지 않을 겁니다."
rows["138:1742428612"]="만약 제가 물어볼 수 있다면 어떻게 이 조각을 되찾았을까요?"
rows["138:175246020"]="엘프들이 오랜만에 숲에서 벗어나고 있다고 합니다. 하지만 호드에 합류하는 것은 사실이 아닐까요?"
rows["138:1754925046"]="해적과 켄타우르, 그림토메, 오, 신하!$B$B어제 밤 머리 위로 날아다니는 큰 걸 봤어요 달이 막혀버렸어요"
rows["138:1806673339"]="아이언포지 기억이 잘되면, 그레이트 포지에서 한 가게가 있어"
rows["138:1824234084"]="희망에 대해 말씀하시는군요. 믿으세요, 우리가 어떻게든 다가올 재앙을 살아남을 수 있다는 믿음은 저를 지지하는 유일한 요소입니다."
rows["138:1846080838"]="파다리아는 안개가 닫힌 이후 전면 전쟁이 일어나지 않았습니다."
rows["138:1852222949"]="예쁜데, 예쁘다! 당신은 이미 동쪽 성전을 방문한 거 보니까 이 동상이 왜 우리 생활에 중요한지 이해해"
rows["138:1857897364"]="광산이 곤충으로 침투한 상태에서 어떻게 광산 샘플을 수집해야 할까요?"
rows["138:186210461"]="다음 스카이 레이스 전에 배운 것에 대해 명상할 충분한 시간이 있습니다."
rows["138:1877082716"]="우린 비참한 놈들에게 너무 자비가 있어$B$B선사일 앵커리지에서의 그들의 용기가 용서할 수 없습니다."
rows["138:1884413725"]="그렇다면 역사에 대한 당신의 지식을 시험해 보겠습니다."
rows["138:1887048767"]="거머리는 좋은 코를 가지고 있어, 냄새로 행운과 나쁜 운의 차이를 알 수 있어."
rows["138:1887792725"]="정말 이놈의 세금 때문에 못 살겠습니다. 테레나스 국왕은 이런 재건축이 경제 부흥에 도움이 된다고 생각하는 걸까요? 정말 어디가 잘못돼도 한참 잘못 됐나 봐요."
rows["138:1898111986"]="마지막으로, 그리고 확실히 가장 중요한 것은 피로블라스트가 있습니다. 이것은 절대적으로, 긍정적으로 지속적인 첫 인상을 만들고 싶을 때입니다."
rows["138:1907693615"]="그는 아직 당신을 볼 수 없지만, 걱정하지 마세요. 나는 그가 그의 바쁜 일정에 적응하는 방법을 찾을 것이라고 확신합니다."
rows["138:1922636416"]="적을 한 인치도 허용하지 말자. 만약 그들이 암흑해안에 공격한다면, 다르나서스 그 자체로"
rows["138:1953123325"]="경매소는 어디있어요? 아이언포지 우리 아름다운 도시로 들어갔을 때,"
rows["138:1971967933"]="이 붉은 동상은 당신이 들고 있는 세티넬의 보석처럼 생겼습니다.$b$b동상은 작은 진입이 있는데, 보자의 크기와 일치합니다."
rows["138:1972876386"]="제 사제 여부들 중 몇 명을 보내서 도와주세요."
rows["138:1989630153"]="이  ⁇ 스마디, 내 탱크와 다크스피어 모두 있잖아."
rows["138:201224963"]="지구 어머니, 우리들 중 한 명을 당신의 품에 맡겨주십시오. 그녀는 유나야 호크윈드입니다. 우리 모두의 어머니이자 할머니입니다."
rows["138:2025478537"]="내 돈은 네 바람의 계곡에서 온 한 아이한테$b$b제이드 숲의 수도원에서 훈련 받았다고 들었어요"
rows["138:2043446255"]="오늘처럼 낯선 사람들의 친절에 감사하는 날이 있는데..."
rows["138:2070481231"]="고대의 해적 Dice를 조심스럽게 굴러갑니다. dice는 떨어지며 11, 그에게 |cFF3366FF|Hspell:142061|h|h|r을 부여합니다."
rows["138:2097921532"]="페렐리 씨, 여행을 하다가 스컬지 활동이나 뭔가 은밀한 공작 같은 걸 목격하시면 가장 가까운 로데론 병사에게 알려주시기 바랍니다."
rows["138:2108401349"]="하지만 그를 물리치기 위해서는 그의 위대한 힘의 근원을 찾아내야 합니다."
rows["138:2108572487"]="내 힘을 이 칼에 집중시켜야 하오. 그러면 이 칼과 관련된 영상을 더욱 확실하게 볼 수 있을 것이오."
rows["138:2111750848"]="고대의 해적 Dice를 조심스럽게 굴러갑니다. dice는 떨어지며 11, 그녀를 부여합니다 |cFF3366FF|Hspell:142061|h|h|r."
rows["138:2113751127"]="호랑이의 날개의 윙어, 눈 속에서 양자의 호흡, 숲을 가로지르는 곰의 속도는 사냥꾼에게 인생입니다."
rows["138:2114949988"]="기억나는 것은 많지 않습니다, 마그니 형님. 전 악몽을 꾸었습니다... 키가 큰... 밝은 색 머리의... 죽음의 검은 갑옷을 입은 자가 나타났지요. 그의 이름이 혀끝에서 맴돌기는 하지만..."
rows["138:2133356892"]="너무 많았어요... 우리 공격은 순위를 잘 못 긁어냈어요."
rows["138:219963604"]="죽음의 날개가 우리 세상에 들어왔을 때, 이 날개와 디폴름의 사이에는 틈이 있었습니다.$B$B세계 기둥을 재건하는 것만이 균열을 안정시킬 수 있는 유일한 방법입니다."
rows["138:244458881"]="다른 연습생들에게서 윙워드 섬에서 희귀한 오닉스 알을 찾을 수 있다고 들었습니다."
rows["138:256459668"]="좋아, 파멸의 군주 카자크께서 기뻐하실 것이다. 공격 속도를 높여라. 최대한 빨리 오크와 드워프의 요새를 파괴해라."
rows["138:283812175"]="잠깐만요, 우수한 엑스클을 사지 않고서는 안 되죠."
rows["138:293260340"]="고어게크는 절대로 닭장에 \"걸려 넘어지는\" 게 아니야. 그놈은 항상 멍청한 배를 채우려 들어. 닭을 다 잡고 보면 꼭 한 마리가 빈단 말이지."
rows["138:294593812"]="이 연구 결과를 팔아서 황천 로켓의 좌석을 구입하는 게 현명하겠지. 어서 여길 떠나야 할 것 같은 기분이 드는군!"
rows["138:347027573"]="네 친구들랑 같이 갈 수 있는 만큼 잘 어울릴 수 있어"
rows["138:369108241"]="여기 머무는 건 너무 위험해 생명은 잃지 않는 땅이 없어"
rows["138:387494895"]="산림 벌이는 참 나쁜 단어입니다. 저는 이 말을 비평을 해소하는 것 처럼 생각하기를 더 좋아합니다!$b$b어떻게 그 나무들 사이로 바다를 볼 수 있었을까요?"
rows["138:39066524"]="전투장에서 경쟁자들을 물리쳐야 합니다. 승리에 따라 금메달이 보내질 가능성이 있습니다."
rows["138:414520168"]="또 다른 치명적인 적의 탄생을 축하하는 것은 이상하긴 하지만, 우리는 동맹국들과 함께 그들의 축제에 참여할 것입니다."
rows["138:419741871"]="스카이던서  ⁇ 은 판다리아에서 비행을 가르칠 수 있어"
rows["138:427462651"]="바콘에게 말해야 돼, 그는 고기를 많이 가지고 있어$B$B지도에 그의 위치를 표시해 줄게요"
rows["138:441434978"]="만약 우리가 무장 없이 둘러싸여 있고 상처받고 압도당한다면 우리는 그들의 얼굴에 뱉어내며 머리를 들어올릴 것입니다."
rows["138:46568521"]=" ⁇ 의 미술에 더 발전하고 싶다면 제 고용주 키렌과 이야기해 주세요."
rows["138:491424654"]="난 더 나은 걸 받을 자격이 있어, 난 배우야, 연기자야, 평범한 덤브 위프가 아니야"
rows["138:52636613"]="아니, 얘야, 이건 더 나쁜 일이야 호드스톤탈론 피크에서 나오는 어둠은 고대적이죠."
rows["138:537720002"]="아래 드래크는 탑승을 거부하고 있습니다."
rows["138:591088001"]="이 유물은 많은 폭풍을 견뎌냈고, 심각한 악화의 징후를 보여줬습니다."
rows["138:606462348"]="내 스카우들은 그 숲에 강력한 무기들이 있다는 것을 알려줬습니다. 만약 그들이 멈추지 않는다면, 얼라이언스은 우리를 공격할 것입니다."
rows["138:618363422"]="난 그 사실을 가르쳐 줄 수 있겠지만, 여기 오그레 타닌만 찾을 수 있을거야."
rows["138:618635738"]="숨겨진 동굴이라고? 흥미로운 사실이군. 네 할 바를 다 해주어서 고맙다, 랜드그렌. 안타깝지만, 이번에는 다시 살아나지 못할 것이다!"
rows["138:620708413"]="말이 너무 길었군... 너는 이 황혼의 인도자와 맞서 싸우려고 세상 먼 곳에서부터 나를 찾아 여기까지 왔다. 너를 실망시키지는 않으마..."
rows["138:6272088"]="복습할 수 있도록 영상은 계속 켜 두겠다. 상대의 능력을 잘 파악해라. 그 능력이 약점일 수도 있으니 말이다."
rows["138:634067743"]="|TInterface\\Icons\\ability_vehicle_siegeenginecannon.blp:20|t 갈레온은 |cFFFF0000|Hspell:121600|h[Cannon Barrage]|h|r를 발사할 준비를 하고 있다!"
rows["138:659243585"]="땅과 물에는 많은 변화가 있습니다. 여러분, 그들... 많은 변화가 있습니다.$B$B이 변화 들 이 카마가우 의 생활 방식 을 위협 하는 것 이다. 당신 은 어떻게 할 것 입니까?"
rows["138:720061259"]="여기 모든 것이 아니라 아웃랜드 이 지역만큼이나 무산한 지역입니다. 이것은 에버송의 녹색 잔디밭과 숲과는 상당히 다릅니다."
rows["138:728369684"]="내 피난처의 문을 열었으니, 가서 쉬어라."
rows["138:730708935"]="친구, 팁 하나 있어. 큰 채소를 원하면 비료를 써야 해$B$B밸리의 가장 좋은 비료를 누가 가지고 있는지 아세요?"
rows["138:747267371"]="숲은 윈터그래스프 서쪽에 있어 영혼이 돋보이는 색을 찾아봐"
rows["138:776300726"]="달콤한 걸 찾아내야 돼$B$B보통은 전면 테라스나 성당의 주관에서 돌아다니고 있어요"
rows["138:780820504"]="우리 정찰병이 보고하기를 어느 어둠의 집단이 그란골바르 마을의 폐허로 들어왔다고 합니다. 앗, 이 보고는 일주일 이상 지난 것이로군요."
rows["138:782055621"]="음, 무라딘! 갑판을 정리하고 위쪽 성채를 공격할 수 있도록 병사들을 준비하시오. 스톰윈드에서 병력을 더 보내겠소."
rows["138:79343937"]="그리폰들은 짐승들을 돌보지 않고\010상거래 구역의 성벽에 덩가르 롱드링크를 찾을 수 있습니다."
rows["138:801659789"]="친구들, 와일드햄어 생활 방식이 위협받고 있습니다. 우리 적들은 서로 격리되어 있을 수 없을 만큼 많아요. 우리는 연합해야 합니다."
rows["138:808244869"]="랜더의 계곡에 가까워지고 있어 이 오크들은 강하네|TInterface\\Icons\\SPELL_NATURE_PROTECTIONFORMNATURE.BLP:16|t\010"
rows["138:816376212"]="4개월 동안 마법을 하지 않고, 기분이 좋아$B$B누가 이런 신선한 과일과 뜨거운 차를 먹을 때 미스터리의 무한한 신비가 필요할까요?"
rows["138:831904784"]="전쟁에서 우리 동포를 보호하는 것처럼, 우리는 또한 포세이큰의 이익을 보호해야 합니다."
rows["138:854477697"]="|TInterface\\Icons\\ability_mage_conjurewater11.blp:20|t 일리던은 |cFFFF0000|Hspell:103952|h[영원 물]|h|r로 자신을 마비한다!"
rows["138:908668246"]="아무것도요. 빛에 구속된 이상 대영주님께서 하실 수 있는 일은 없습니다. 성스러운 빛이 완전히 조종하고 있기 때문에, 그 고결함으로 꼼짝할 수 없으실 겁니다."
rows["138:912502953"]="리페이 선생의 목소리는 \"아야, 다시 만나서 반갑습니다. 존경심과 함께 왔어요. 그래서 당신이 찾는 답을 줄게요\"."
rows["138:92228610"]="루퍼트 보흐가 있어요. 그랑 그의 동원은 브릴 남동쪽의 겔로우스 엔드 타버너에 있는"
rows["138:922374183"]="실비아, 내가 널 에스토란 타워로 보내서 고르도니 오그레를 몰아낼거야"
rows["138:940470462"]="다른 샤만도 깨달음을 찾고 있지? 영들이 미묘하게 말하고 있지?"
rows["139:1011849222"]="오크 배들은 칼림도어 해안선, 승객이 대륙에 도착할 수 없고 우리 상인들은 그들의 상품을 이동시킬 수 없습니다!"
rows["139:1018796965"]="대우조선장판드랄 스태겔름은 드루드를 깨우고 Darkshore의 고대의 원주단을 설득시켜 우리 사람들이 재건할 때가 됐다고 했습니다."
rows["139:1028115263"]="만약 우리가 무장하고 무력한 채 둘러싸여 있고 상처받고 희망이 없는 상태라면 우리는 그들의 얼굴에 뱉어내며 머리를 들어올릴 것입니다."
rows["139:1051014901"]="페시크스, 네가 믿었던 기술적인 거품이 널 실망시킬 거라고 말해줬어"
rows["139:1062021069"]="저 위에 알도르의 가장 신성한 신전과 주거지들이 있습니다. 그 곳은 매우 신성한 장소로 사제회에 속한 자들만이 환영을 받는 곳이지요."
rows["139:1069385744"]="칭찬으로 받아들여서, 항구를 지키고 군대를 지휘해 볼진이 오그리마의 문에서 당신을 기다리고 있어야 합니다."
rows["139:1093310006"]="내 신아, 나 좀 데려가줘요! 난  ⁇ 에 갇혀서 무서워"
rows["139:1096841596"]="다시 한번, 저주를 받은 잃어버린 사람들을 도와줘서 고마워요."
rows["139:1110840601"]="미묘한 마법은 우리 세계의 경계를 왜곡시키고 이 영역의 법칙을 약화시켜서는 불가능한 일이 일어나도록 합니다."
rows["139:1190231081"]="내 장능이 3년 동안 라저힐 바라크의 냄새가 난 카 ⁇ 스 덩어리 수프를 먹을 수 있다면,"
rows["139:1213235336"]="내 아들과 농장을 구해줬어 난 영원히 네 빚에 졌어"
rows["139:1226590634"]="그것은 방심하게 설계되었으며 예산 문제와 그 무겁고 비효율적인 \"물리학의 법칙\"을 무시했습니다."
rows["139:1232682452"]="음식이 잘못되었다는 소문 때문에 공황에 빠진 병사들이 늘어갑니다. 이웃들은 음식에 독을 넣었다며 서로 고발하고 있습니다. 도시 전체가 혼란에 빠질 것입니다!"
rows["139:1238629644"]="내가 지시하기 전에 당신은 대회 마운트를 타고 있을 겁니다.$B$B창을 장착하고, 당신의 분단의 대장 밖에서 대회 마운트를 찾아라."
rows["139:1240314878"]="좀비들을 몰래 찾아볼 수 있어?$B$B여기서 절반은 걱정할 게 없어"
rows["139:1244782228"]="트롤, 나한테 대답하지 마. 누가 이 자리에 맡았는지 알잖아. 왜 트롤이 널 대신해 나를 선택했는지 물어본 적 없어?"
rows["139:1298069431"]="스컹크, 토끼, 새끼 사슴이 함께 다닌다니. 매일 볼 광경은 아니군. 뭐 상관없지, 오늘 저녁은 사슴고기다!"
rows["139:1317698330"]="만약 당신이 작은 털이 있는 동물을 총으로 쏘지 않는다면, 어떻게 깨끗하게 유지해 줄 수 있겠죠?"
rows["139:133015957"]="나는 '그들을 끌어들이는 보드브레, 발자국' 그리고 물려, 남쪽의 어떤 집으로. 지금 당신이 서둘러, 당신은 그녀를 도울 수 있습니다, 그녀는 더 많은 것을 알고있을 수도 있습니다."
rows["139:1351053219"]="우린 버나클레를 구해줬어 포세이큰 안개, 배구 돌려!"
rows["139:1355983355"]="이제 더 나아가야 할 시간입니다. 다르나서스년]의 공예인 테라시 안에 위치한 밤 elf인 Telonis은 여러분의 훈련의 다음 단계입니다."
rows["139:1371626532"]="타브레, 당신은 사르도르 섬에 대한 공격의 선두를 맡을 것입니다."
rows["139:1420761640"]=" ⁇ 의 윙글이 주머니의 윙글에서 벗어나지 말고 겨울 베일 축제에 스모키우드 패서즈의 감자들을 사라!"
rows["139:1437153447"]="난 심각하게 다쳤지만 내가 할 수 있는 모든 것을 해줘서 마법을 막는 내 방안에 있어"
rows["139:1437615648"]="호드의 대족장이신 스랄 님과 대군주 가로쉬 헬스크림 님께서 마상시합 광장에 도착하셨습니다! 입구에 이르는 길을 비우십시오!"
rows["139:1443858557"]="이 강도들은 죽은 사람들로부터 옷, 집들로부터 장신, 그리고 동조장으로부터  ⁇ 을 훔쳤어."
rows["139:1454729529"]="차 한 잔을 마시러 온 게 아니잖아 어떻게 이 상황을 벗어날 수 있을지 보자"
rows["139:1485799827"]="드디어 마력의 눈을 말리고스의 세력에서 빼내어 우리가 지배할 수 있게 되었다. 작은 존재여, 그대가 더 가벼워진 것이 아닐 터인데, 저 창공을 날고 싶어 날개가 근질거릴 지경이로다."
