rows["139:1673654968"]="|TInterface\\Icons\\ability_vehicle_demolisherflamecatapult.blp:20|t 호드 함대는 그들의 |cFFFF0000|Hspell:147088|h[폭탄]|h|r를 시작합니다!"
rows["139:1677112971"]="Umbrafen 호수에서 설명한 구조와 비슷해요."
rows["139:1692675861"]="이곳을 빨리 뜨시는 게 좋을 걸요. 여기서는 개구리로 모습이 바뀌는 게 좋은 일 축에 드니까요."
rows["139:1716888600"]=" ⁇ 다라리족은 내가 모르는 암흑 마술을 실천하고 있습니다. 그들은 신비한 힘을 그림자와 섞어 놓습니다."
rows["139:1723646057"]="언젠가 곧, 내 친구, 네가 나처럼 오그릴라 크리스탈을 들고 있을거야. 그리고 네 주변의 세계를 더 잘 이해할 수 있을 거야."
rows["139:178052517"]="여기서 나가고 싶다는 걸 비난하지 않네 꼭대기에 올라서 유적에서 북쪽으로 가"
rows["139:1790577694"]="\"사랑하는 소그리, 당신이 이 글을 읽고 있다면 결국은 늙은 헌장을 따라 사람을 보내기 위해 용기를 얻었음을 의미합니다."
rows["139:1796937383"]="오, 그럴 리가. 일리단은 더 원대한 계획을 실현할 도구이자 하찮은 발판이었을 뿐이다! 바로 지금을 위한... 그리고 이번엔, 너희도 날 방해할 수 없어!"
rows["139:1797565340"]="챔피언들, 환영합니다. 그녀를 쓰러뜨리는 모든 시도는 실패했습니다."
rows["139:1854419885"]="에리스가 주면$B$B눈은 많은 공포와 많은 기적을 보았다.$B$B그것은 보는 사람이 가장 잘 보는 것을 느끼는 것을 보여줍니다."
rows["139:1863952408"]="가끔은 누군가가 무슨 일이 일어나야 한다고 해서 일이 벌어지는데, 역사를 잘 지키기엔 어려움이 있지만"
rows["139:1876423304"]="우리 문화는 오래 살았던 고대 문화입니다.$b$b우리 공예 덕분에 그 문화의 일부 기억은 미래 세대에 보존될 수 있습니다."
rows["139:1919832592"]="토끼발 형제는 똑똑하고 키가 높고 행운과 행운의 냄새가 나지만 그는 내 운 좋은 야크쇼에 대해 콧수염을 토하고 나쁜 농담을 한다."
rows["139:1978840191"]="목사가 되고 싶으세요? 이스트벨 목사 캠프에 목사가 있다고 생각합니다.  "
rows["139:2027491426"]="이 멋진 막대기를 선택하고 선을 조심스럽게 끌고 다른 끝에서 무슨 일이 벌어지는지 알아내게 해"
rows["139:2035961845"]="아니, 전 전투에 도움이 될 예언된 사람을 찾고 있다고 말해줘"
rows["139:2042706403"]="그 고양이들을 때려버린 건 정말 멋지죠. 그들은 \"그레어!\" 하고, 당신은 \"와반그!\" 하고, 그리고 그들의 물건을 가져갔어요."
rows["139:2046780933"]="당신 아버지처럼 약해 보이시죠 오늘 제가 시작한 일을 끝낼 겁니다."
rows["139:2066402314"]="제 형제 브란의 소식이 전해졌어요. 노스렌드년, 그는 울두어를 탐험하면서"
rows["139:2121571607"]="제 전문적인 수준이 넘어서서,  ⁇ 칸의 직물 전문가가 되는 조지오 볼레로도"
rows["139:2140062047"]="오, 정말 멋졌어!$b$b지휘관도 자신감 있고, 그 억양도 꽤 매력적이긴 합니다.$b$b결혼한지 아세요?"
rows["139:215642181"]="골드린의 끈기는 전설의 소재입니다.$B$B모든 군인들이 이 성당을 방문하여 그 종류의 전투 능력을 활용할 수 있기를 희망합니다. "
rows["139:277458355"]="칼림도어의 북쪽 지역에서 큰 폭발이 일어났고, 엘프는 마침내 켈라타라스에서 움직이고 있습니다!"
rows["139:281952463"]="발가드의 맥고이버를 아는 사람 있어요? 제 삼촌이죠. 그분 칭호가 뭔지 알아요? 전문가라고요. 그래요, 그냥 \"전문가\"요. 저도 전문가가 되고 싶어요."
rows["139:285055127"]="이 여신 눈물은 엘룬이 축복해줬고 그들의 힘은 아키몬드의 사악한 마술과 싸우는데 도움이 될 것입니다"
rows["139:295994359"]="저리 좀 비켜요 저들이 저리 보고 싶지 않아요$B$B이 에테리얼들은 자기들이 누구라고 생각하죠?$B$B이건 내 주장이야!"
rows["139:328391990"]="이스크로wn 성당에서 벌어진 전쟁에 따라, 승리는 우리 손에 닿아 있습니다. 리치 왕 그 영광은 호드!"
rows["139:422740165"]="보기에 코루네족은 천 년 전에 썬더 킹에게 충성했지 파다렌들이 이 땅을 통치하기 전에"
rows["139:457929411"]="어떻게? 아니, 불가능해! 너무 조심해서...$B$B거짓말하고, 이제 사기에 죽게 될 거야!"
rows["139:478729664"]="카라잔은 항상 그렇게 비명적이지는 않았죠. 카라잔의 암흑은 메디프의 죽음으로만 일어났습니다."
rows["139:508935281"]="뒤틀린 황천은 프레젤 모양이 있나요? 그리고 네더란 무엇인가요? 고아 모녀는 사람들에게 네더에 대해 묻지 말아야 한다고 말했습니다."
rows["139:51155201"]="이건 뭐야? 이 키버는 양을 원한 적이 없는데? 강한 힘을 가진 무기를 원했건만 고작 이런 양이 되다니. 정말 실망이야."
rows["139:528996192"]="내가 스틸 마스터라면 아마도 스틸 근처에 있을지도 몰라?"
rows["139:530271256"]="늑대들의 피부를 충분히 모았어 곧 기병들이 타고 갈 준비가 되겠지"
rows["139:552524957"]="이 섬에 갇혀있는 당신은 모든 판다리아에서 가장 위험한 생물들을 찾을 것입니다. 당신이 해야 할 경우 탐험, 앤드윈 왕자."
rows["139:566133387"]="|TInterface\\Icons\\ability_warlock_inferno.blp:20|t%s는 적들의 집합에 캐스팅하기 시작합니다 |cFFFF6600|Hspell:100777|h[Magma Geyser]|h|r!"
rows["139:571845365"]="저는 고용된 도움을 찾아야 합니다. 저는 하루 종일 물고기의 물품을 팔고 있는 게 싫어요. 낚시를 하고 물품을 팔는 게 더 좋겠습니다."
rows["139:583373803"]="그럼 모든 용의를 불러 그들이 뭘 계획하든, 그 일이 일어나기 전에 우리가 알 수 있도록 해"
rows["139:586208698"]="전투장에서 경쟁자를 물리쳐야 합니다. 승리에 따라 금메달이 보내질 확률이 높습니다."
rows["139:597540888"]="제 저장고에서 뭘 하고 있었습니까? 요즘은 음식을 안심하고 먹을 수 없는 때입니다. 내 물건을 샅샅이 뒤지는 낯선 이는 정말이지 보고 싶지 않습니다! 저리 꺼지십시오!"
rows["139:597871220"]="저와 얘기를 나누고 싶으신 분은 고해실 칸막이 뒤에서 절 만나실 수 있을 겁니다. 의심, 걱정이나 불확실한 점이라면 무엇이든지 제가 기쁜 마음으로 덜어 드리겠습니다."
rows["139:618128138"]="세포 외상 인덕션, 몇 개의 조직 샘플, 마이크로소닉 심도 유전자 검사를 하는 것 뿐이야"
rows["139:619451201"]="전라남도에서 온 힘을 끌어들이는 이 섬은"
rows["139:680349409"]="마법사의 길을 선택하는 것은 큰 어려움의 길을 선택하는 것입니다. 많은 사람들이 우리를 이해하지 못합니다. 우리 자신의 사람들은 우리의 예술을 받아들이기 위해 투쟁합니다."
rows["139:68548383"]="난 스랑글스톤에서 네싱워리를 처음 만났는데 그 이후로 계속 만나고 있어"
rows["139:705965554"]="한샤시는 스틱을 잘 알고 있습니다. 더 강렬한 강사를 원한다면 썬더 블러프에 가세요. 안세크와는 저 중앙 승강장에서 가르칠 것입니다."
rows["139:709115296"]="블랙록 오크들이 지옥의 불꽃이 호드로 돌아온다는 말을 계속 듣곤 했어요"
rows["139:772364075"]="드디어 이 경관을 점점하는 유적들을 연구할 기회가 생겼습니다."
