rows["139:791034363"]="그리고 당신은? 나는 내 날에 많은 것을 보았다 하지만 당신은 확실히 첫 번째. 거북이 돌아왔습니까?"
rows["139:820190763"]="이 얼라이언스  ⁇ 수꾼들은 정말 용감합니다! 포세이큰 파괴자... 이제 내가 그 말을 들어본다면 자살행동이라고 할 수 있습니다."
rows["139:827286212"]="정말 물어봐야지? 당신은 그를 느끼지 못해? 전능하신 라스타칸 왕은 외교 임무로 그의 종과 손을 보내셨습니까?"
rows["139:846552774"]=" 육신과 근육, 약하지만 자부심. 그들은 마스터의 뚜 ⁇ 을 갈라 dare? 그들은 스캔버스 스터핑 맹목. 운명과 혼란이 서로 연결되어 있다는 것을 발견."
