rows["13:976492354"]="듀커가 망쳤어!"
rows["13:981776944"]="무기의 마스터"
rows["13:993512833"]="그래, 대군"
rows["140:1055866151"]="드디어 내가 기다렸던 보급품이 왔어 스냅글볼트가 요청한 서류를 준비했어"
rows["140:106103426"]="대폭발이 먼지바람에 걸린다고 이해하지만, 무더스프로켓은 비교적 안전해 보이네"
rows["140:1117399762"]="네 무기가 느끼는 굶주림은 앞으로 기다리는 것에 비하면 그림자에 불과하다. 진짜 굶주림을 보고 싶나? 진짜 힘을? 계속 나아가라, 영웅이여! 내가 기다리고 있다."
rows["140:1138565205"]="오븐 근처에 앉아 있지 마 오늘 폭발하지 않았어"
rows["140:1151567516"]="우리는 물의 소리를 따라가며 이 빛나는 계곡에 이르렀습니다.$B$B이 수영장의 물은 우리가 본 다른 물과도 같지 않습니다."
rows["140:1152060388"]="여기 드루이드들은 없는데 스톰윈드 - 경비원한테 물어봐 스톰윈드."
rows["140:1156713383"]="난 네 영웅성을 들었어, 거북이. 그들이 말했어요. 모고 노동 수용소와 농촌에 대한 공격은"
rows["140:1160431010"]="지금에도 적들이 우리 주위에 몰려들어 움직이지 않는 동안"
rows["140:1164837734"]="안녕하세요, 최고장님. 호드 타운카의 공식 멤버이자 지도자로서?"
rows["140:1166184356"]="제 형제들에게 길을 열어주셨다는 것을 알 수 있습니다. 제 형제들과 성전과의 연결은 여전히 강하다."
rows["140:1166367706"]="메스너가 나쁜 놈들을 빨리 죽이고 싶어서 내가 저처럼 빨리 죽였으면 좋겠어 빛 불 공에 맞게?"
rows["140:1211740685"]=" ⁇ 루 고렐루스트는 동쪽의 바락 뒤에 숨어있어요 불타는 군단!"
rows["140:1230527225"]="이런 비공개는 비싸고 우리의 허물을 위해만 쓰지만 축하를 하고 싶다면"
rows["140:123543454"]="요즘은 걱정이 있는 사람들이 도로에서 여행하는 것을 보는 것이 좋네요."
rows["140:1242817675"]="그라이트 스프링스에 오신 것을 환영합니다$b$b이 얼음 트롤들 중 하나를 살아 잡을 수 있다면, 알려줘요"
rows["140:1247237769"]="하늘 새들과 함께 날아가서 타를 찾아서 윈더 라이더 루스트의 꼭대기에 올라가서"
rows["140:1249666162"]="비키가 무기를 던지도록 가르칠 수 있어 다르나서스 더 빨리 가면, 이리니아 월불과 이야기해"
rows["140:1262979077"]="좀 머그먼에게 맡겨서 윤의 집에 가서 먼저 시장에서 일을 끝낼 수 있겠어"
rows["140:1270094249"]="자유의 길은 언제나 비극으로 둘러싸여 있어, 신사님. 우리는 당신을 잃을 위험을 감수할 수 없었어요. 십자군 전쟁은 그러한 타격을 피할 수 없었죠."
rows["140:1311318404"]="난 이 안에 왜기가 있다는 걸 들었어 스톰윈드 사냥 능력으로 유명세를 떨친 사람이 있어"
rows["140:1336617898"]="내 운명을 걱정하지 마라, 브론젠. 시간 안에 신호를 전송하지 못하면, 재창조가 시작되고 말 것이다. 너희의 세상을... 지켜라..."
rows["140:1352930363"]="여기까지 온 건 자넬 보고 싶어서네, 자를! 그랬더니 이런 알 수 없는 곳에 텅텅 빈 오두막집에서 개구리 타령이나 하며 살고 있다니! 절망 그 자체로군!"
rows["140:1385420489"]="무고와 잔다라리들은 천둥왕의 벽 뒤에 서 있습니다. 레이디 제이나가 우리를 통과시킬 계획을 가지고 있습니다."
rows["140:1395384813"]="난 당신 앞에 서 있습니다. 아그라란, 라이알의 딸, 사락의 딸 그리고 나는 자랑스럽게 당신의 부인이 될 것입니다. 이 세상이나 다른 곳에서도요."
rows["140:1399154906"]="난 스다오판의 도움으로 네가 발견한 생물을 이용해서"
rows["140:1403737145"]="날 풀어줄래? 거의 시간 됐어."
rows["140:1436528204"]="오크스, 오크스가 정신을 되찾았어!"
rows["140:1438230370"]="그 거대 칼라마는 기회를 잡지 못했고 베른은 이미 다시 무장하고 또 한번 준비됐어$B$B다시 올 거야$B$B- 알겠지"
rows["140:1469629671"]="지금은 평범한 거북이 덩어리처럼 보일 수도 있지만, 전염병 가두기가 설치되면 질병과 부패와 전염병의 원인이 될 것입니다!"
rows["140:1477085492"]="왜 우리가 명예의 노예가 되어야 할까요? 적들의 아이들을 잠들 때 죽일 수 있는 거죠. 얼라이언스 피!"
rows["140:1493055069"]="우리에게 있는 가장 오래된 용 알 무리도 성숙기까지는 아직 한참이나 남았지만 인내하며 공부한다면 머지않아용군단이 준비될 것이라 확신한다."
rows["140:1507927342"]="저는 조용히 욕을 무시합니다. 저는 제 대왕에게 말하지 않을 것입니다. 왜냐하면 저는 어떤 대가를 치르더라도 평화를 보장해야 하기 때문입니다. 그것은 단지 욕심입니다."
rows["140:1530301024"]="제펠린이 항구로 도착했지, 제가 수감됐고, 그녀가 있는 상태는 아쉽지만 2분 후에 다시 항구에서 출발할 겁니다."
rows["140:153878018"]="그럼 역사에 대한 여러분의 지식을 시험해 보겠습니다. 오브시디안 성당에서 동원 달걀을 지키던 세 명의 젊은 동원 드래크는 누구였을까요?"
rows["140:1558038984"]="그래도 제게서 사랑을 뺏어가지는 마세요. 운명이 연인들을 갈라놓을 때 어떤 비극이 기다리고 있을까요?! 이제... 연극을 시작하겠습니다!"
rows["140:1567071408"]="이 물품이 어디서 왔는지 모르겠지만 어떻게든 마머가 한 번에 온 산을 공격할 방법을 찾았습니다"
rows["140:1626375619"]="내가 진흙 덩어리 바닥을 닦아내지 않을거야!$B$B그 쥐, 무역 왕자와 싸워야 해!"
rows["140:1637199618"]="마법을 줄이는 것은 우리가 지금 얘기하는 동안 검토되고 있습니다. "
rows["140:1638273805"]="한 번, 전 제 상대를 뇌로  ⁇ 었는데, 전복이 전투 중에 떨어졌다는 것을 보고 놀랐고, 그는 어디 있어야 했는지 보지 못했어요."
rows["140:1674569567"]="트롤들, 진짜 트롤들이었지 이야기에서 들었는데 직접 봤을 때"
rows["140:167662013"]="세계 기둥의 마지막 조각이 발견되었습니다. 이 영역이 아제로스로 붕괴되는 것을 막기 위해 우리는 그것을 묶어야만 합니다."
rows["140:1691871391"]="증기 전동 얼라이언스 빙하 해체 노스페어는 이곳을 떠나 동부 왕국에서 바다를 건너 습지인 메네틸 항구로 이동합니다."
rows["140:1699204516"]="만약 그래라면, 여름 휴식시간에 미판은 멋진 선택권을 가지고 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["140:1706158199"]="그 답을 거부한 사람을 알고 있었습니다. 자신의 느낌과 같은 사람들을 위해 집을 지은 위대한 사람이었습니다. 불가능한 것을 선택한 사람이었죠."
rows["140:1717278230"]="마치 내 기억이 안갯속에 가려진 것 같다네. 그에게 무슨 일이 있었는지조차 생각나질 않아. 이것이 혹시 그가 위험에 처한 이유인가?"
rows["140:1720049319"]="이 드레네이 씨는 그림자보존의 죽음의 기사들과 함께 잡혔어요."
rows["140:1734250570"]="내가 그들을 방해하는 동안, 당신은 경비자의 시체에서 계획을 얻습니다."
rows["140:1743569152"]="일반 상품을 찾고 있어요? 2발 마리 (Marli Two-Toes) 가 필요한 걸 가지고 있을 겁니다. 여름 휴식기에 위치하고 있습니다."
rows["140:1754772625"]="내가 조언하는 것은 당신에게 도움이 되지 않습니다. 당신이 토너먼트 마운트를 타고 있지 않으면.$B$B창을 장착하고, 당신의 분당의 대장 앞에서 대회 마운트를 잡으세요."
rows["140:1762759942"]="너희 모두는 영광으로 올라가지 않을 것이다. 왼편을 바라보고 오른편을 바라보라. 마지막 날에 멸망할 것이다. 그러나 너는 불멸할 것이다."
rows["140:1787454814"]="울고 있는 비올릿을 사용하여 우리의 말을 묶어내겠습니다. 우리의 목소리는 제이덴르와 그림자 포지션의 가장 깊은 곳에서도 당신에게 전해질 것입니다."
